window.EMS = {"screens": [{"id": "3.1", "slug": "panel-consolidado", "profile": "gerencial", "device": "desktop", "title": "Panel consolidado", "activeMenu": "Panel consolidado", "breadcrumb": ["Chile", "Portafolio nacional"], "subtitle": "Pantalla de aterrizaje · estado del portafolio en < 3 s (ARQ-07) · drill-down de 3 niveles", "filters": [{"name": "Colorear marcadores por", "default": "Estado de alarma"}, {"name": "Mostrar solo malls con", "default": "Todos"}, {"name": "Período de KPIs", "default": "Mes actual"}], "blocks": [{"type": "map", "col": 0, "colspan": 6, "y": 222, "h": 300, "label": "Nivel 2 — Centro comercial (mapa interactivo)", "meta": "Marcadores por mall · color = estado · tamaño ∝ consumo", "reqs": ["ARQ-05", "DAT-11", "ARQ-07"], "markers": [[0.25, 0.35, "ok"], [0.55, 0.5, "crit"], [0.72, 0.3, "warn"], [0.4, 0.68, "ok"], [0.82, 0.66, "null"]]}, {"type": "legend", "x": 276, "y": 536, "w": 580, "h": 20}, {"type": "planta", "col": 0, "colspan": 6, "y": 560, "h": 314, "label": "Nivel 3 — Tienda / Local / Isla", "meta": "Plano de planta vectorial (provisto por PASA) · hover: consumo [kW] y última alarma", "reqs": ["ARQ-05", "DAT-03", "DAT-11", "ARQ-09"]}, {"type": "kpi", "col": 6, "colspan": 3, "y": 184, "h": 112, "label": "Tarjeta Consumo [MWh]", "value": "1.284", "delta": "▲ 3,2% vs. mes ant. · sparkline 24h", "spark": true, "reqs": ["DAT-22", "DAT-08", "ARQ-07"]}, {"type": "kpi", "col": 9, "colspan": 3, "y": 184, "h": 112, "label": "Tarjeta Costo [UF]", "value": "42.910", "delta": "▲ 1,8% · moneda UF/CLP/USD", "reqs": ["DAT-22", "FIN-07"]}, {"type": "kpi", "col": 6, "colspan": 3, "y": 308, "h": 112, "label": "Intensidad energética", "value": "38", "delta": "kWh/m² · ▼ 0,6% (desde Nivel 2)", "reqs": ["DAT-11", "DAT-22"]}, {"type": "kpi", "col": 9, "colspan": 3, "y": 308, "h": 112, "label": "Cobertura de medición", "value": "96%", "delta": "medidores activos · semáforo ≥95%", "reqs": ["DAT-17", "DAT-06"]}, {"type": "feed", "col": 6, "colspan": 6, "y": 432, "h": 196, "label": "Feed de eventos críticos", "meta": "Solo lectura · últimos 4–5 del nivel activo", "reqs": ["DAT-03", "DAT-27"], "items": [["URGENT", "Sobrecarga transformador — Costanera P2", "crit"], ["WARNING", "Fase desbalanceada — Egaña", "warn"], ["INFO", "Backfill completado — Vespucio", "null"], ["WARNING", "Dato tardío medidor 4471", "warn"]]}, {"type": "panel", "col": 6, "colspan": 6, "y": 642, "h": 98, "label": "Semáforo calidad del dato", "meta": "% reales / estimadas / CNR del período (pills de color)", "reqs": ["DAT-06", "DAT-17"], "subs": ["Reales 88%   ·   Estimadas 9%   ·   CNR 3%", "Aplica desde Nivel 2 (centro comercial) en adelante"]}], "detail": {"descripcion": "Pantalla de aterrizaje al iniciar sesión. Muestra el estado del portafolio completo en menos de 3 segundos (ARQ-07). La información se filtra progresivamente a través de 3 niveles geográficos interactivos accionados desde el mapa: País → Centro comercial → Tienda/Local. Cada clic refina el nivel de detalle y actualiza los KPIs del panel derecho sin saltar niveles.", "componentes": [{"nombre": "Nivel 1 — País", "descripcion": "País fijo en Chile (operación monopaís por ahora); no hay selector de país. Marcadores circulares por cada mall activo.", "reqs": ["ARQ-05", "DAT-11", "ARQ-07"]}, {"nombre": "Nivel 2 — Centro comercial", "descripcion": "Mapa con marcador por mall; color = estado (verde normal / amarillo alerta / rojo crítico / gris sin dato), tamaño proporcional al consumo relativo. Click actualiza KPIs.", "reqs": ["ARQ-05", "DAT-11", "DAT-03"]}, {"nombre": "Nivel 3 — Tienda / Local / Isla", "descripcion": "Al seleccionar un mall y piso se despliega el plano de planta vectorial provisto por PASA; cada tienda/local/isla es un bloque coloreado por estado; hover con nombre, consumo actual [kW] y última alarma.", "reqs": ["ARQ-05", "DAT-03", "DAT-11", "ARQ-09"]}, {"nombre": "Tarjeta Consumo [MWh]", "descripcion": "Consumo total del período en el nivel seleccionado. Variación % vs. mismo período anterior. Mini sparkline de tendencia de las últimas 24 h.", "reqs": ["DAT-22", "DAT-08", "ARQ-07"]}, {"nombre": "Tarjeta Costo [UF]", "descripcion": "Costo acumulado del período. Variación % vs. período anterior. Moneda seleccionable (UF/CLP/USD) según país del nivel activo.", "reqs": ["DAT-22", "FIN-07"]}, {"nombre": "Tarjeta Intensidad energética", "descripcion": "Consumo / superficie arrendada [kWh/m²]. Variación % vs. período anterior. Aplica desde Nivel 2 (mall) en adelante.", "reqs": ["DAT-11", "DAT-22"]}, {"nombre": "Tarjeta Cobertura de medición", "descripcion": "% de medidores activos / total esperado. Semáforo: verde ≥95%, amarillo 85–95%, rojo <85%.", "reqs": ["DAT-17", "DAT-06"]}, {"nombre": "Feed de eventos críticos", "descripcion": "Lista de los últimos 4–5 eventos del nivel activo: severidad (URGENT/WARNING/INFO), hora, descripción breve, zona afectada. Solo lectura en este perfil.", "reqs": ["DAT-03", "DAT-27"]}, {"nombre": "Semáforo calidad del dato", "descripcion": "% lecturas reales / estimadas / CNR del período activo, en pills de color. Aplica desde Nivel 2.", "reqs": ["DAT-06", "DAT-17"]}, {"nombre": "Sistema de colores de estado", "descripcion": "Consistente en todos los niveles y perfiles: verde = operación normal; amarillo = WARNING (sobreconsumo leve, calidad degradada, fase desbalanceada); rojo = alarma crítica (sobrecarga, medidor offline >4 h); gris = sin dato.", "reqs": ["DAT-06", "DAT-03", "DAT-27"]}], "filtros": [{"nombre": "Colorear marcadores por", "opciones": "Estado de alarma / Consumo actual [kW] / Variación consumo % / Cobertura de medición %", "default": "Estado de alarma"}, {"nombre": "Mostrar solo malls con", "opciones": "Todos / Alarma crítica activa / Alerta warning activa / Sin datos", "default": "Todos"}, {"nombre": "Período de KPIs", "opciones": "Hoy / Mes actual / Trimestre / Últimos 12 meses / Rango personalizado", "default": "Mes actual"}], "ux": [{"componente": "Mapa como único punto de entrada (superior-izquierda)", "texto": "El gerente abre esta pantalla para responder una sola pregunta: «¿dónde hay un problema en mi portafolio?». Por eso el mapa ocupa el cuadrante de mayor peso visual —arranque del recorrido de lectura en F— y no una columna lateral: la ubicación geográfica del riesgo es el primer dato que busca, y los marcadores de color le permiten localizar el mall crítico sin leer una sola cifra.", "principio": "Patrón de lectura en F y jerarquía visual: lo urgente ocupa el punto de entrada."}, {"componente": "Retícula 2×2 de tarjetas KPI a la derecha", "texto": "Consumo, costo, intensidad y cobertura se agrupan pegadas entre sí a la derecha del mapa porque el gerente las lee como un solo bloque de «salud del portafolio», no una por una. Alinearlas a la grilla permite comparar sus variaciones % con un barrido vertical del ojo; dispersarlas obligaría a rastrearlas y rompería la lectura en 3 segundos exigida por ARQ-07.", "principio": "Proximidad (Gestalt) y ley de proximidad para agrupar métricas afines."}, {"componente": "Semáforo de color en lugar de texto de estado", "texto": "El estado se codifica primero con color y forma y solo después con texto, porque este perfil escanea decenas de malls en segundos y el color se procesa de forma pre-atenta —más rápido que leer la palabra «crítico»—. Se añade letra y una leyenda fija para no depender únicamente del color y cumplir accesibilidad.", "principio": "Codificación pre-atenta del color; regla de no-solo-color (accesibilidad)."}, {"componente": "Feed de eventos sin botones de acción", "texto": "El feed se ubica debajo de las tarjetas, como información de contexto de segundo nivel, y se muestra en solo lectura: el gerente no gestiona alarmas —eso pertenece al perfil Operacional—, así que se omiten los botones para no ofrecer una acción que el rol no posee y evitar errores de expectativa.", "principio": "Correspondencia entre rol y affordance; el diseño no promete lo que el permiso no permite."}, {"componente": "Drill-down progresivo de 3 niveles", "texto": "La navegación nunca salta niveles (País→Mall→Local): cada clic refina en el mismo lugar y conserva el panel de KPIs a la vista, de modo que el gerente no tiene que recordar dónde estaba. Reducir de 6 a 3 niveles acorta la ruta a la información que este perfil realmente consulta (portafolio y mall), sin obligarlo a atravesar región/ciudad/comuna.", "principio": "Reconocer antes que recordar; minimizar la carga en memoria de trabajo."}, {"componente": "Barra de filtros única y persistente", "texto": "Los cuatro filtros globales viven en una sola barra sobre el contenido, mostrando su valor por defecto entre paréntesis, para que el gerente sepa exactamente qué está viendo sin abrir menús y para que el patrón sea idéntico en todas las pantallas del perfil.", "principio": "Consistencia entre pantallas y visibilidad del estado del sistema."}]}}, {"id": "3.2", "slug": "consumo-jerarquico", "profile": "gerencial", "device": "desktop", "title": "Consumo jerárquico", "activeMenu": "Consumo jerárquico", "breadcrumb": ["Chile", "Costanera Center", "Piso 2"], "subtitle": "Análisis drill-down: mapa + árbol expandible + panel de detalle sincronizados", "filters": [{"name": "Período", "default": "Mes actual"}, {"name": "Métrica principal", "default": "Consumo [MWh]"}, {"name": "Granularidad", "default": "Mensual"}, {"name": "Ordenar malls por", "default": "Mayor consumo"}, {"name": "Comparar con", "default": "Período anterior"}, {"name": "Moneda", "default": "UF"}], "blocks": [{"type": "map", "col": 0, "colspan": 4, "y": 184, "h": 300, "label": "Mapa geográfico (sincronizado)", "meta": "Un solo mapa · País → Centro comercial → Tienda/Local · sincronizado con el árbol", "reqs": ["ARQ-05", "DAT-11", "DAT-03"]}, {"type": "kpi", "col": 7, "colspan": 5, "y": 184, "h": 92, "label": "Consumo del período [MWh]", "value": "1.284", "delta": "▲ 2,1% vs. período anterior", "reqs": ["DAT-22", "DAT-11"]}, {"type": "kpi", "col": 7, "colspan": 5, "y": 288, "h": 92, "label": "Intensidad [kWh/m²]", "value": "38", "delta": "▼ 0,4% vs. período anterior", "reqs": ["DAT-11", "DAT-22"]}, {"type": "kpi", "col": 7, "colspan": 5, "y": 392, "h": 92, "label": "Costo estimado [UF]", "value": "42.910", "delta": "▲ 1,2% vs. período anterior", "reqs": ["FIN-07", "DAT-22"]}, {"type": "tree", "col": 4, "colspan": 3, "y": 184, "h": 300, "label": "Árbol jerárquico expandible", "meta": "3 niveles de sangría", "reqs": ["DAT-11", "DAT-22"], "rows": [[0, "Total país — Chile", null], [1, "Costanera Center", false], [2, "Piso 1", false], [2, "Piso 2", false], [1, "Mallplaza Egaña", false], [1, "Alto Las Condes", false], [1, "Arauco Maipú", false]], "caret": "▾"}, {"type": "bars", "col": 0, "colspan": 12, "y": 502, "h": 150, "label": "Tendencia mensual: mall vs. promedio portafolio", "meta": "Últimos 8–12 meses · detecta anomalías estacionales", "reqs": ["DAT-08", "DAT-22"], "hl": 6}, {"type": "table", "col": 0, "colspan": 12, "y": 668, "h": 212, "label": "Tabla de remarcadores del mall", "meta": "al seleccionar mall sin piso", "reqs": ["DAT-06", "DAT-19", "DAT-17"], "cols": ["ID medidor", "Zona", "Consumo [MWh]", "% del total", "Último valor", "Timestamp", "Estado"], "nrows": 6, "statuscol": true}], "detail": {"descripcion": "Pantalla de análisis drill-down del consumo. Combina el mapa geográfico (panel izquierdo) con un árbol jerárquico expandible (columna central) y un panel de detalle con KPIs y gráficos (columna derecha). La interacción en cualquiera de los tres paneles sincroniza los otros dos. El árbol tiene 3 niveles: Total país → Mall → Piso/zona.", "componentes": [{"nombre": "Nivel 0 — Total país", "descripcion": "Fila raíz sin sangría. Muestra el total [MWh o métrica seleccionada] del país activo y variación % vs. período anterior.", "reqs": ["DAT-22", "ARQ-05"]}, {"nombre": "Nivel 1 — Mall (▸/▾)", "descripcion": "Una fila por mall con punto de color de estado. Consumo [MWh], % del total, variación % (rojo si sube, verde si baja). Click expande y activa el detalle.", "reqs": ["DAT-11", "DAT-22"]}, {"nombre": "Nivel 2 — Piso / zona", "descripcion": "Solo visible al expandir un mall (sangría doble). Nombre, consumo [MWh], variación %, punto de color según alarma. Click profundiza el mapa por niveles hasta la tienda/local y sincroniza el detalle.", "reqs": ["DAT-11", "ARQ-05"]}, {"nombre": "KPIs del mall (3 tarjetas independientes)", "descripcion": "Tres tarjetas separadas —Consumo del período [MWh], Intensidad [kWh/m²] y Costo estimado [UF]—, cada una con su valor y variación % vs. período anterior.", "reqs": ["DAT-22", "DAT-11", "FIN-07"]}, {"nombre": "Gráfico de tendencia mensual", "descripcion": "Barras del mall vs. barras del promedio del portafolio, últimos 8–12 meses. Permite identificar anomalías estacionales.", "reqs": ["DAT-08", "DAT-22"]}, {"nombre": "Tabla de remarcadores", "descripcion": "Al seleccionar el mall (sin piso): ID medidor, zona, consumo [MWh], % del total, último valor, timestamp y estado (activo/offline/CNR/estimado).", "reqs": ["DAT-06", "DAT-19", "DAT-17"]}], "filtros": [{"nombre": "Período", "opciones": "Mes actual / Trimestre / Año en curso / Últimos 12 meses / Rango personalizado (hasta 5 años)", "default": "Mes actual"}, {"nombre": "Métrica principal", "opciones": "Consumo [MWh] / Costo [UF o moneda] / Intensidad [kWh/m²] / Demanda máxima [kW]", "default": "Consumo [MWh]"}, {"nombre": "Granularidad temporal", "opciones": "Mensual / Semanal", "default": "Mensual"}, {"nombre": "Ordenar malls por", "opciones": "Mayor consumo / Mayor costo / Mayor variación % / Nombre A-Z", "default": "Mayor consumo"}, {"nombre": "Mostrar solo malls con", "opciones": "Todos / Alarma crítica / Variación > X% / Sin datos completos", "default": "Todos"}, {"nombre": "Comparar con", "opciones": "Período anterior / Mismo período año anterior / Promedio del portafolio", "default": "Período anterior"}, {"nombre": "Moneda de costos", "opciones": "UF / CLP / USD", "default": "UF"}], "ux": [{"componente": "Un solo mapa por niveles (sin contenedor de planta aparte)", "texto": "La navegación País → Centro comercial → Tienda/Local ocurre dentro del mismo mapa con drill-down, igual que en el Panel consolidado, en vez de mostrar el nivel de piso en un contenedor separado. Así el gerente no ve el mismo objeto de análisis partido en dos tarjetas con niveles de selección distintos: hay una sola fuente de verdad espacial y un único modelo mental de navegación.", "principio": "Consistencia entre pantallas; evitar niveles de selección duplicados en contenedores distintos."}, {"componente": "Tres paneles sincronizados en una vista", "texto": "Mapa, árbol y detalle conviven sin pestañas ni modales porque el gerente compara «dónde» (mapa), «cuánto» (árbol) y «por qué» (detalle) en un mismo golpe de vista. Sincronizar los tres al hacer un solo clic elimina la coordinación manual y evita que pierda el hilo del análisis.", "principio": "Múltiples vistas coordinadas; reducir el costo de interacción."}, {"componente": "Árbol expandible en vez de navegación página-a-página", "texto": "El árbol se expande in situ (▸/▾) y solo el mall pulsado abre sus pisos; los demás no se mueven. Así el gerente mantiene visible el contexto del portafolio completo mientras profundiza, en lugar de abrir una pantalla nueva y perder la referencia de dónde estaba en la jerarquía.", "principio": "Preservar el contexto; revelación progresiva (progressive disclosure)."}, {"componente": "Resaltado en azul-acento de la fila activa", "texto": "El único color saturado de la pantalla es el acento sobre la fila seleccionada, que ata visualmente el árbol con lo que muestran el mapa y el detalle. Al reservar el acento para «lo que estás mirando ahora», el resto queda en gris y la atención no se dispersa.", "principio": "Un único foco de atención; economía del color."}, {"componente": "Barra de comparación como filtro, no como gráfico aparte", "texto": "«Comparar con» (período anterior / año anterior / promedio del portafolio) es un filtro y no una vista separada porque el gerente casi siempre lee una cifra contra su referencia; incorporarlo al mismo panel evita duplicar pantallas y mantiene la variación % siempre en contexto.", "principio": "Comparación en contexto; consistencia con el resto del perfil."}, {"componente": "Tabla de remarcadores al pie", "texto": "El detalle a nivel medidor se coloca al final, en ancho completo y solo cuando se selecciona un mall sin piso: es el dato más granular y el menos frecuente para un gerente, así que ocupa la zona de menor prioridad de lectura pero queda disponible sin cambiar de pantalla.", "principio": "Jerarquía por frecuencia de consulta; lo granular al final del recorrido."}]}}, {"id": "3.3", "slug": "costos-tendencias", "profile": "gerencial", "device": "desktop", "title": "Costos y tendencias", "activeMenu": "Costos y tendencias", "subtitle": "Vista financiera del consumo para control de gestión y proyecciones", "filters": [{"name": "Mall", "default": "Todos"}, {"name": "Período", "default": "Año en curso"}, {"name": "Moneda", "default": "UF"}, {"name": "Agrupación de gráficos", "default": "Por mall"}, {"name": "Ordenar tabla por", "default": "Costo total desc."}, {"name": "Mostrar variación", "default": "Todos"}], "blocks": [{"type": "stackedbars", "col": 0, "colspan": 7, "y": 184, "h": 300, "label": "Barras apiladas mensual — costo [UF]", "meta": "Línea eje secundario: precio medio [UF/MWh] · tooltip con desglose", "reqs": ["DAT-22", "FIN-07"]}, {"type": "waterfall", "col": 7, "colspan": 5, "y": 184, "h": 300, "label": "Waterfall de variación de costo", "meta": "volumen · precio · mix de malls (verde baja, rojo sube)", "reqs": ["DAT-22", "FIN-07"]}, {"type": "table", "col": 0, "colspan": 12, "y": 500, "h": 232, "label": "Tabla de costos por mall (ordenable · exportable CSV/Excel)", "meta": "", "reqs": ["DAT-22", "FIN-07", "DAT-12"], "cols": ["Mall", "Consumo [MWh]", "Precio medio [UF/MWh]", "Costo total", "Variación %", "Proyección cierre"], "nrows": 6}, {"type": "bars", "col": 0, "colspan": 12, "y": 748, "h": 108, "label": "Proyecciones — 2 meses", "meta": "barras con trama diferente · base tendencia últimos 3 meses", "reqs": ["DAT-22", "FIN-07"], "projline": 1}], "detail": {"descripcion": "Vista financiera del consumo para control de gestión y proyecciones. Orientada a directivos y al área de finanzas. Combina la evolución mensual de costos, la descomposición de la variación y una tabla exportable con proyección de cierre.", "componentes": [{"nombre": "Gráfico de barras apiladas mensual", "descripcion": "Eje Y: costo [UF o moneda seleccionada]. Barras apiladas por mall (configurable). Línea superpuesta en eje Y secundario: precio medio de la energía [UF/MWh]. Hover con desglose del costo por componente.", "reqs": ["DAT-22", "FIN-07"]}, {"nombre": "Waterfall chart de variación", "descripcion": "Descompone la variación de costo total entre el período anterior y el actual en: cambio en volumen, cambio en precio y cambio en mix de malls. Barras verdes para reducción, rojas para incremento.", "reqs": ["DAT-22", "FIN-07"]}, {"nombre": "Tabla de costos por mall", "descripcion": "Columnas: mall, consumo [MWh], precio medio [UF/MWh], costo total, variación %, proyección cierre de mes y año. Ordenable por columna. Exportable a CSV/Excel.", "reqs": ["DAT-22", "FIN-07", "DAT-12"]}, {"nombre": "Proyecciones", "descripcion": "Últimos 2 meses con cifras proyectadas (barras con trama diferente), basadas en la tendencia de los últimos 3 meses.", "reqs": ["DAT-22", "FIN-07"]}], "filtros": [{"nombre": "Mall", "opciones": "Multi-selección con buscador", "default": "Todos"}, {"nombre": "Período", "opciones": "Mes actual / Trimestre / Año en curso / Últimos 12 meses / Rango personalizado", "default": "Año en curso"}, {"nombre": "Moneda", "opciones": "UF / CLP / USD (conversión al tipo de cambio del último día disponible)", "default": "UF"}, {"nombre": "Agrupación de gráficos", "opciones": "Por mall / Por tipología de mall", "default": "Por mall"}, {"nombre": "Ordenar tabla por", "opciones": "Cualquier columna (asc/desc)", "default": "Costo total desc."}, {"nombre": "Mostrar solo malls con variación", "opciones": "Todos / >5% / >10% / >20% (campo numérico)", "default": "Todos"}], "ux": [{"componente": "Barras apiladas como pieza principal a la izquierda", "texto": "La evolución mensual del costo es lo que el área de control de gestión revisa primero, así que ocupa el mayor bloque y el punto de entrada de lectura. Apilar por mall en una sola barra por mes permite ver a la vez el total y su composición sin cambiar de gráfico.", "principio": "Jerarquía visual por frecuencia de uso; densidad informativa controlada."}, {"componente": "Waterfall junto a las barras, no en otra pestaña", "texto": "El waterfall responde la pregunta que surge inmediatamente al ver subir el costo: «¿fue volumen, precio o mix?». Colocarlo al lado —no en otra pantalla— permite leer el «cuánto» y el «por qué» en el mismo movimiento ocular, respetando el sentido de lectura izquierda→derecha.", "principio": "Proximidad causa-efecto; patrón de lectura en Z."}, {"componente": "Verde/rojo con dirección explícita en el waterfall", "texto": "En finanzas el color por sí solo es ambiguo (¿rojo es malo o es gasto?), por eso cada barra lleva además el signo de la variación; el color acelera el escaneo pero el texto elimina la interpretación errónea de un ahorro como sobrecosto.", "principio": "Redundancia de codificación; prevención de error de interpretación."}, {"componente": "Tabla exportable al pie, en ancho completo", "texto": "La tabla es el artefacto que finanzas se lleva a su propio análisis, por eso está al final (cierre del recorrido), abarca todo el ancho para mostrar todas las columnas sin scroll horizontal, y expone el CSV/Excel donde se espera terminar la tarea.", "principio": "Coincidencia con el flujo de trabajo real del usuario; visibilidad de la acción de salida."}, {"componente": "Proyección diferenciada por trama, no por color nuevo", "texto": "Las columnas proyectadas usan una trama distinta en vez de un color adicional para no introducir una cuarta categoría cromática que compita con el semáforo; el gerente distingue «dato real» de «estimación» por textura, manteniendo la paleta sobria.", "principio": "Distinción por forma antes que por color; economía de la paleta."}]}}, {"id": "3.4", "slug": "reportes-ejecutivos", "profile": "gerencial", "device": "desktop", "title": "Reportes ejecutivos", "activeMenu": "Reportes ejecutivos", "primaryAction": "Generar reporte", "subtitle": "Generación y descarga de reportes para comités y directorio", "filters": [{"name": "Alcance geográfico", "default": "Portafolio completo"}, {"name": "Período", "default": "Mes actual"}, {"name": "Comparación", "default": "vs. período anterior"}, {"name": "Métrica principal", "default": "Consumo"}, {"name": "Formato de salida", "default": "PDF"}], "blocks": [{"type": "form", "col": 0, "colspan": 7, "y": 184, "h": 300, "label": "Configurador de reporte", "meta": "los filtros determinan el contenido a generar", "reqs": ["FIN-07", "DAT-28"], "fields": ["Alcance geográfico (Portafolio / Mall)", "Período (Mes / Trimestre / Año / Rango)", "Comparación (vs. anterior / año anterior / sin)", "Métrica principal (Consumo / Costo / Intensidad)", "Formato de salida (PDF / PPT / Excel)"]}, {"type": "panel", "col": 0, "colspan": 7, "y": 496, "h": 150, "label": "Secciones a incluir (checkboxes)", "meta": "todas activadas por defecto", "reqs": ["FIN-07", "DAT-28"], "subs": ["☑ KPIs ejecutivos    ☑ Tendencia de consumo    ☑ Ranking de malls", "☑ Análisis de costos    ☑ Calidad del dato    ☑ Resumen de alarmas", "☑ Mapa de cobertura"]}, {"type": "panel", "col": 7, "colspan": 5, "y": 184, "h": 150, "label": "Vista previa del reporte", "meta": "miniatura de portada e índice", "reqs": ["FIN-07"], "subs": ["Portada + logo", "Índice de secciones seleccionadas"]}, {"type": "actions", "col": 7, "colspan": 5, "y": 346, "h": 40, "btns": ["Generar reporte", "Programar envío"]}, {"type": "table", "col": 7, "colspan": 5, "y": 400, "h": 246, "label": "Historial de reportes", "meta": "retención de archivos ≥ 12 meses", "reqs": ["DAT-12", "DAT-08"], "cols": ["Fecha", "Usuario", "Alcance", "Formato", "Estado"], "nrows": 6}], "detail": {"descripcion": "Generación y descarga de reportes para comités y directorio. Permite configurar el contenido (alcance, período, comparación, secciones y formato) antes de generar, y conserva un historial descargable con retención mínima de 12 meses.", "componentes": [{"nombre": "Configurador de reporte", "descripcion": "Filtros que determinan el contenido: alcance geográfico, período, comparación, métrica principal, secciones a incluir y formato de salida (PDF con gráficos / PPT editable / Excel plano).", "reqs": ["FIN-07", "DAT-28", "DAT-08"]}, {"nombre": "Secciones a incluir", "descripcion": "Checkboxes individuales: KPIs ejecutivos, tendencia de consumo, ranking de malls, análisis de costos, calidad del dato, resumen de alarmas del período y mapa de cobertura. Todas activadas por defecto.", "reqs": ["FIN-07", "DAT-28"]}, {"nombre": "Tabla de historial", "descripcion": "Fecha de generación, usuario, alcance, período cubierto, formato, estado (generando/listo/error) y link de descarga. Retención de archivos: 12 meses mínimo.", "reqs": ["DAT-12", "DAT-08"]}], "filtros": [{"nombre": "Alcance geográfico", "opciones": "Portafolio completo / Mall específico (multi-selección con buscador)", "default": "Portafolio completo"}, {"nombre": "Período", "opciones": "Mes / Trimestre / Año / Rango personalizado (hasta 5 años)", "default": "Mes actual"}, {"nombre": "Comparación", "opciones": "vs. período anterior / vs. mismo período año anterior / Sin comparación", "default": "vs. período anterior"}, {"nombre": "Secciones a incluir", "opciones": "KPIs / Tendencia / Ranking / Costos / Calidad / Alarmas / Mapa de cobertura", "default": "Todas activadas"}, {"nombre": "Métrica principal del reporte", "opciones": "Consumo / Costo / Intensidad", "default": "Consumo"}, {"nombre": "Formato de salida", "opciones": "PDF (con gráficos) / PPT (slides editables) / Excel (tablas planas)", "default": "PDF"}], "ux": [{"componente": "Configurador a la izquierda, resultado a la derecha", "texto": "El flujo es «configuro → previsualizo → genero», por eso el formulario ocupa la columna izquierda (primer paso, sentido de lectura) y la vista previa más el historial la derecha (resultado). El gerente avanza de izquierda a derecha sin retroceder.", "principio": "Flujo secuencial alineado al recorrido de lectura; correspondencia con el modelo mental de la tarea."}, {"componente": "Secciones como checkboxes con todo activado", "texto": "Las secciones vienen todas marcadas porque el caso más común es el reporte completo; el gerente resta lo que no quiere en vez de construir desde cero. Es una configuración por defecto inteligente que minimiza clics para el 80% de los casos.", "principio": "Valores por defecto inteligentes; minimizar el esfuerzo del caso frecuente."}, {"componente": "Vista previa antes del botón Generar", "texto": "La miniatura e índice se muestran antes de generar para que el gerente confirme que el reporte es el correcto sin gastar el tiempo de render ni descargar un PDF equivocado; es feedback anticipado sobre una acción costosa.", "principio": "Visibilidad del estado del sistema; prevención de errores antes de una acción cara."}, {"componente": "Botón «Generar» con estilo de acento (CTA primaria)", "texto": "«Generar reporte» es el único botón sólido en acento de la pantalla; «Programar envío» queda como acción secundaria en contorno. Diferenciar la acción principal por peso visual evita que el gerente dude cuál es el paso que cierra la tarea.", "principio": "Jerarquía de acciones (primaria vs. secundaria); ley de Fitts en el objetivo principal."}, {"componente": "Historial con estado y link de descarga", "texto": "El historial expone el estado (generando/listo/error) y el link en la misma fila para que el gerente sepa si un reporte ya está disponible sin reintentar; el estado visible reduce la incertidumbre en generaciones que tardan.", "principio": "Feedback de estado de procesos asíncronos."}]}}, {"id": "3.5", "slug": "alarmas-agregadas", "profile": "gerencial", "device": "desktop", "title": "Alarmas agregadas", "activeMenu": "Alarmas agregadas", "subtitle": "Resumen ejecutivo del estado de alertas del portafolio · vista de gestión, no de operación", "filters": [{"name": "Mall", "default": "Todos"}, {"name": "Período de análisis", "default": "Últimos 7 días"}, {"name": "Severidad", "default": "Todas"}, {"name": "Estado", "default": "Activas"}, {"name": "Gráfico agrupar por", "default": "Día"}], "blocks": [{"type": "kpi", "col": 0, "colspan": 3, "y": 184, "h": 100, "label": "Total alarmas activas", "value": "37", "delta": "en el período filtrado", "reqs": ["DAT-27", "FIN-06"]}, {"type": "kpi", "col": 3, "colspan": 3, "y": 184, "h": 100, "label": "Críticas activas", "value": "5", "delta": "badge rojo si > 0", "reqs": ["DAT-27", "FIN-06"]}, {"type": "kpi", "col": 6, "colspan": 3, "y": 184, "h": 100, "label": "Resueltas 24h", "value": "22", "delta": "últimas 24 horas", "reqs": ["DAT-27"]}, {"type": "kpi", "col": 9, "colspan": 3, "y": 184, "h": 100, "label": "T. medio de resolución", "value": "3,4 h", "delta": "indicador si supera SLA", "reqs": ["FIN-06"]}, {"type": "map", "col": 0, "colspan": 5, "y": 300, "h": 300, "label": "Mapa geográfico de alarmas", "meta": "marcadores SIEMPRE por estado de alarma", "reqs": ["DAT-03", "DAT-27"]}, {"type": "stackedbars", "col": 5, "colspan": 7, "y": 300, "h": 150, "label": "Evolución 30 días", "meta": "abiertas / escaladas / resueltas por día", "reqs": ["DAT-27", "DAT-03"]}, {"type": "panel", "col": 5, "colspan": 7, "y": 466, "h": 134, "label": "Top 5 malls con más alarmas", "meta": "con tendencia ↑/↓/→ vs. semana anterior", "reqs": ["DAT-27", "DAT-11"], "subs": ["1. Costanera Center — 4 crít / 9 warn  ↑", "2. Mallplaza Egaña — 2 crít / 6 warn  →", "3. Vespucio — 1 crít / 5 warn  ↓", "4. Alto Las Condes — 1 crít / 4 warn  ↑", "5. Arauco Maipú — 0 crít / 3 warn  →"]}, {"type": "table", "col": 0, "colspan": 12, "y": 616, "h": 244, "label": "Tabla de alarmas por mall (sin datos de medidores individuales)", "meta": "", "reqs": ["DAT-03", "DAT-11", "FIN-06"], "cols": ["Mall", "Críticas", "Warnings", "Resueltas", "T.medio [h]", "Última alarma"], "nrows": 6, "statuscol": true}], "detail": {"descripcion": "Resumen ejecutivo del estado de alertas del portafolio, sin detalle técnico de medidores individuales. Es una vista de gestión (no de operación): el gerente ve magnitud, tendencia y concentración de alarmas, pero no las gestiona.", "componentes": [{"nombre": "Tarjetas de cabecera", "descripcion": "Total alarmas activas / Críticas activas (badge rojo si >0) / Resueltas en últimas 24 h / Tiempo medio de resolución del período [h] con indicador si supera el SLA.", "reqs": ["DAT-27", "FIN-06"]}, {"nombre": "Mapa geográfico de alarmas", "descripcion": "Misma lógica del Panel consolidado, pero los marcadores se colorean siempre por estado de alarma (ignora la métrica de otras pantallas). Click: panel lateral con resumen del mall.", "reqs": ["DAT-03", "DAT-27"]}, {"nombre": "Gráfico de evolución — 30 días", "descripcion": "Barras apiladas por día: abiertas (rojo) / escaladas (naranja) / resueltas (verde). Hover con conteo exacto por severidad.", "reqs": ["DAT-27", "DAT-03"]}, {"nombre": "Top 5 malls con más alarmas", "descripcion": "Nombre, país, nº críticas, nº warnings y tendencia (↑/↓/→) vs. semana anterior.", "reqs": ["DAT-27", "DAT-11"]}, {"nombre": "Tabla de alarmas por mall", "descripcion": "Mall, críticas activas, warnings activas, resueltas en período, tiempo medio de resolución [h], última alarma (hora y descripción breve). Sin datos de medidores individuales.", "reqs": ["DAT-03", "DAT-11", "FIN-06"]}], "filtros": [{"nombre": "Mall", "opciones": "Multi-selección con buscador", "default": "Todos"}, {"nombre": "Período de análisis", "opciones": "Hoy / Últimas 24h / Últimos 7 días / Últimos 30 días / Rango personalizado", "default": "Últimos 7 días"}, {"nombre": "Severidad", "opciones": "Todas / Solo críticas / Críticas y altas", "default": "Todas"}, {"nombre": "Estado de la alarma", "opciones": "Activas / Resueltas / Todas", "default": "Activas"}, {"nombre": "Gráfico — agrupar por", "opciones": "Día / Semana / Mall", "default": "Día"}], "ux": [{"componente": "Cuatro tarjetas-resumen en la cabecera", "texto": "El gerente necesita una respuesta binaria al entrar: «¿está mi portafolio bajo control?». Las cuatro cifras clave —con la de críticas destacada por un badge— ocupan la primera línea de lectura para dar esa respuesta antes de que el ojo baje a los gráficos.", "principio": "Jerarquía visual en F; la conclusión antes que la evidencia."}, {"componente": "Mapa siempre coloreado por estado de alarma", "texto": "A diferencia de otras pantallas donde el color del marcador es configurable, aquí se fija en «estado de alarma» para eliminar ambigüedad: en la pantalla de alarmas, rojo siempre significa alarma. Quitar esa opción evita que el gerente malinterprete un mapa configurado para otra métrica.", "principio": "Consistencia de significado del color; prevención de error por configuración."}, {"componente": "Evolución 30 días y Top 5 apilados a la derecha", "texto": "Tendencia (¿mejora o empeora?) y concentración (¿qué malls?) responden preguntas de segundo nivel y se agrupan a la derecha, en bloque, para que el gerente pase de «cuántas» a «hacia dónde van» y «dónde se concentran» de arriba hacia abajo.", "principio": "Agrupación por afinidad funcional; secuencia de preguntas del usuario."}, {"componente": "Tabla sin medidores individuales", "texto": "La tabla se detiene deliberadamente a nivel mall: exponer medidores individuales sería ruido para un gerente y competencia del perfil Operacional. Limitar la granularidad protege el foco ejecutivo y respeta la separación de responsabilidades entre perfiles.", "principio": "Minimización de información según el rol; separación de responsabilidades."}, {"componente": "Ausencia de botones de gestión de alarma", "texto": "No hay «Asignar» ni «Cerrar»: esta vista informa, no opera. La ausencia de affordances de acción comunica al gerente que su rol aquí es de supervisión, evitando que intente gestionar algo que corresponde a otro perfil.", "principio": "Affordance acorde al permiso; claridad del rol."}]}}, {"id": "3.6", "slug": "exportar-reportes", "profile": "gerencial", "device": "desktop", "title": "Exportar reportes", "activeMenu": "Exportar reportes", "primaryAction": "Exportar", "subtitle": "Descarga ad-hoc de datos agregados para análisis externo, presentaciones o respaldo", "filters": [{"name": "Tipo de contenido", "default": "Consumos agregados"}, {"name": "Alcance geográfico", "default": "Portafolio completo"}, {"name": "Período", "default": "Mes actual"}, {"name": "Granularidad temporal", "default": "Mensual"}, {"name": "Formato de salida", "default": "Excel"}, {"name": "Moneda de costos", "default": "UF"}], "blocks": [{"type": "form", "col": 0, "colspan": 6, "y": 184, "h": 360, "label": "Configurador de exportación", "meta": "selección de contenido, alcance y formato", "reqs": ["DAT-07", "DAT-12"], "fields": ["Tipo de contenido (multi-selección)", "Alcance geográfico", "Período (hasta 5 años)", "Granularidad temporal (Mensual / Semanal)", "Formato de salida (PDF / Excel / CSV)", "Moneda de costos"]}, {"type": "panel", "col": 6, "colspan": 6, "y": 184, "h": 150, "label": "Resumen de la exportación", "meta": "", "reqs": ["DAT-12"], "subs": ["Contenido: Consumos agregados por mall", "Alcance: Portafolio completo · Período: mes actual", "Granularidad: Mensual · Formato: Excel"]}, {"type": "actions", "col": 6, "colspan": 6, "y": 346, "h": 40, "btns": ["Exportar", "Programar exportación"]}, {"type": "panel", "col": 6, "colspan": 6, "y": 400, "h": 144, "label": "Limitación del perfil gerencial", "meta": "", "reqs": ["DAT-07"], "subs": ["Solo datos agregados por mall y período", "Sin datos crudos de medidores individuales", "Sin información identificable de locatarios", "Para granularidad / trazabilidad / evidencia firmada → perfil Auditor"]}, {"type": "table", "col": 0, "colspan": 12, "y": 560, "h": 300, "label": "Historial de exportaciones", "meta": "", "reqs": ["DAT-12", "DAT-08"], "cols": ["Fecha", "Usuario", "Contenido", "Período", "Formato", "Descarga"], "nrows": 6}], "detail": {"descripcion": "Descarga ad-hoc de datos agregados para análisis externo, presentaciones o respaldo. Permite elegir tipo de contenido, alcance, período, granularidad y formato. Los exports del perfil gerencial contienen únicamente datos agregados por mall y período.", "componentes": [{"nombre": "Configurador del exportador", "descripcion": "Tipo de contenido (consumos agregados / costos y facturación / calidad del dato / cobertura de medición / resumen de alarmas), alcance geográfico, período, granularidad temporal, formato de salida y moneda.", "reqs": ["DAT-07", "DAT-12"]}, {"nombre": "Historial de exportaciones", "descripcion": "Registro de exportaciones realizadas con fecha, usuario, contenido, período, formato y link de descarga.", "reqs": ["DAT-12", "DAT-08"]}, {"nombre": "Limitación del perfil gerencial", "descripcion": "Los exports incluyen solo datos agregados por mall y período; no incluyen datos crudos de medidores ni información identificable de locatarios. Para mayor granularidad, trazabilidad o evidencia firmada se requiere el perfil Auditor.", "reqs": ["DAT-07"]}], "filtros": [{"nombre": "Tipo de contenido", "opciones": "Consumos agregados por mall / Costos y facturación / Calidad del dato / Cobertura de medición / Resumen de alarmas (multi-selección)", "default": "Consumos agregados"}, {"nombre": "Alcance geográfico", "opciones": "Portafolio completo / Mall específico (multi-selección con buscador)", "default": "Portafolio completo"}, {"nombre": "Período", "opciones": "Mes actual / Trimestre / Año en curso / Rango personalizado (hasta 5 años)", "default": "Mes actual"}, {"nombre": "Granularidad temporal", "opciones": "Mensual / Semanal (datos diarios no disponibles en perfil gerencial)", "default": "Mensual"}, {"nombre": "Formato de salida", "opciones": "PDF ejecutivo / Excel / CSV", "default": "Excel"}, {"nombre": "Moneda de costos", "opciones": "UF / CLP / USD", "default": "UF"}], "ux": [{"componente": "Formulario a la izquierda con resumen espejo a la derecha", "texto": "Mientras el gerente arma la exportación en el formulario, el panel «Resumen» refleja en lenguaje natural lo que va a descargar. Ese eco reduce el error de exportar un alcance o período equivocado sin tener que releer cada control.", "principio": "Feedback inmediato del estado; reconocer antes que recordar."}, {"componente": "Aviso de limitación siempre visible", "texto": "La restricción de granularidad no se esconde en un tooltip: se muestra como bloque fijo para que el gerente entienda por qué no ve datos crudos y sepa que la ruta correcta es el perfil Auditor. Explicar el límite en el sitio evita frustración y tickets de soporte.", "principio": "Prevención de errores por expectativa; ayuda en contexto."}, {"componente": "Excel como formato por defecto", "texto": "El valor por defecto es Excel porque es el destino más frecuente de un gerente que arma presentaciones o análisis; ofrecer el formato esperado sin obligar a elegir acelera la tarea del caso común.", "principio": "Valor por defecto inteligente orientado al caso más frecuente."}, {"componente": "Historial de exportaciones al pie", "texto": "El historial en ancho completo al final permite reutilizar o volver a descargar una extracción previa sin reconfigurarla; es memoria del sistema que ahorra repetir trabajo, ubicada al cierre del recorrido por ser de consulta ocasional.", "principio": "El sistema recuerda por el usuario; jerarquía por frecuencia."}, {"componente": "Botón «Exportar» como CTA primaria", "texto": "La acción de salida se distingue en acento sólido frente a «Programar», de contorno, para que el clic que completa la tarea sea el objetivo visual más grande y evidente de la columna derecha.", "principio": "Ley de Fitts; jerarquía primaria/secundaria de acciones."}]}}, {"id": "4.1", "slug": "monitoreo-en-vivo", "profile": "operacional", "device": "desktop", "title": "Monitoreo en vivo", "activeMenu": "Monitoreo en vivo", "subtitle": "Pantalla principal del turno · estado en tiempo real del parque de medidores · refresco cada 15 min · carga < 3 s (ARQ-07)", "filters": [{"name": "Mall", "default": "Todos"}, {"name": "Estado del medidor", "default": "Todos"}, {"name": "Granularidad del histograma", "default": "Horaria"}], "blocks": [{"type": "kpi", "col": 0, "colspan": 3, "y": 184, "h": 100, "label": "Total medidores", "value": "2.480", "delta": "parque completo del portafolio", "reqs": ["ARQ-08"]}, {"type": "kpi", "col": 3, "colspan": 3, "y": 184, "h": 100, "label": "En línea [%]", "value": "94,2%", "delta": "▲ vs. inicio de turno · sparkline 24h", "spark": true, "reqs": ["ARQ-08", "DAT-27"]}, {"type": "kpi", "col": 6, "colspan": 2, "y": 184, "h": 100, "label": "Offline", "value": "38", "delta": "medidores sin conexión", "reqs": ["ARQ-08", "DAT-24"]}, {"type": "kpi", "col": 8, "colspan": 2, "y": 184, "h": 100, "label": "Dato estancado > 4h", "value": "12", "delta": "badge rojo · alerta DAT-24", "reqs": ["DAT-24", "DAT-27"]}, {"type": "kpi", "col": 10, "colspan": 2, "y": 184, "h": 100, "label": "CNR pendientes", "value": "7", "delta": "a la espera de ingreso", "reqs": ["DAT-24"]}, {"type": "map", "col": 0, "colspan": 8, "y": 300, "h": 300, "label": "Mapa / grilla de centros comerciales", "meta": "Tarjeta por mall: nombre, % medidores online, última lectura, semáforo general · click → grilla de medidores", "reqs": ["ARQ-08", "DAT-11", "DAT-19"], "markers": [[0.22, 0.32, "ok"], [0.45, 0.5, "warn"], [0.6, 0.28, "ok"], [0.72, 0.55, "crit"], [0.38, 0.7, "ok"], [0.85, 0.4, "null"]]}, {"type": "table", "col": 0, "colspan": 8, "y": 616, "h": 244, "label": "Grilla de medidores del mall seleccionado", "meta": "se despliega al hacer click en una tarjeta del mapa", "reqs": ["DAT-11", "DAT-19", "ARQ-08"], "cols": ["Serial", "Zona", "Estado", "Último valor", "Timestamp", "Var. vs. día ant."], "nrows": 6, "statuscol": true}, {"type": "histogram", "col": 8, "colspan": 4, "y": 300, "h": 250, "label": "Comportamiento del parque — 24h", "meta": "% medidores online por hora · detecta caídas masivas o parciales", "reqs": ["DAT-27", "DAT-24"]}, {"type": "feed", "col": 8, "colspan": 4, "y": 566, "h": 294, "label": "Feed de eventos recientes", "meta": "cronológico · con timestamp y mall", "reqs": ["DAT-03", "DAT-10", "DAT-19"], "items": [["OFFLINE", "Medidor 4471 pasó a offline — Costanera P2", "crit"], ["ALARMA", "Alarma abierta — sobreconsumo Egaña L14", "warn"], ["BACKFILL", "Backfill completado — Vespucio (gap 2h)", "null"], ["CNR", "CNR ingresada — Alto Las Condes medidor 3120", "null"], ["OFFLINE", "Dato estancado > 4h — Arauco Maipú tablero B", "crit"]]}], "detail": {"descripcion": "Pantalla principal del turno del perfil Operacional. Muestra el estado en tiempo real del parque completo de medidores, actualizado cada 15 minutos, con carga en menos de 3 segundos (ARQ-07). Combina indicadores de cabecera, un mapa/grilla de centros comerciales que abre la grilla de medidores al hacer click, un histograma de comportamiento del parque en las últimas 24 h y un feed cronológico de eventos recientes.", "componentes": [{"nombre": "Indicadores de cabecera (refresco 15 min)", "descripcion": "Total medidores / En línea [%] / Offline / Con dato estancado > 4h (badge rojo, alerta automática DAT-24) / CNR pendientes.", "reqs": ["DAT-24", "DAT-27", "ARQ-08"]}, {"nombre": "Mapa / grilla de centros comerciales", "descripcion": "Tarjeta por mall: nombre, % medidores online, última lectura y semáforo general. Click en la tarjeta despliega la grilla de medidores del mall: serial, zona, estado, último valor, timestamp y variación vs. día anterior.", "reqs": ["ARQ-08", "DAT-11", "DAT-19"]}, {"nombre": "Histograma de comportamiento del parque", "descripcion": "% de medidores online por hora en las últimas 24 h. Permite detectar caídas masivas o parciales y correlacionarlas con eventos externos.", "reqs": ["DAT-27", "DAT-24"]}, {"nombre": "Feed de eventos recientes", "descripcion": "Lista cronológica: medidor pasó a offline, alarma abierta, backfill completado, CNR ingresada. Con timestamp y mall.", "reqs": ["DAT-03", "DAT-10", "DAT-19"]}], "filtros": [{"nombre": "Mall", "opciones": "Selector con buscador", "default": "Todos"}, {"nombre": "Estado del medidor", "opciones": "Todos / Online / Offline / Dato estancado > 4h / CNR pendiente", "default": "Todos"}, {"nombre": "Granularidad del histograma", "opciones": "Horaria / Por turno (8h)", "default": "Horaria"}], "ux": [{"componente": "Cinco indicadores de cabecera en una sola línea", "texto": "Al recibir el turno, el operador escanea la primera línea para saber en segundos cuánto del parque está en riesgo: online, offline, estancado y CNR forman su check de entrada. Se codifica «dato estancado > 4h» con un badge rojo porque es el disparador de la alerta DAT-24 y no debe perderse entre cifras neutras.", "principio": "Visibilidad del estado del sistema; realce del dato accionable por color."}, {"componente": "Mapa/grilla como bloque de mayor peso, arriba-izquierda", "texto": "El mapa de malls ocupa el cuadrante de arranque de lectura porque la primera pregunta del turno es «¿qué mall está caído?». El click abre la grilla de medidores en el mismo lugar, sin cambiar de pantalla, para que el operador profundice al detalle sin perder la vista global del parque.", "principio": "Jerarquía visual y revelación progresiva; conservar el contexto del monitoreo."}, {"componente": "Histograma 24h junto al mapa", "texto": "Poner el histograma de % online por hora al lado del mapa permite distinguir de un vistazo una caída puntual de una masiva: si la curva se hunde a una hora concreta, el operador correlaciona con un evento externo en vez de abrir medidor por medidor.", "principio": "Reconocimiento de patrones sobre inspección manual; datos afines agrupados."}, {"componente": "Feed cronológico en columna lateral", "texto": "El feed corre en tiempo real a la derecha como bitácora viva del turno; cada línea lleva timestamp y mall para que el operador reconstruya la secuencia de fallas sin cruzar reportes. Los eventos críticos (offline, estancado) usan color rojo para saltar por delante de los informativos.", "principio": "Feedback continuo del sistema; escaneabilidad por severidad."}, {"componente": "Filtros de estado en la barra superior", "texto": "Filtrar por «Offline» o «Dato estancado > 4h» desde la barra reduce el parque a solo lo que exige acción, evitando que el operador rastree manualmente entre 2.480 medidores. La granularidad horaria/turno del histograma vive en la misma barra para no fragmentar los controles.", "principio": "Reducción del espacio de búsqueda; consistencia de ubicación de controles."}]}, "live": "En vivo · act. hace 2 min · refresco 15 min", "breadcrumb": ["Chile", "Parque completo"]}, {"id": "4.2", "slug": "alarmas-eventos", "profile": "operacional", "device": "desktop", "title": "Alarmas y eventos", "activeMenu": "Alarmas y eventos", "subtitle": "Gestión operativa de alarmas · lista accionable priorizada por severidad y antigüedad", "filters": [{"name": "Severidad", "default": "Todas"}, {"name": "Mall", "default": "Todos"}, {"name": "Estado", "default": "Abierta"}, {"name": "Rango de fecha", "default": "Hoy"}, {"name": "Responsable asignado", "default": "Todas"}], "blocks": [{"type": "table", "col": 0, "colspan": 7, "y": 184, "h": 676, "label": "Tabla de alarmas", "meta": "orden por defecto: severidad + antigüedad · fila expandible: valor que disparó, baseline esperado, historial de acciones", "reqs": ["DAT-03", "DAT-27", "FIN-05"], "cols": ["ID", "Sev.", "Descripción", "Mall", "Zona/medidor", "Apertura", "Transcurrido", "Responsable", "Estado"], "nrows": 10, "statuscol": true, "expand": true}, {"type": "stackedbars", "col": 7, "colspan": 5, "y": 184, "h": 150, "label": "Resumen de SLA de alarmas", "meta": "% resueltas dentro / fuera del SLA, por severidad y período", "reqs": ["FIN-06", "FIN-05"]}, {"type": "line", "col": 7, "colspan": 5, "y": 350, "h": 270, "label": "Panel de detalle — serie del medidor 48h", "meta": "línea de threshold del valor que disparó la alarma", "reqs": ["DAT-03", "DAT-10", "DAT-23"], "threshold": 0.68}, {"type": "actions", "col": 7, "colspan": 5, "y": 636, "h": 44, "btns": ["Asignar", "Escalar", "Cerrar", "Iniciar backfill"]}, {"type": "form", "col": 7, "colspan": 5, "y": 696, "h": 164, "label": "Comentario de la alarma", "meta": "queda registrado en la pista de auditoría", "reqs": ["DAT-14", "DAT-23"], "fields": ["Comentario del operador (texto libre)"]}], "detail": {"descripcion": "Gestión operativa de alarmas. Presenta una lista accionable ordenada por severidad y antigüedad, un panel de detalle con la serie temporal del medidor y sus acciones (asignar, escalar, cerrar, iniciar backfill), y un resumen del cumplimiento de SLA. Todo comentario queda en la pista de auditoría (DAT-14).", "componentes": [{"nombre": "Tabla de alarmas", "descripcion": "Columnas: ID, severidad (badge), descripción, mall, zona/medidor, fecha de apertura, tiempo transcurrido, responsable asignado y estado. Ordenada por severidad + antigüedad por defecto. Fila expandible: valor que disparó la alarma, baseline esperado e historial de acciones.", "reqs": ["DAT-03", "DAT-27", "FIN-05"]}, {"nombre": "Panel de detalle de alarma", "descripcion": "Gráfico de serie temporal del medidor en las últimas 48 h con línea de threshold. Botones: Asignar / Escalar / Cerrar / Iniciar backfill automático. Campo de comentario que queda en la pista de auditoría.", "reqs": ["DAT-03", "DAT-10", "DAT-14", "DAT-23"]}, {"nombre": "Resumen de SLA de alarmas", "descripcion": "% resueltas dentro del SLA / fuera del SLA, desglosado por severidad y período.", "reqs": ["FIN-06", "FIN-05"]}], "filtros": [{"nombre": "Severidad", "opciones": "Crítica / Alta / Media / Baja (multi-selección)", "default": "Todas"}, {"nombre": "Mall", "opciones": "Multi-selección con buscador", "default": "Todos"}, {"nombre": "Estado", "opciones": "Abierta / Asignada / Escalada / Resuelta / Todas", "default": "Abierta"}, {"nombre": "Rango de fecha", "opciones": "Date picker inicio–fin", "default": "Hoy"}, {"nombre": "Responsable asignado", "opciones": "Mías / Todas / Por técnico (selector)", "default": "Todas"}], "ux": [{"componente": "Tabla ordenada por severidad + antigüedad por defecto", "texto": "La lista llega ya priorizada: crítico y más antiguo arriba, para que el operador ataque en el orden correcto sin ordenar manualmente cada vez que entra. El punto de estado en la primera columna transmite la severidad de forma pre-atenta antes de leer la descripción.", "principio": "Orden por prioridad como valor por defecto; codificación pre-atenta del riesgo."}, {"componente": "Fila expandible en lugar de abrir otra pantalla", "texto": "El valor que disparó la alarma, su baseline y el historial de acciones se despliegan dentro de la misma fila para que el operador confirme el diagnóstico sin abandonar la lista ni perder su posición entre decenas de alarmas del turno.", "principio": "Revelación progresiva; preservar el contexto de la lista de trabajo."}, {"componente": "Panel de detalle con serie 48h y línea de threshold", "texto": "La serie temporal muestra explícitamente la línea de umbral que gatilló la alarma, de modo que el operador vea de un golpe si fue un pico aislado o una tendencia sostenida antes de decidir escalar o cerrar. La evidencia gráfica precede a la acción.", "principio": "Evidencia visible antes de la decisión; correspondencia entre dato y acción."}, {"componente": "Botonera de acción fija (Asignar / Escalar / Cerrar / Iniciar backfill)", "texto": "Las cuatro acciones operativas viven juntas y siempre visibles bajo el gráfico, para que gestionar la alarma sea un solo movimiento sin buscar menús; agruparlas reduce el tiempo de respuesta en un turno de uso intensivo. «Iniciar backfill» queda en la misma fila porque suele seguir al cierre.", "principio": "Agrupación por afinidad de acción; economía de gestos (ley de Fitts)."}, {"componente": "Campo de comentario ligado a la pista de auditoría", "texto": "El comentario se muestra pegado a las acciones y advierte que queda en la auditoría (DAT-14): así el operador sabe que lo que escribe es trazable e inmutable, lo que fomenta notas precisas y desalienta texto informal.", "principio": "Transparencia de las consecuencias; el diseño comunica la trazabilidad."}, {"componente": "Resumen de SLA como cabecera del panel derecho", "texto": "El bloque de % dentro/fuera de SLA por severidad se coloca arriba a la derecha como marco de contexto: recuerda al operador cuánto margen le queda antes de incumplir FIN-06 mientras trabaja cada alarma individual.", "principio": "Mantener la meta visible durante la tarea; contexto de rendimiento persistente."}]}, "primaryAction": "Asignar alarma"}, {"id": "4.3", "slug": "tickets-sla", "profile": "operacional", "device": "desktop", "title": "Tickets y SLA", "activeMenu": "Tickets y SLA", "subtitle": "Seguimiento de tickets de soporte y cumplimiento de SLA · uptime contratado ≥ 99,5% (FIN-06)", "filters": [], "blocks": [{"type": "kpi", "col": 0, "colspan": 4, "y": 184, "h": 120, "label": "Uptime del servicio (30 días)", "value": "99,6%", "delta": "umbral de alerta si < 99,5% · sparkline 30d", "spark": true, "reqs": ["FIN-06", "ARQ-08"]}, {"type": "kpi", "col": 4, "colspan": 4, "y": 184, "h": 120, "label": "Disponibilidad de datos [%]", "value": "97,1%", "delta": "lecturas recibidas / esperadas", "reqs": ["FIN-06", "ARQ-08"]}, {"type": "kpi", "col": 8, "colspan": 4, "y": 184, "h": 120, "label": "T. medio resolución críticas [h]", "value": "3,4 h", "delta": "indicador visual si supera el SLA", "reqs": ["FIN-06"]}, {"type": "line", "col": 0, "colspan": 12, "y": 320, "h": 220, "label": "Evolución de SLA — últimos 3 meses", "meta": "uptime real vs. umbral contratado (99,5%) · puntos de incidente marcados", "reqs": ["FIN-06", "FIN-07"], "threshold": 0.82}, {"type": "tabs", "col": 0, "colspan": 12, "y": 556, "h": 30, "tabs": ["Mis tickets", "Todos", "Por vencer", "Vencidos"], "active": 1}, {"type": "table", "col": 0, "colspan": 12, "y": 602, "h": 258, "label": "Tablero de tickets", "meta": "días restantes en verde · vencidos en rojo", "reqs": ["FIN-05", "FIN-06"], "cols": ["ID", "Descripción", "Tipo", "Prioridad", "Apertura", "Compromiso SLA", "Estado", "Días rest./venc."], "nrows": 6, "statuscol": true}], "detail": {"descripcion": "Seguimiento de tickets de soporte y cumplimiento de SLA para el perfil Operacional. Combina un semáforo permanente de SLA en la cabecera, un gráfico de evolución de uptime contra el umbral contratado del 99,5% y un tablero de tickets con estado y días restantes o vencidos. Cubre los niveles de soporte N1-N2-N3 (FIN-05).", "componentes": [{"nombre": "Semáforo de SLA (cabecera permanente)", "descripcion": "Uptime del servicio (30 días) / Disponibilidad de datos [%] / Tiempo medio de resolución de alarmas críticas [h], cada uno con umbral de alerta visual.", "reqs": ["FIN-06", "ARQ-08"]}, {"nombre": "Tablero de tickets", "descripcion": "ID, descripción, tipo (alarma / CNR / solicitud), prioridad, fecha de apertura, fecha de compromiso SLA, estado y días restantes o vencidos. Filtro rápido: mis tickets / todos / por vencer / vencidos.", "reqs": ["FIN-05", "FIN-06"]}, {"nombre": "Gráfico de evolución de SLA", "descripcion": "Últimos 3 meses: línea de uptime real vs. umbral contratado (99,5%). Puntos de incidente marcados sobre la línea.", "reqs": ["FIN-06", "FIN-07"]}], "filtros": [], "ux": [{"componente": "Semáforo de SLA como cabecera permanente", "texto": "Las tres métricas de SLA encabezan la pantalla y no se ocultan al hacer scroll porque son el marcador contra el que se mide todo el turno: el operador debe saber en todo momento si el uptime sigue por encima del 99,5% comprometido antes de priorizar un ticket. El umbral se marca en el propio indicador para que la lectura sea de aprobado/reprobado, no un número aislado.", "principio": "Persistencia del indicador clave; comparación contra referencia en el propio dato."}, {"componente": "Gráfico de evolución sobre la tabla", "texto": "La línea de uptime vs. umbral se ubica entre el semáforo y el tablero para que el operador entienda la tendencia antes de bajar al detalle: los puntos de incidente marcados enlazan visualmente una caída del gráfico con los tickets que la explican debajo.", "principio": "De lo general a lo particular; relación causa-efecto en el recorrido de lectura."}, {"componente": "Filtro rápido como pestañas, no como dropdown", "texto": "«Mis tickets / Todos / Por vencer / Vencidos» se ofrece como pestañas siempre visibles porque son las vistas que el operador alterna decenas de veces por turno; un solo clic cambia el foco sin abrir un menú, y «Por vencer» queda a la vista como recordatorio de urgencia.", "principio": "Acceso de un clic a estados frecuentes; visibilidad de las opciones de filtrado."}, {"componente": "Columna de días restantes/vencidos con color", "texto": "La última columna traduce la fecha de compromiso a días restantes o vencidos y los pinta verde/rojo, evitando que el operador calcule mentalmente el margen de SLA fecha por fecha; el rojo empuja los vencidos al primer plano de atención.", "principio": "Reducir la carga cognitiva de cálculo; realce del incumplimiento."}, {"componente": "Ausencia de barra de filtros global", "texto": "Esta pantalla no lleva barra de filtros superior porque el filtrado relevante (por estado del ticket) ya vive en las pestañas y el alcance temporal está fijado por el SLA de 30/90 días; añadir filtros globales duplicaría controles y confundiría el modelo mental respecto a las otras pantallas del perfil.", "principio": "Evitar controles redundantes; simplicidad sobre completitud innecesaria."}]}, "primaryAction": "Nuevo ticket"}, {"id": "4.4", "slug": "calidad-backfill", "profile": "operacional", "device": "desktop", "title": "Calidad y backfill", "activeMenu": "Calidad y backfill", "subtitle": "Control de calidad del dato por mall y gestión de backfill · flag de validación real/estimado/erróneo (DAT-06)", "filters": [], "blocks": [{"type": "table", "col": 0, "colspan": 7, "y": 184, "h": 300, "label": "Scorecard de calidad por mall", "meta": "semáforo por fila · tendencia ↑↓ vs. período anterior", "reqs": ["DAT-06", "DAT-17"], "cols": ["Mall", "% Reales", "% Estimadas", "% CNR", "% Backfill compl.", "Tendencia"], "nrows": 8, "statuscol": true}, {"type": "stackedbars", "col": 7, "colspan": 5, "y": 184, "h": 300, "label": "Histograma de calidad — 30 días", "meta": "área apilada por día: real / estimado / CNR / faltante", "reqs": ["DAT-06", "DAT-17", "DAT-27"]}, {"type": "table", "col": 0, "colspan": 7, "y": 500, "h": 300, "label": "Panel de backfill activo", "meta": "procesos en curso · % completado y ETA", "reqs": ["DAT-10"], "cols": ["Medidor", "Tipo de gap", "Período a reponer", "% completado", "ETA"], "nrows": 6, "statuscol": true}, {"type": "actions", "col": 0, "colspan": 7, "y": 816, "h": 40, "btns": ["Lanzar backfill manual"]}, {"type": "feed", "col": 7, "colspan": 5, "y": 500, "h": 356, "label": "Alertas de degradación de calidad", "meta": "medidores que bajaron su % lecturas reales en los últimos 7 días", "reqs": ["DAT-27", "DAT-17"], "items": [["-14%", "Medidor 3120 Egaña — cae a 78% reales · causa: dato tardío", "crit"], ["-9%", "Medidor 4471 Costanera — 83% reales · gateway intermitente", "warn"], ["-6%", "Medidor 2088 Vespucio — 88% reales · causa n/d", "warn"], ["-5%", "Medidor 5510 Maipú — 90% reales · reintentos altos", "warn"]]}], "detail": {"descripcion": "Control de calidad del dato por mall y gestión de backfill. Reúne un scorecard de calidad por mall con semáforo por fila, un histograma de composición de la calidad en 30 días, el panel de procesos de backfill en curso con opción de lanzarlos manualmente y las alertas de degradación de medidores que empeoraron en la última semana.", "componentes": [{"nombre": "Scorecard de calidad por mall", "descripcion": "Tabla: mall, % lecturas reales, % estimadas, % CNR, % backfill completado y tendencia (↑↓) vs. período anterior. Semáforo por fila.", "reqs": ["DAT-06", "DAT-17"]}, {"nombre": "Panel de backfill activo", "descripcion": "Lista de procesos en curso: medidor, tipo de gap, período a reponer, % completado y ETA. Botón para lanzar backfill manual.", "reqs": ["DAT-10"]}, {"nombre": "Histograma de calidad — 30 días", "descripcion": "Área apilada por día: real / estimado / CNR / faltante. Los días problemáticos quedan visibles de un vistazo.", "reqs": ["DAT-06", "DAT-17", "DAT-27"]}, {"nombre": "Alertas de degradación de calidad", "descripcion": "Medidores que bajaron su % de lecturas reales en los últimos 7 días. Lista con delta y causa si está disponible.", "reqs": ["DAT-27", "DAT-17"]}], "filtros": [], "ux": [{"componente": "Scorecard por mall como bloque principal a la izquierda", "texto": "La tabla de calidad por mall ocupa el punto de entrada porque responde la pregunta de rutina del turno —«¿qué mall tiene peor calidad de dato hoy?»—. El semáforo por fila permite barrer verticalmente y detener el ojo solo en las filas ámbar/rojas, sin leer cada porcentaje.", "principio": "Escaneo vertical guiado por color; jerarquía por frecuencia de consulta."}, {"componente": "Histograma de 30 días con composición apilada", "texto": "Apilar real/estimado/CNR/faltante por día deja ver de inmediato los días problemáticos y si la degradación es puntual o sostenida; el operador distingue un incidente de un día contra un deterioro estructural sin abrir series individuales.", "principio": "Comparación de composición a lo largo del tiempo; densidad informativa legible."}, {"componente": "Panel de backfill con acción de lanzamiento adjunta", "texto": "Los procesos de backfill en curso muestran % completado y ETA en tabla, y el botón «Lanzar backfill manual» queda justo debajo para que el operador dispare la reposición del gap que acaba de identificar sin cambiar de módulo. Ver el ETA evita relanzar procesos ya en marcha.", "principio": "Proximidad entre información y acción; prevención de acciones duplicadas."}, {"componente": "Alertas de degradación como lista con delta y causa", "texto": "Los medidores que empeoraron en 7 días se listan con su caída porcentual y la causa cuando existe, ordenados por magnitud del deterioro; así el operador prioriza la intervención por impacto real y no por orden alfabético o de mall.", "principio": "Priorización por magnitud del cambio; información diagnóstica en contexto."}, {"componente": "Coherencia de la codificación real/estimado/CNR", "texto": "El mismo vocabulario de calidad (real / estimado / CNR / faltante) se usa en el scorecard, el histograma y las alertas, de modo que el operador no reinterpreta categorías al pasar de un bloque a otro dentro de la misma pantalla.", "principio": "Consistencia terminológica y de codificación entre componentes."}]}}, {"id": "4.5", "slug": "cnr-pendientes", "profile": "operacional", "device": "desktop", "title": "CNR pendientes", "activeMenu": "CNR pendientes", "subtitle": "Gestión de Consumos No Registrados · certificación de dato manual según norma CNR (DAT-20) · trazabilidad de cargas (DAT-19)", "filters": [], "blocks": [{"type": "kpi", "col": 0, "colspan": 4, "y": 184, "h": 110, "label": "Total CNR abiertas", "value": "41", "delta": "a la espera de resolución", "reqs": ["DAT-20"]}, {"type": "kpi", "col": 4, "colspan": 4, "y": 184, "h": 110, "label": "Con > 7 días sin resolución", "value": "9", "delta": "badge de alerta de antigüedad", "reqs": ["DAT-20"]}, {"type": "kpi", "col": 8, "colspan": 4, "y": 184, "h": 110, "label": "Ingresadas hoy", "value": "6", "delta": "nuevas en el turno", "reqs": ["DAT-20"]}, {"type": "actions", "col": 0, "colspan": 12, "y": 310, "h": 40, "btns": ["Asignar responsable", "Cambiar estado", "Agregar comentario", "Exportar CNR a CSV"]}, {"type": "table", "col": 0, "colspan": 12, "y": 366, "h": 494, "label": "Tabla de CNR", "meta": "fila expandible: detalle, justificación e historial", "reqs": ["DAT-20", "DAT-19", "DAT-14"], "cols": ["ID", "Medidor", "Mall", "Período afectado", "Tipo", "Responsable", "Fecha ingreso", "Estado", "Valor estim. [kWh]"], "nrows": 10, "statuscol": true, "expand": true}], "detail": {"descripcion": "Gestión de los Consumos No Registrados (CNR) pendientes. Muestra indicadores de cabecera sobre el volumen y antigüedad de las CNR abiertas, una tabla accionable con fila expandible por CNR y una barra de acciones para asignar, cambiar estado, comentar o exportar las CNR seleccionadas. Toda operación es trazable (DAT-19, DAT-14).", "componentes": [{"nombre": "Indicadores de cabecera", "descripcion": "Total CNR abiertas / Con > 7 días sin resolución / Ingresadas hoy.", "reqs": ["DAT-20"]}, {"nombre": "Tabla de CNR", "descripcion": "ID, medidor, mall, período afectado, tipo (manual / automático), responsable, fecha de ingreso, estado (pendiente / en revisión / aprobada / rechazada) y valor estimado [kWh]. Fila expandible con detalle, justificación e historial.", "reqs": ["DAT-20", "DAT-19", "DAT-14"]}, {"nombre": "Acciones disponibles", "descripcion": "Asignar responsable / Cambiar estado / Agregar comentario / Exportar CNR seleccionadas a CSV.", "reqs": ["DAT-20", "DAT-12"]}], "filtros": [], "ux": [{"componente": "Tres indicadores de cabecera centrados en la antigüedad", "texto": "Las tarjetas priorizan el conteo de CNR con más de 7 días sin resolución porque la antigüedad es el criterio operativo de riesgo; destacarla junto al total y las del día le dice al operador de inmediato si el backlog está envejeciendo antes de entrar a la tabla.", "principio": "Visibilidad del indicador crítico; jerarquía por urgencia operativa."}, {"componente": "Barra de acciones sobre la tabla, operando sobre la selección", "texto": "Las cuatro acciones se colocan encima de la tabla para que el flujo natural sea seleccionar filas y actuar sobre ellas en lote; agrupar «Asignar / Cambiar estado / Comentar / Exportar» evita que el operador repita la misma operación CNR por CNR en un backlog grande.", "principio": "Acción por lotes sobre selección; economía de interacción."}, {"componente": "Fila expandible con justificación e historial", "texto": "El detalle, la justificación y el historial de cada CNR se abren dentro de la fila porque el operador necesita verificar la evidencia antes de aprobar o rechazar, sin perder de vista el resto del backlog ni abrir una ventana nueva por cada caso.", "principio": "Revelación progresiva; verificación en contexto antes de decidir."}, {"componente": "Estado como columna con punto de color", "texto": "El estado (pendiente / en revisión / aprobada / rechazada) se codifica con el punto de estado de la primera columna, permitiendo separar visualmente lo que espera acción de lo ya resuelto durante el barrido de la tabla.", "principio": "Codificación de estado pre-atenta; separar lo accionable de lo cerrado."}, {"componente": "Exportación a CSV integrada en la misma barra", "texto": "«Exportar CNR a CSV» convive con las acciones de gestión porque forma parte del mismo flujo (traspasar CNR a certificación o respaldo); tenerlo a mano evita que el operador salga a otra pantalla para documentar lo que acaba de revisar.", "principio": "Continuidad del flujo de trabajo; herramientas donde ocurre la tarea."}]}, "primaryAction": "Exportar CNR"}, {"id": "4.6", "slug": "mapa-cobertura", "profile": "operacional", "device": "desktop", "title": "Mapa de cobertura", "activeMenu": "Mapa de cobertura", "subtitle": "Cobertura de medición del portafolio · marcadores por % medidores online · salud de interfaces (ARQ-08)", "filters": [{"name": "Métrica del marcador", "default": "Online %"}], "blocks": [{"type": "map", "col": 0, "colspan": 8, "y": 184, "h": 676, "label": "Mapa interactivo de cobertura", "meta": "marcadores por mall coloreados según % medidores online · hover: nombre, % online, alarmas activas, último dato · click: grilla de medidores", "reqs": ["ARQ-08", "DAT-17", "DAT-11"], "markers": [[0.2, 0.28, "ok"], [0.35, 0.5, "warn"], [0.5, 0.35, "crit"], [0.62, 0.6, "ok"], [0.75, 0.3, "null"], [0.82, 0.62, "warn"], [0.45, 0.75, "ok"]]}, {"type": "table", "col": 8, "colspan": 4, "y": 184, "h": 676, "label": "Panel lateral de lista", "meta": "malls ordenados por % online ascendente (los más problemáticos primero) · buscador por nombre", "reqs": ["DAT-17", "DAT-27"], "cols": ["Mall", "% online", "Alarmas", "Último dato"], "nrows": 12, "statuscol": true}], "detail": {"descripcion": "Vista de cobertura de medición del portafolio para el perfil Operacional. Un mapa interactivo colorea cada mall según su % de medidores online y, al hacer click, abre la grilla de medidores del mall; un panel lateral lista los malls ordenados de peor a mejor cobertura con buscador. El selector de métrica del marcador permite recolorear el mapa por alarmas, última lectura o calidad.", "componentes": [{"nombre": "Mapa interactivo", "descripcion": "Marcadores por mall coloreados según % de medidores online. Hover: popup con nombre, % online, alarmas activas y último dato. Click: grilla de medidores del mall.", "reqs": ["ARQ-08", "DAT-17", "DAT-11"]}, {"nombre": "Panel lateral de lista", "descripcion": "Malls ordenados por % online ascendente (los más problemáticos primero). Buscador por nombre.", "reqs": ["DAT-17", "DAT-27"]}, {"nombre": "Selector de métrica del marcador", "descripcion": "Online % / Alarmas activas / Última lectura / Calidad del dato. Recolorea los marcadores del mapa según la métrica elegida.", "reqs": ["DAT-17", "DAT-06"]}], "filtros": [{"nombre": "Métrica del marcador", "opciones": "Online % / Alarmas activas / Última lectura / Calidad del dato", "default": "Online %"}], "ux": [{"componente": "Mapa como bloque dominante con lista pareada", "texto": "El mapa ocupa dos tercios del ancho porque la cobertura es intrínsecamente geográfica: el operador localiza visualmente los focos rojos de un vistazo. La lista lateral acompaña como índice navegable para quienes prefieren buscar por nombre en vez de rastrear en el mapa.", "principio": "Vistas coordinadas mapa-lista; dos rutas al mismo dato."}, {"componente": "Lista ordenada por % online ascendente", "texto": "El panel lateral pone arriba los malls con peor cobertura porque son los que exigen acción; el operador lee de arriba hacia abajo su cola de trabajo sin ordenar la tabla, y el buscador le permite saltar a un mall concreto cuando llega un reporte específico.", "principio": "Los peores primero; el orden por defecto refleja la prioridad de acción."}, {"componente": "Selector de métrica del marcador en la barra superior", "texto": "Recolorear el mapa por online %, alarmas, última lectura o calidad desde un único selector permite responder distintas preguntas sobre el mismo mapa sin cambiar de pantalla; mantenerlo en la barra deja claro qué significa el color en cada momento.", "principio": "Reutilización de la misma vista con codificación conmutable; claridad del significado del color."}, {"componente": "Hover con popup de resumen antes del click", "texto": "El popup de hover (nombre, % online, alarmas, último dato) entrega el resumen del mall sin comprometer el click, de modo que el operador descarta o confirma un mall antes de abrir su grilla de medidores completa.", "principio": "Previsualización de bajo costo antes de la navegación; feedback anticipado."}, {"componente": "Continuidad con la grilla de medidores de Monitoreo en vivo", "texto": "El click en un marcador abre la misma grilla de medidores que en Monitoreo en vivo, reutilizando un patrón que el operador ya conoce; no aprende una interacción nueva para llegar al detalle desde el mapa de cobertura.", "principio": "Consistencia de interacción entre pantallas del perfil; transferencia de aprendizaje."}]}}, {"id": "5.1", "slug": "mis-ordenes", "profile": "tecnico", "device": "mobile", "navActive": 0, "title": "Mis órdenes", "activeMenu": "Mis órdenes", "subtitle": "Órdenes de trabajo del técnico en terreno · priorizadas por SLA", "filters": [{"name": "Estado", "default": "Pendientes + En curso"}, {"name": "Prioridad", "default": "Todas"}, {"name": "Mall", "default": "Todos"}], "blocks": [{"type": "kpi", "h": 92, "label": "Vencidas (past SLA)", "value": "1", "delta": "badge rojo · atención inmediata", "reqs": ["FIN-05", "DAT-19"]}, {"type": "panel", "h": 84, "label": "Contadores del turno", "meta": "se actualiza al sincronizar", "reqs": ["FIN-05", "DAT-19"], "subs": ["Pendientes 6    ·    En curso 2", "Cerradas hoy 3    ·    Vencidas 1"]}, {"type": "table", "h": 168, "label": "Lista de órdenes", "meta": "orden: prioridad + fecha compromiso · toca una fila", "reqs": ["FIN-05", "DAT-19"], "cols": ["ID", "Tipo", "Prior.", "Estado"], "nrows": 5, "statuscol": true}, {"type": "panel", "h": 108, "label": "Detalle de orden seleccionada", "meta": "OT-2291 · Medidor SN-4471", "reqs": ["DAT-19", "DAT-23", "INT-13"], "subs": ["Problema: sin lectura > 4 h en remarcador", "Ficha del medidor asociado y ubicación", "Historial de intervenciones previas (DAT-23)"]}], "detail": {"descripcion": "Pantalla de aterrizaje del perfil Técnico en terreno (PWA móvil). Muestra las órdenes de trabajo asignadas con indicadores de cabecera, una lista priorizada por severidad y fecha de compromiso, y un panel de detalle con la ficha del medidor asociado y las acciones de gestión de la orden. Diseñada para uso con una mano y señal intermitente.", "componentes": [{"nombre": "Indicadores de cabecera", "descripcion": "Órdenes pendientes / En curso / Cerradas hoy / Vencidas (past SLA). La cifra de vencidas se destaca con badge para dirigir la atención.", "reqs": ["FIN-05", "DAT-19"]}, {"nombre": "Lista de órdenes", "descripcion": "ID, descripción, tipo (mantención / instalación / diagnóstico / CNR), mall, prioridad, fecha de asignación, fecha de compromiso y estado. Ordenada por prioridad + fecha de compromiso por defecto.", "reqs": ["FIN-05", "DAT-19"]}, {"nombre": "Panel de detalle de orden", "descripcion": "Descripción del problema, ficha del medidor asociado, historial de intervenciones previas (DAT-23) y botones: Iniciar / Pausar / Cerrar orden / Registrar intervención.", "reqs": ["DAT-19", "DAT-23", "INT-13"]}], "filtros": [{"nombre": "Estado", "opciones": "Pendientes / En curso / Cerradas / Vencidas / Todas", "default": "Pendientes + En curso"}, {"nombre": "Prioridad", "opciones": "Crítica / Alta / Media / Baja / Todas", "default": "Todas"}, {"nombre": "Mall", "opciones": "Selector con buscador", "default": "Todos"}], "ux": [{"componente": "Tarjeta «Vencidas» aislada en la cabecera", "texto": "El técnico abre la app para decidir qué atender primero, y el único número que altera su ruta del día es cuántas órdenes están vencidas; por eso ocupa la primera tarjeta con badge y no se diluye entre los demás contadores. La conclusión accionable va antes que el resumen.", "principio": "Jerarquía por consecuencia: lo que cambia la decisión se muestra primero."}, {"componente": "Filas de la lista como objetivos táctiles grandes", "texto": "Cada fila es un objetivo alto con el punto de estado a la izquierda porque la lista se toca de pie, con guantes o una sola mano; filas generosas y separadas reducen los toques errados frente al equipo.", "principio": "Ley de Fitts en móvil: objetivos táctiles amplios (≈44 px) y bien espaciados."}, {"componente": "Barra de acciones fija al pie", "texto": "Iniciar / Pausar / Cerrar / Registrar se colocan en la franja inferior, dentro del arco natural del pulgar, para que la acción que cambia el estado de la orden esté siempre al alcance sin reacomodar la mano.", "principio": "Zona del pulgar (thumb zone): las acciones frecuentes viven abajo en móvil."}, {"componente": "Orden por prioridad + compromiso por defecto", "texto": "El sistema ordena la lista para que el técnico no tenga que calcular cuál es más urgente bajo presión de tiempo; la secuencia correcta llega hecha, reduciendo la carga mental en terreno.", "principio": "Valores por defecto que ejecutan el trabajo por el usuario."}, {"componente": "Apilado estricto en una columna", "texto": "A diferencia del escritorio, aquí todo se apila en una sola columna para eliminar el scroll horizontal y la lectura en zigzag cuando la pantalla es pequeña y la conexión es intermitente.", "principio": "Diseño móvil primero: un único eje de lectura vertical."}]}, "mobilePrimary": "Iniciar orden"}, {"id": "5.2", "slug": "activos-medidores", "profile": "tecnico", "device": "mobile", "navActive": 1, "title": "Activos (medidores)", "activeMenu": "Activos (medidores)", "subtitle": "Inventario de medidores y ficha técnica para consulta en terreno", "filters": [{"name": "Mall", "default": "Costanera"}, {"name": "Estado comms", "default": "Todos"}, {"name": "Tipo", "default": "Todos"}, {"name": "Con alarma", "default": "No"}], "blocks": [{"type": "table", "h": 116, "label": "Medidores del mall", "meta": "serial · estado · protocolo · último dato", "reqs": ["INT-14", "DAT-06", "DAT-24"], "cols": ["Serial", "Estado", "Prot.", "Últ. dato"], "nrows": 3, "statuscol": true}, {"type": "form", "h": 158, "label": "Ficha — Identificación", "reqs": ["INT-14", "DAT-23"], "fields": ["Serial / tag / fabricante", "Modelo · firmware · protocolo", "Dirección Modbus/IP · gateway"]}, {"type": "panel", "h": 70, "label": "Ubicación física", "meta": "ref. Estándar Técnico Salas", "reqs": ["INT-14", "ARQ-15"], "subs": ["Tipo de sala · rack / tablero", "Posición en tablero"]}, {"type": "histogram", "h": 104, "label": "Disponibilidad 72 h (barras 15 min)", "meta": "estado de comunicación · reintentos", "reqs": ["INT-13", "INT-10"]}, {"type": "line", "h": 104, "label": "Serie temporal 48 h (gaps marcados)", "meta": "tipo de valor: real / estimado / CNR", "reqs": ["DAT-04", "DAT-06", "DAT-19"]}, {"type": "timeline", "h": 92, "label": "Historial de fallas e intervenciones", "reqs": ["DAT-23", "DAT-19"], "items": ["Offline > 4 h — reintento automático", "Cambio de firmware — técnico", "CNR ingresada — período repuesto"]}], "detail": {"descripcion": "Inventario de medidores accesible desde terreno con búsqueda y filtros, y ficha técnica detallada del medidor seleccionado. La ficha reúne identificación, ubicación física, estado de comunicación con disponibilidad de 72 h, serie temporal de 48 h con gaps marcados por tipo de valor, e historial de fallas e intervenciones.", "componentes": [{"nombre": "Búsqueda y filtros", "descripcion": "Por serial, tag, mall, zona, gateway, protocolo y estado. Filtros: mall / estado de comunicación / tipo / con alarma activa.", "reqs": ["INT-14", "ARQ-15"]}, {"nombre": "Lista de medidores", "descripcion": "Serial, nombre/tag, mall, zona, estado (online / offline / sin dato > 4 h), protocolo (Modbus / DLMS / otro), último dato y timestamp.", "reqs": ["INT-14", "DAT-06", "DAT-24"]}, {"nombre": "Ficha del medidor — Identificación", "descripcion": "Serial, fabricante, modelo, firmware, protocolo, dirección Modbus/IP y gateway asignado.", "reqs": ["INT-14", "DAT-23"]}, {"nombre": "Ficha del medidor — Ubicación física", "descripcion": "Tipo de sala (ref. Estándar Técnico Salas), rack / tablero / posición.", "reqs": ["INT-14", "ARQ-15"]}, {"nombre": "Ficha del medidor — Estado de comunicación", "descripcion": "Timestamp, reintentos e historial de disponibilidad de 72 h en barras de 15 min.", "reqs": ["INT-13", "INT-10"]}, {"nombre": "Ficha del medidor — Serie temporal 48 h", "descripcion": "Serie de las últimas 48 h con gaps marcados y tipo de valor (real / estimado / CNR).", "reqs": ["DAT-04", "DAT-06", "DAT-19"]}, {"nombre": "Ficha del medidor — Historial de fallas", "descripcion": "Fallas e intervenciones registradas sobre el medidor, en orden cronológico.", "reqs": ["DAT-23", "DAT-19"]}], "filtros": [{"nombre": "Mall", "opciones": "Selector con buscador", "default": "Costanera"}, {"nombre": "Estado de comunicación", "opciones": "Todos / Online / Offline / Sin dato > 4 h", "default": "Todos"}, {"nombre": "Tipo", "opciones": "Todos / Remarcador / Sub-medidor", "default": "Todos"}, {"nombre": "Con alarma activa", "opciones": "Sí / No", "default": "No"}], "ux": [{"componente": "Lista compacta arriba, ficha desplegada debajo", "texto": "El técnico primero localiza el medidor y luego lo inspecciona; el layout respeta esa secuencia buscar → seleccionar → inspeccionar en un solo scroll vertical, sin abrir pantallas nuevas que le hagan perder la referencia del equipo que tiene delante.", "principio": "Revelación progresiva: del listado al detalle sin cambiar de contexto."}, {"componente": "Identificación como ficha campo-por-línea", "texto": "Serial, protocolo y dirección Modbus se muestran uno por renglón etiquetado para poder cotejarlos contra el tablero físico sin ambigüedad; en terreno un dígito confundido es una intervención perdida.", "principio": "Reconocimiento sobre recuerdo y correspondencia con el objeto físico."}, {"componente": "Histograma de disponibilidad de 72 h", "texto": "Las barras de 15 min dejan ver de un vistazo si la caída es puntual o sostenida, lo que decide si el técnico revisa el enlace o el equipo; el patrón temporal se lee antes que cualquier cifra.", "principio": "Codificación visual pre-atenta de patrones temporales."}, {"componente": "Serie de 48 h con gaps dibujados explícitamente", "texto": "Los huecos se representan como vacíos, no como ceros, para que el técnico distinga «sin dato» de «consumo nulo» y no diagnostique una falla donde solo faltó la lectura.", "principio": "Hacer visible el estado ausente; prevención de error de interpretación."}, {"componente": "Historial como línea de tiempo al final", "texto": "La cronología de fallas cierra la ficha para que el técnico sepa qué se intentó antes y no repita una intervención ya realizada por otro turno.", "principio": "Continuidad y contexto: el sistema recuerda el historial por el usuario."}, {"componente": "Densidad reducida frente al escritorio", "texto": "La ficha muestra menos elementos por pantalla que su equivalente de estación fija, priorizando lo que se consulta junto al equipo con señal intermitente y evitando saturar una pantalla pequeña.", "principio": "Economía atencional adaptada al contexto móvil."}]}}, {"id": "5.3", "slug": "diagnostico-comms", "profile": "tecnico", "device": "desktop", "title": "Diagnóstico comms", "activeMenu": "Diagnóstico comms", "subtitle": "Dashboard de salud del enlace por medidor · herramientas de diagnóstico y log crudo", "filters": [{"name": "Medidor", "default": "SN-4471"}, {"name": "Mall", "default": "Costanera"}, {"name": "Gateway", "default": "GW-02"}, {"name": "Ventana", "default": "72 h"}], "blocks": [{"type": "kpi", "col": 0, "colspan": 4, "y": 184, "h": 112, "label": "Estado de comunicación", "value": "Intermitente", "delta": "online / offline / intermitente · cambió hace 12 min", "reqs": ["INT-13", "DAT-24"]}, {"type": "kpi", "col": 4, "colspan": 4, "y": 184, "h": 112, "label": "Tasa de éxito 24 h", "value": "92%", "delta": "reintentos 34 · timeouts 8", "reqs": ["INT-13", "INT-10"]}, {"type": "kpi", "col": 8, "colspan": 4, "y": 184, "h": 112, "label": "Último dato recibido", "value": "14:32", "delta": "hace 00:18 · 48,2 kWh", "reqs": ["INT-13", "DAT-24"]}, {"type": "histogram", "col": 0, "colspan": 7, "y": 312, "h": 250, "label": "Histograma de disponibilidad 72 h", "meta": "barras de 15 min · huecos = sin lectura", "reqs": ["INT-13", "INT-10", "DAT-24"]}, {"type": "panel", "col": 7, "colspan": 5, "y": 312, "h": 150, "label": "Herramientas de diagnóstico", "meta": "acción directa sobre el enlace", "reqs": ["INT-13", "INT-10"], "subs": ["Test de conexión al gateway", "Forzar re-intento de lectura", "Ver log de comunicación raw (100 líneas)"]}, {"type": "actions", "col": 7, "colspan": 5, "y": 478, "h": 40, "btns": ["Test de conexión", "Forzar re-lectura", "Ver log raw"]}, {"type": "table", "col": 0, "colspan": 12, "y": 590, "h": 250, "label": "Log de comunicación raw (últimas 100 líneas)", "meta": "solo lectura · exportable", "reqs": ["INT-13", "INT-10"], "cols": ["Timestamp UTC", "Dirección", "Trama / evento", "Resultado"], "nrows": 7, "statuscol": true}], "detail": {"descripcion": "Consola de diagnóstico de comunicaciones por medidor. Reúne el panel de estado del enlace (estado actual, último dato y tasa de éxito de 24 h), el histograma de disponibilidad de 72 h y las herramientas de diagnóstico activo, con acceso al log de comunicación crudo. Orientada a estación de escritorio por el detalle técnico que maneja.", "componentes": [{"nombre": "Panel de diagnóstico", "descripcion": "Estado actual (online / offline / intermitente). Último dato: valor, timestamp y tiempo transcurrido. Tasa de éxito de 24 h: % de intentos exitosos, reintentos y timeouts. Histograma de disponibilidad de 72 h.", "reqs": ["INT-13", "INT-10", "DAT-24"]}, {"nombre": "Histograma de disponibilidad 72 h", "descripcion": "Barras de 15 min; los huecos indican tramos sin lectura, revelando si la falla es puntual o sostenida.", "reqs": ["INT-13", "INT-10", "DAT-24"]}, {"nombre": "Herramientas de diagnóstico", "descripcion": "Test de conexión al gateway, forzar re-intento de lectura y ver el log de comunicación raw (últimas 100 líneas).", "reqs": ["INT-13", "INT-10"]}], "filtros": [{"nombre": "Medidor", "opciones": "Selector por serial / tag", "default": "SN-4471"}, {"nombre": "Mall", "opciones": "Selector con buscador", "default": "Costanera"}, {"nombre": "Gateway", "opciones": "Selector de gateway del mall", "default": "GW-02"}, {"nombre": "Ventana", "opciones": "24 h / 48 h / 72 h", "default": "72 h"}], "ux": [{"componente": "Tres KPIs de estado en la cabecera", "texto": "Estado, tasa de éxito y último dato responden la primera pregunta del técnico —«¿está vivo el enlace?»— antes de que toque ninguna herramienta, de modo que el diagnóstico empieza con el estado visible y no con una acción a ciegas.", "principio": "Visibilidad del estado del sistema."}, {"componente": "Histograma de 72 h como pieza principal", "texto": "El patrón de intermitencia ocupa el bloque de mayor peso porque es lo que dicta qué herramienta usar: una caída sostenida apunta al gateway, una intermitente a la señal. La evidencia manda sobre las acciones.", "principio": "Jerarquía por valor diagnóstico."}, {"componente": "Herramientas separadas de las lecturas", "texto": "Test, forzar y log se agrupan a la derecha, apartados de los indicadores, para que el técnico no confunda «ver el estado» con «actuar sobre el equipo»; leer y modificar viven en zonas distintas.", "principio": "Separación entre información y acción."}, {"componente": "«Forzar re-lectura» ofrecida sin confirmación pesada", "texto": "Reintentar una lectura es seguro y repetible (INT-10), así que se expone como acción directa; la fricción se reserva para lo que no tiene vuelta atrás, no para operaciones inocuas.", "principio": "Coste de interacción proporcional al riesgo de la acción."}, {"componente": "Log crudo al pie, en ancho completo", "texto": "Las 100 líneas de trama son el último recurso del diagnóstico, por eso cierran el recorrido y ocupan todo el ancho, permitiendo leer las tramas completas sin recorte cuando el técnico ya agotó la vista resumida.", "principio": "Jerarquía por frecuencia: el detalle crudo al final del flujo."}]}, "primaryAction": "Probar conexión"}, {"id": "5.4", "slug": "registro-intervencion", "profile": "tecnico", "device": "mobile", "navActive": 3, "title": "Registro de intervención", "activeMenu": "Registro de intervención", "subtitle": "Bitácora firmada e inmutable de la intervención en terreno", "blocks": [{"type": "panel", "h": 66, "label": "Orden asociada", "meta": "OT-2291 · Medidor SN-4471", "reqs": ["DAT-19"], "subs": ["Cierre de intervención en terreno"]}, {"type": "form", "h": 168, "label": "Bitácora de intervención", "reqs": ["DAT-19", "DAT-23"], "fields": ["Tipo de intervención", "Descripción (texto libre)", "Resultado (solucionado / pendiente piezas / escalación)"]}, {"type": "panel", "h": 96, "label": "Adjuntos y firma", "reqs": ["DAT-19", "DAT-23"], "subs": ["Fotos máx. 5 (JPG/PNG) + documentos (PDF)", "☐ Requiere CNR → pre-llena formulario de CNR", "Firma digital del técnico"]}, {"type": "panel", "h": 80, "label": "Inmutabilidad del registro", "meta": "al firmar y guardar", "reqs": ["DAT-19", "CYB-10", "DAT-14"], "subs": ["Timestamp del servidor + usuario + hash de integridad", "No editable una vez firmado"]}], "detail": {"descripcion": "Formulario de bitácora de la intervención realizada en terreno, con adjuntos y firma digital del técnico. Al firmar y guardar, el registro se vuelve inmutable con timestamp del servidor, usuario y hash de integridad, y no puede editarse. Un checkbox permite encadenar el ingreso de CNR.", "componentes": [{"nombre": "Formulario de bitácora", "descripcion": "Tipo de intervención / Descripción (texto libre) / Resultado (solucionado / pendiente piezas / requiere escalación) / Adjuntos: fotos máx. 5 (JPG/PNG) + documentos (PDF) / Firma digital del técnico. El checkbox «requiere CNR» pre-llena el formulario de CNR.", "reqs": ["DAT-19", "DAT-23"]}, {"nombre": "Validaciones e inmutabilidad", "descripcion": "Al guardar: registro inmutable con timestamp del servidor, usuario y hash de integridad. No se puede editar una vez firmado.", "reqs": ["DAT-19", "CYB-10", "DAT-14"]}], "ux": [{"componente": "Formulario corto en una sola columna", "texto": "Se muestran pocos campos apilados a la vez para poder completar la bitácora de pie y con una mano justo al terminar el trabajo, evitando formularios que exijan sentarse o dos manos.", "principio": "Minimizar campos por vista; baja carga de entrada en terreno."}, {"componente": "Resultado como opción cerrada", "texto": "Solucionado / pendiente piezas / escalación se elige de una lista en vez de escribirse, lo que acelera el registro con guantes y estandariza el dato para los tableros aguas abajo.", "principio": "Reconocer sobre escribir; entrada restringida y consistente."}, {"componente": "Bloque de inmutabilidad visible antes de firmar", "texto": "Se advierte explícitamente que el registro no será editable antes de mostrar el botón de firma, para que el técnico revise el contenido sabiendo que no habrá corrección posterior.", "principio": "Prevención de errores; visibilidad de consecuencias irreversibles."}, {"componente": "«Firmar y guardar» como único CTA de acento", "texto": "Un solo botón primario, claramente distinto de «Cancelar», evita firmar por accidente y deja inequívoca la acción que cierra la bitácora.", "principio": "Jerarquía de acciones; una salida primaria inconfundible."}, {"componente": "Checkbox «requiere CNR» que pre-llena el CNR", "texto": "Cuando la intervención implica un consumo no registrado, el checkbox arrastra los datos ya capturados al formulario de CNR sin re-teclearlos, siguiendo el flujo natural del terreno.", "principio": "Continuidad de tarea; evitar el reingreso de datos."}]}, "mobilePrimary": "Firmar y guardar"}, {"id": "5.5", "slug": "ingreso-cnr-manual", "profile": "tecnico", "device": "mobile", "navActive": 3, "title": "Ingreso CNR manual", "activeMenu": "Ingreso CNR manual", "subtitle": "Alta de Consumo No Registrado firmada según norma CNR", "blocks": [{"type": "panel", "h": 66, "label": "Medidor y contexto", "meta": "SN-4471 · Costanera P2", "reqs": ["DAT-20"], "subs": ["Ingreso CNR según norma de Consumos No Registrados"]}, {"type": "form", "h": 168, "label": "Datos del CNR", "reqs": ["DAT-20", "DAT-19"], "fields": ["Período afectado (fecha/hora inicio – fin)", "Valor real [kWh]", "Motivo del CNR"]}, {"type": "form", "h": 124, "label": "Justificación y evidencia", "reqs": ["DAT-20", "DAT-14"], "fields": ["Justificación (texto libre)", "Adjunto de evidencia"]}, {"type": "panel", "h": 78, "label": "Marcado del valor", "reqs": ["DAT-20", "DAT-19"], "subs": ["Se marca 'dato manual — CNR' en todos los dashboards", "Firma digital obligatoria"]}, {"type": "panel", "h": 96, "label": "Restricciones post-firma", "meta": "irreversible", "reqs": ["DAT-20", "DAT-14", "CYB-10"], "subs": ["No se puede retroeditar", "Solo Operacional puede marcar 'en revisión'", "Auditoría: usuario, timestamp, valor anterior"]}], "detail": {"descripcion": "Formulario de ingreso manual de Consumo No Registrado (CNR) siguiendo la norma correspondiente. Captura período afectado, valor real, motivo, justificación, evidencia y firma digital. El valor queda marcado como dato manual — CNR en todos los dashboards y, una vez firmado, no puede retroeditarse.", "componentes": [{"nombre": "Formulario CNR", "descripcion": "Período afectado (fecha/hora inicio – fin) / Valor real [kWh] / Motivo del CNR / Justificación (texto libre) / Adjunto de evidencia / Firma digital. El valor queda marcado como 'dato manual — CNR' en todos los dashboards.", "reqs": ["DAT-20", "DAT-14", "DAT-19"]}, {"nombre": "Restricciones post-firma", "descripcion": "No se puede retroeditar. Solo puede marcarse como 'en revisión' por el perfil operacional. Registra en pista de auditoría: usuario, timestamp y valor anterior si existía.", "reqs": ["DAT-20", "DAT-14", "CYB-10"]}], "ux": [{"componente": "Formulario dividido en dos bloques (datos / justificación)", "texto": "Separar los datos duros del CNR de la justificación y evidencia parte el formulario en unidades más cortas y agrupa campos afines, reduciendo la sensación de trámite largo en una pantalla pequeña.", "principio": "Chunking y agrupación por afinidad."}, {"componente": "Restricciones post-firma explícitas antes del botón", "texto": "El aviso de irreversibilidad se coloca justo antes de la firma para que el técnico entienda que no hay marcha atrás en el mismo momento en que decide confirmar.", "principio": "Prevención de errores en acciones irreversibles."}, {"componente": "Marcado «dato manual — CNR» comunicado en pantalla", "texto": "Se informa que el valor quedará etiquetado como manual en todos los dashboards, alineando la expectativa del técnico con el efecto real del ingreso y evitando que crea que introduce una lectura ordinaria.", "principio": "Visibilidad del efecto del sistema; honestidad sobre la naturaleza del dato."}, {"componente": "Confirmación por firma digital, no un simple guardar", "texto": "La firma eleva el ingreso a un compromiso trazable, proporcional a un dato que altera consumos certificados; guardar sin firma sería demasiado liviano para el peso del acto.", "principio": "Correspondencia entre gravedad del acto y fricción exigida."}, {"componente": "Targets grandes y campo numérico para [kWh]", "texto": "Campos amplios y el tipo de dato adecuado para el valor en kWh reducen los errores de tecleo en terreno, donde una cifra mal ingresada quedaría fijada de forma inmutable.", "principio": "Ley de Fitts; ajuste del control al tipo de dato."}]}, "mobilePrimary": "Firmar CNR"}, {"id": "5.6", "slug": "maestro-medidores", "profile": "tecnico", "device": "desktop", "title": "Maestro de medidores", "activeMenu": "Maestro de medidores", "subtitle": "Alta y edición del maestro de medidores con pista de cambios inmutable", "filters": [{"name": "Mall", "default": "Todos"}, {"name": "Protocolo", "default": "Todos"}, {"name": "Estado del activo", "default": "Activo"}, {"name": "Estado comms", "default": "Todos"}], "blocks": [{"type": "table", "col": 0, "colspan": 7, "y": 184, "h": 360, "label": "Maestro de medidores", "meta": "búsqueda y filtros completos · selecciona para editar", "reqs": ["INT-14", "FIN-02", "FIN-03"], "cols": ["Serial", "Tag", "Mall", "Prot.", "Gateway", "Comms", "Estado activo"], "nrows": 8, "statuscol": true}, {"type": "form", "col": 7, "colspan": 5, "y": 184, "h": 380, "label": "Alta / edición de medidor", "meta": "agrupado por secciones", "reqs": ["INT-14", "ARQ-15", "FIN-03"], "fields": ["Identificación: serial · fabricante · modelo · firmware", "Protocolo", "Comunicación: dirección Modbus/IP · gateway", "Tiempo de muestreo", "Ubicación: mall · zona · tipo de sala", "Rack / tablero", "Factor de multiplicación / constante de medición"]}, {"type": "actions", "col": 7, "colspan": 5, "y": 580, "h": 40, "btns": ["Guardar cambios", "Dar de baja", "Cancelar"]}, {"type": "table", "col": 0, "colspan": 12, "y": 636, "h": 220, "label": "Pista de cambios del maestro (inmutable)", "meta": "campo · valor anterior → valor nuevo · usuario · timestamp", "reqs": ["DAT-23", "DAT-14", "CYB-10"], "cols": ["Timestamp", "Usuario", "Campo", "Valor anterior", "Valor nuevo"], "nrows": 5}], "detail": {"descripcion": "Gestión del maestro de medidores: tabla completa con búsqueda y filtros, formulario de alta / edición agrupado por secciones y pista de cambios inmutable. Permite incorporar nuevos puntos de medida sin consultoría específica (FIN-02 / FIN-03). Pensada para estación de escritorio por el volumen de campos y la precisión requerida.", "componentes": [{"nombre": "Lista y búsqueda del maestro", "descripcion": "Tabla completa: serial, tag, mall, zona, protocolo, gateway, estado comms, fecha de alta y estado del activo (activo / baja / en mantención). Búsqueda y filtros completos.", "reqs": ["INT-14", "FIN-02", "FIN-03"]}, {"nombre": "Formulario de alta / edición", "descripcion": "Identificación (serial, fabricante, modelo, firmware, protocolo). Configuración de comunicación (dirección Modbus/IP, gateway, tiempo de muestreo). Ubicación (mall, zona, tipo de sala, rack, tablero). Factor de multiplicación / constante de medición.", "reqs": ["INT-14", "ARQ-15", "FIN-03"]}, {"nombre": "Pista de cambios del maestro", "descripcion": "Toda modificación registra: campo cambiado, valor anterior, valor nuevo, usuario y timestamp. Inmutable.", "reqs": ["DAT-23", "DAT-14", "CYB-10"]}], "filtros": [{"nombre": "Mall", "opciones": "Selector con buscador", "default": "Todos"}, {"nombre": "Protocolo", "opciones": "Modbus / DLMS / BACnet / Otro / Todos", "default": "Todos"}, {"nombre": "Estado del activo", "opciones": "Activo / Baja / En mantención / Todos", "default": "Activo"}, {"nombre": "Estado de comunicación", "opciones": "Todos / Online / Offline / Sin dato > 4 h", "default": "Todos"}], "ux": [{"componente": "Tabla a la izquierda, formulario a la derecha", "texto": "Es un patrón maestro-detalle: el técnico selecciona un medidor en la lista y lo edita en el panel contiguo sin cambiar de pantalla, manteniendo a la vista el resto del inventario mientras modifica un registro.", "principio": "Patrón maestro-detalle; contexto persistente durante la edición."}, {"componente": "Formulario largo agrupado por secciones", "texto": "Identificación, comunicación, ubicación y medición se ordenan en bloques lógicos que guían el alta paso a paso; agrupar decenas de campos por afinidad evita que un formulario extenso resulte abrumador.", "principio": "Agrupación por afinidad y progresión lógica del formulario."}, {"componente": "«Dar de baja» separado de «Guardar cambios»", "texto": "La acción que retira un activo se distingue visualmente del guardado ordinario para que el técnico no la accione por inercia al confirmar una edición rutinaria.", "principio": "Separación de acciones destructivas; prevención de error."}, {"componente": "Pista de cambios inmutable al pie", "texto": "Mostrar valor anterior → nuevo, usuario y timestamp en la misma pantalla cumple la trazabilidad (DAT-23) y disuade cambios sin registro, porque cada modificación queda expuesta y firmada.", "principio": "Transparencia; rendición de cuentas visible."}, {"componente": "Diseño de escritorio, no de terreno", "texto": "El alta y la edición del maestro son trabajo de precisión con muchos campos, propio de una estación fija; por eso esta pantalla se saca del layout móvil de una columna que sirve para consulta en terreno.", "principio": "Correspondencia dispositivo-tarea."}]}, "primaryAction": "Nuevo medidor"}, {"id": "5.7", "slug": "reglas-transformacion", "profile": "tecnico", "device": "desktop", "title": "Reglas de transformación", "activeMenu": "Reglas de transformación", "subtitle": "Normalización de datos de campo antes de exponerlos por API y dashboards · con simulador", "filters": [{"name": "Medidor", "default": "Todos"}, {"name": "Tipo de regla", "default": "Todas"}, {"name": "Estado", "default": "Activas"}], "blocks": [{"type": "table", "col": 0, "colspan": 7, "y": 184, "h": 300, "label": "Reglas activas por medidor", "meta": "entrada esperada → salida resultante", "reqs": ["INT-05", "DAT-22", "DAT-23"], "cols": ["Medidor", "Tipo de regla", "Entrada", "Salida", "Estado"], "nrows": 6, "statuscol": true}, {"type": "form", "col": 7, "colspan": 5, "y": 184, "h": 200, "label": "Alta / edición de regla", "reqs": ["INT-05", "DAT-22"], "fields": ["Medidor al que aplica", "Tipo (factor / unidad / offset / fórmula)", "Fórmula personalizada (expresión validada)"]}, {"type": "panel", "col": 7, "colspan": 5, "y": 400, "h": 110, "label": "Simulador de valor de prueba", "meta": "en tiempo real, antes de guardar", "reqs": ["INT-05", "DAT-22"], "subs": ["Valor raw: 48 200 Wh", "→ Valor transformado: 48,2 kWh", "Se recalcula al editar la regla"]}, {"type": "panel", "col": 7, "colspan": 5, "y": 526, "h": 100, "label": "Indicador de impacto", "meta": "al editar sobre datos históricos", "reqs": ["INT-05", "DAT-22", "DAT-19"], "subs": ["12 dashboards · 5 exports · 3 alertas afectadas", "Requiere confirmación explícita antes de guardar"]}, {"type": "actions", "col": 7, "colspan": 5, "y": 642, "h": 40, "btns": ["Guardar regla", "Simular", "Cancelar"]}, {"type": "table", "col": 0, "colspan": 12, "y": 700, "h": 160, "label": "Historial de cambios de reglas (inmutable)", "meta": "regla · campo · valor anterior → nuevo · usuario · timestamp", "reqs": ["DAT-23", "DAT-14", "CYB-10"], "cols": ["Timestamp", "Usuario", "Regla", "Campo", "Valor anterior", "Valor nuevo"], "nrows": 4}], "detail": {"descripcion": "Módulo dentro del maestro de medidores para configurar las reglas de normalización de los datos de campo antes de exponerlos por la API y los dashboards (INT-05). Combina la lista de reglas activas, el formulario de alta / edición con simulador de valor de prueba, el indicador de impacto y el historial de cambios inmutable.", "componentes": [{"nombre": "Lista de reglas activas por medidor", "descripcion": "Tabla: medidor (serial/tag), tipo de regla (factor de escala / conversión de unidades / offset / fórmula personalizada), valor de entrada esperado, valor de salida resultante, estado (activa/inactiva), fecha de creación y usuario que la creó.", "reqs": ["INT-05", "DAT-22", "DAT-23"]}, {"nombre": "Formulario de alta / edición de regla", "descripcion": "Medidor al que aplica. Tipo de transformación: factor multiplicador [número], conversión de unidad (ej. Wh → kWh), offset aditivo, fórmula personalizada (expresión validada). Campo de valor de prueba con simulador: ingresa un valor raw y muestra el valor transformado resultante en tiempo real antes de guardar.", "reqs": ["INT-05", "DAT-22"]}, {"nombre": "Historial de cambios de reglas", "descripcion": "Toda modificación registra: regla afectada, campo cambiado, valor anterior, valor nuevo, usuario y timestamp. Inmutable. Permite al auditor verificar cuándo y por qué cambió una regla de conversión.", "reqs": ["DAT-23", "DAT-14", "CYB-10"]}, {"nombre": "Indicador de impacto", "descripcion": "Al editar una regla: aviso de cuántos dashboards, exports y alertas activas se ven afectados por el cambio. Solicita confirmación explícita antes de guardar cambios sobre medidores con datos históricos.", "reqs": ["INT-05", "DAT-22", "DAT-19"]}], "filtros": [{"nombre": "Medidor", "opciones": "Selector por serial / tag", "default": "Todos"}, {"nombre": "Tipo de regla", "opciones": "Factor de escala / Conversión de unidades / Offset / Fórmula personalizada / Todas", "default": "Todas"}, {"nombre": "Estado", "opciones": "Activas / Inactivas / Todas", "default": "Activas"}], "ux": [{"componente": "Simulador de valor de prueba junto al formulario", "texto": "Mostrar el valor transformado en tiempo real mientras se define la regla convierte una conversión abstracta en un resultado verificable; el técnico comprueba que 48 200 Wh se vuelven 48,2 kWh antes de comprometer nada.", "principio": "Feedback inmediato; prevención de errores antes de guardar."}, {"componente": "Indicador de impacto antes de confirmar", "texto": "Avisar cuántos dashboards, exports y alertas dependen de la regla da al técnico el alcance real del cambio, para que decida sabiendo a cuántos consumidores del dato afecta.", "principio": "Visibilidad de consecuencias; decisión informada."}, {"componente": "Confirmación explícita sobre datos históricos", "texto": "Cambiar una conversión reescribe la interpretación de datos pasados, así que el sistema exige una confirmación deliberada cuando el medidor ya tiene historia, elevando la fricción justo donde el error es irreversible.", "principio": "Fricción proporcional al riesgo; salvaguarda ante acción irreversible."}, {"componente": "Lista con entrada → salida visible por fila", "texto": "Ver el par esperado en cada regla permite auditar de un vistazo si una transformación hace lo previsto, sin abrir el detalle de cada una.", "principio": "Transparencia del comportamiento y escaneabilidad."}, {"componente": "Historial inmutable al pie", "texto": "El registro de quién cambió qué y cuándo permite al auditor reconstruir el porqué de una conversión meses después, cumpliendo CYB-10 y cerrando la pantalla con la evidencia de gobierno del dato.", "principio": "Trazabilidad; memoria del sistema."}, {"componente": "«Guardar» y «Simular» como acciones distintas", "texto": "Simular no compromete y guardar sí; separarlas evita que el técnico persista una regla que solo quería probar, distinguiendo la exploración del compromiso.", "principio": "Distinción entre exploración y compromiso."}]}, "primaryAction": "Nueva regla"}, {"id": "6.1", "slug": "calidad-datos", "profile": "auditor", "device": "desktop", "title": "Calidad de datos", "activeMenu": "Calidad de datos", "subtitle": "Verificación de la calidad del dato por mall · solo lectura · todo acceso queda registrado (DAT-14)", "filters": [{"name": "Mall", "default": "Todos"}, {"name": "Período", "default": "Último trimestre"}, {"name": "Granularidad", "default": "Mensual"}, {"name": "Umbral de calidad", "default": "95%"}], "blocks": [{"type": "table", "col": 0, "colspan": 12, "y": 184, "h": 300, "label": "Scorecard de calidad por mall", "meta": "Solo lectura · semáforo por fila · exportable a CSV", "reqs": ["DAT-06", "DAT-17"], "cols": ["Mall", "Período", "Lecturas esperadas", "Reales (# / %)", "Estimadas (# / %)", "CNR (# / %)", "Faltantes (# / %)", "Tendencia"], "nrows": 6, "statuscol": true}, {"type": "line", "col": 0, "colspan": 7, "y": 500, "h": 300, "label": "Evolución de calidad — % lecturas reales", "meta": "Por mall seleccionado · últimos 12 meses o rango configurado", "reqs": ["DAT-17", "DAT-08"], "threshold": 0.72}, {"type": "table", "col": 7, "colspan": 5, "y": 500, "h": 300, "label": "Medidores con baja calidad", "meta": "Al seleccionar un mall · % reales < umbral", "reqs": ["DAT-06", "DAT-17"], "cols": ["Medidor", "% reales", "Causa más frecuente", "Estado"], "nrows": 8, "statuscol": true, "expand": true}], "detail": {"descripcion": "Pantalla de verificación de la calidad del dato para el auditor externo. Es de solo lectura y todo acceso queda registrado (DAT-14). Presenta un scorecard por mall con el desglose de lecturas reales, estimadas, CNR y faltantes; la evolución del porcentaje de lecturas reales en el tiempo; y, al seleccionar un mall, el detalle de los medidores que caen por debajo del umbral de calidad configurado.", "componentes": [{"nombre": "Scorecard de calidad por mall", "descripcion": "Tabla con mall, período, total de lecturas esperadas, lecturas reales (# y %), estimadas (# y %), CNR (# y %), faltantes (# y %) y tendencia vs. período anterior. Semáforo por fila. Exportable a CSV.", "reqs": ["DAT-06", "DAT-17"]}, {"nombre": "Gráfico de evolución de calidad", "descripcion": "Línea del % de lecturas reales por mes para el mall seleccionado, con línea de umbral. Últimos 12 meses o el rango configurado. Permite detectar deterioros sostenidos de la calidad.", "reqs": ["DAT-17", "DAT-08"]}, {"nombre": "Detalle de medidores con baja calidad", "descripcion": "Al hacer clic en un mall: lista de medidores cuyo % de lecturas reales cae bajo el umbral configurado, con la causa más frecuente si está disponible. Fila expandible con el histórico del medidor.", "reqs": ["DAT-06", "DAT-17"]}], "filtros": [{"nombre": "Mall", "opciones": "Selector de mall (buscador)", "default": "Todos"}, {"nombre": "Período", "opciones": "Rango personalizado hasta 5 años", "default": "Último trimestre"}, {"nombre": "Granularidad", "opciones": "Mensual / Diaria", "default": "Mensual"}, {"nombre": "Umbral de alerta de calidad", "opciones": "Campo numérico % (ej. < 95%)", "default": "95%"}], "ux": [{"componente": "Scorecard como bloque principal a ancho completo", "texto": "El auditor no busca un titular sino la evidencia completa: el scorecard ocupa toda la franja superior para mostrar de una vez las cuatro categorías de calidad (real / estimada / CNR / faltante) con su conteo y porcentaje, de modo que la cifra y su base convivan en la misma fila y no haya que confiar en un porcentaje sin ver de cuántas lecturas sale.", "principio": "Visibilidad de los datos crudos tras cada indicador; no pedir confianza ciega en una métrica agregada."}, {"componente": "Conteo absoluto junto al porcentaje en cada celda", "texto": "Cada categoría muestra el número (#) y el porcentaje a la vez porque un 5% de CNR significa cosas distintas sobre 200 o sobre 200.000 lecturas; para verificar cumplimiento el auditor necesita el denominador visible y no una proporción descontextualizada.", "principio": "Relación parte-todo explícita; prevención de interpretación errónea de porcentajes."}, {"componente": "Umbral configurable dibujado sobre la línea de evolución", "texto": "El límite de aceptación (95% por defecto) se traza como línea en el gráfico y como filtro editable, para que el auditor fije el criterio contra el que audita y vea de inmediato qué meses lo cruzan, en lugar de comparar mentalmente cada punto contra un número recordado.", "principio": "Reconocer antes que recordar; el criterio de evaluación es visible, no memorizado."}, {"componente": "Detalle de medidores solo al descender desde el mall", "texto": "La lista de medidores problemáticos aparece a la derecha únicamente cuando el auditor selecciona un mall del scorecard; encadenar el detalle al agregado le permite pasar del hallazgo («este mall incumple») a la prueba («estos medidores lo causan») sin cambiar de pantalla ni perder el caso que está revisando.", "principio": "Revelación progresiva desde el agregado hacia la evidencia individual."}, {"componente": "Ausencia total de controles de edición", "texto": "En toda la pantalla no hay ningún botón que modifique una lectura o su flag: el rol es de verificación, no de corrección. La ausencia deliberada de affordances de escritura le confirma al auditor que lo que ve es el dato tal como quedó registrado y que nadie puede alterarlo desde aquí.", "principio": "Correspondencia rol-affordance; la inmutabilidad se comunica quitando, no explicando."}]}}, {"id": "6.2", "slug": "cuadratura-agregacion", "profile": "auditor", "device": "desktop", "title": "Cuadratura de agregación", "activeMenu": "Cuadratura de agregación", "subtitle": "Reconciliación remarcador general vs. suma de sub-medidores · consistencia de agregación (DAT-16)", "filters": [], "blocks": [{"type": "table", "col": 0, "colspan": 12, "y": 184, "h": 274, "label": "Tabla de reconciliación", "meta": "Remarcador general vs. suma sub-medidores · desglose por zona / piso", "reqs": ["DAT-16"], "cols": ["Zona / Piso", "Remarcador general [kWh]", "Suma sub-medidores [kWh]", "Diferencia [kWh]", "Diferencia [%]", "Dentro de tolerancia (±2%)"], "nrows": 7, "statuscol": true}, {"type": "bars", "col": 0, "colspan": 7, "y": 474, "h": 246, "label": "Análisis de desviaciones — diferencia mensual", "meta": "Últimos 12 meses · barras fuera de tolerancia resaltadas", "reqs": ["DAT-16", "DAT-08"], "hl": 8}, {"type": "table", "col": 7, "colspan": 5, "y": 474, "h": 246, "label": "Meses fuera de tolerancia", "meta": "Con enlace a datos crudos del período", "reqs": ["DAT-16", "DAT-08"], "cols": ["Mes", "Diferencia %", "Estado", "Datos crudos"], "nrows": 5, "statuscol": true}, {"type": "panel", "col": 0, "colspan": 8, "y": 736, "h": 120, "label": "Exportación firmada de la reconciliación", "meta": "Sello de integridad para adjuntar a la evidencia", "reqs": ["DAT-12", "DAT-07", "CYB-10"], "subs": ["Metadatos incluidos: usuario · fecha y hora de consulta", "Hash SHA-256 de integridad: 9f2c…a71b (visible antes de descargar)", "La cuadratura descargada queda cerrada e íntegra: cualquier alteración rompe el hash"]}, {"type": "actions", "col": 8, "colspan": 4, "y": 772, "h": 40, "btns": ["Descargar reconciliación firmada", "Verificar hash"]}], "detail": {"descripcion": "Pantalla de cuadratura que verifica el requisito DAT-16: la suma de los sub-medidores (locatarios) debe coincidir con el medidor general (remarcador) dentro de una tolerancia configurable (±2% por defecto). Muestra la reconciliación con desglose por zona/piso, el análisis histórico de las desviaciones y una exportación firmada con hash SHA-256 para cerrar la evidencia.", "componentes": [{"nombre": "Tabla de reconciliación", "descripcion": "Por zona/piso: remarcador general [kWh], suma de sub-medidores [kWh], diferencia [kWh] y [%], y bandera «dentro de tolerancia» (sí/no) contra el umbral configurable (ej. ±2%).", "reqs": ["DAT-16"]}, {"nombre": "Análisis de desviaciones", "descripcion": "Gráfico de barras con la diferencia mensual de los últimos 12 meses, resaltando los meses fuera de tolerancia, junto a una tabla de esos meses con enlace directo a los datos crudos del período.", "reqs": ["DAT-16", "DAT-08"]}, {"nombre": "Exportación firmada", "descripcion": "Descarga de la reconciliación con metadatos (usuario, fecha de consulta) y hash SHA-256 de integridad, para adjuntar como evidencia verificable.", "reqs": ["DAT-12", "DAT-07", "CYB-10"]}], "filtros": [], "ux": [{"componente": "Diferencia expresada en kWh y en % lado a lado", "texto": "Cada fila muestra la brecha en unidad absoluta y relativa a la vez, porque la tolerancia se define en porcentaje pero el descuadre se investiga en energía; ofrecer ambas evita que el auditor tenga que calcular a mano y le deja cotejar directamente la diferencia contra el umbral del que depende el veredicto.", "principio": "Datos en la unidad de la decisión; eliminar cálculo mental del flujo de verificación."}, {"componente": "Columna «dentro de tolerancia» con veredicto explícito", "texto": "La última columna resuelve la pregunta central de la pantalla —cuadra o no cuadra— con un sí/no y color, en vez de dejar que el auditor lo deduzca de la cifra. Colocar el juicio como dato explícito y no implícito acelera el barrido de decenas de zonas y hace autoevidente dónde mirar.", "principio": "Hacer explícito el estado del sistema; reducir la carga de inferencia."}, {"componente": "Enlace de cada mes fuera de tolerancia a sus datos crudos", "texto": "Los meses descuadrados no terminan en una alerta: cada uno enlaza a los datos crudos que lo originaron, para que el auditor recorra la cadena descuadre → período → lectura sin reconstruir la ruta manualmente. La evidencia queda a un clic del hallazgo.", "principio": "Trazabilidad accionable; el hallazgo y su prueba conectados."}, {"componente": "Hash SHA-256 mostrado antes de descargar", "texto": "El hash de integridad se exhibe en pantalla junto a los metadatos, no solo dentro del archivo, para que el auditor pueda registrar el sello en su bitácora y verificar después que el documento que presenta es exactamente el que consultó. La integridad es comprobable a simple vista.", "principio": "Verificabilidad de la evidencia; el sello es visible, no está enterrado."}, {"componente": "Exportación firmada como cierre del recorrido", "texto": "El bloque de descarga se ubica al pie, tras la reconciliación y su análisis, porque materializa el resultado del trabajo: primero el auditor verifica, luego se lleva la prueba sellada. Situar la salida al final alinea la pantalla con la secuencia natural de la tarea de auditoría.", "principio": "Correspondencia con el flujo de trabajo real; la acción de cierre al término del recorrido."}]}, "primaryAction": "Exportar firmado"}, {"id": "6.3", "slug": "pista-auditoria", "profile": "auditor", "device": "desktop", "title": "Pista de auditoría", "activeMenu": "Pista de auditoría", "subtitle": "Registro inmutable de acciones · sin edición ni borrado · retención 12 meses con integridad (CYB-10)", "filters": [{"name": "Usuario", "default": "Todos"}, {"name": "Tipo de acción", "default": "Todas"}, {"name": "Recurso afectado", "default": "Todas"}, {"name": "Rango de fechas", "default": "Últimos 30 días"}], "blocks": [{"type": "timeline", "col": 0, "colspan": 7, "y": 184, "h": 620, "label": "Timeline de eventos (inmutable)", "meta": "Cronología inversa · sin botones de edición ni borrado · retención 12 meses", "reqs": ["DAT-14", "DAT-23", "CYB-10"], "items": ["14:32 · j.pardo · Exportación · Reconciliación Costanera · IP 200.14.x · sesión #A72", "14:05 · sistema · Modificación · Regla de escala medidor 4471 · 1.0→1.02 · sesión ETL", "11:20 · m.rios · Consulta · Datos crudos Egaña (mar-2026) · IP 190.x · sesión #B14", "09:58 · a.soto · Login · SSO Azure AD · MFA ok · IP 200.x", "ayer 18:41 · j.pardo · Modificación · CNR medidor 3320 · valor ant. 812 → 840 kWh", "ayer 16:03 · c.vera · Exportación · Paquete de evidencia Alto Las Condes · sesión #C09"]}, {"type": "actions", "col": 0, "colspan": 7, "y": 820, "h": 40, "btns": ["Exportar CSV completo", "Verificar integridad de la pista"]}, {"type": "heatmap", "col": 7, "colspan": 5, "y": 184, "h": 300, "label": "Resumen de actividad — acciones por día y hora", "meta": "7 días × 24 horas · densidad = nº de acciones", "reqs": ["DAT-14", "CYB-10"], "cols": 24, "rowsn": 7}, {"type": "table", "col": 7, "colspan": 5, "y": 500, "h": 360, "label": "Top 10 usuarios por nº de acciones", "meta": "En el período filtrado", "reqs": ["DAT-14", "CYB-10"], "cols": ["Usuario", "Nº de acciones", "Última acción"], "nrows": 10}], "detail": {"descripcion": "Pista de auditoría inmutable que registra cada acción sobre el sistema con retención de 12 meses e integridad garantizada (CYB-10). Presenta un timeline en orden cronológico inverso —sin ningún control de edición o borrado— y un resumen de actividad con heatmap por día/hora y el ranking de los 10 usuarios más activos del período filtrado.", "componentes": [{"nombre": "Timeline de eventos (inmutable)", "descripcion": "Lista cronológica inversa: timestamp, usuario, acción, recurso afectado, valor anterior/posterior (para modificaciones), IP/sesión. No hay botones de edición ni borrado. Exportable completo a CSV.", "reqs": ["DAT-14", "DAT-23", "CYB-10"]}, {"nombre": "Resumen de actividad", "descripcion": "Heatmap de acciones por día y hora que revela patrones y picos de actividad, más el Top 10 de usuarios por número de acciones en el período filtrado.", "reqs": ["DAT-14", "CYB-10"]}], "filtros": [{"nombre": "Usuario", "opciones": "Selector de usuario del portafolio", "default": "Todos"}, {"nombre": "Tipo de acción", "opciones": "Consulta / Modificación / Exportación / Login / Todas", "default": "Todas"}, {"nombre": "Recurso afectado", "opciones": "Medidor / CNR / Configuración / Todas", "default": "Todas"}, {"nombre": "Rango de fechas", "opciones": "Date picker (hasta 12 meses de retención)", "default": "Últimos 30 días"}], "ux": [{"componente": "Timeline sin ningún control de edición ni borrado", "texto": "El registro se presenta como una columna de eventos que solo se pueden leer: no existe un ícono de lápiz, papelera o menú contextual en ninguna fila. Esa ausencia es el mensaje —la pista es append-only— y le da al auditor la certeza de que lo que ve es lo que ocurrió, sin posibilidad de que alguien lo haya retocado desde la interfaz.", "principio": "La inmutabilidad se hace creíble eliminando toda affordance de escritura, no con un cartel."}, {"componente": "Orden cronológico inverso por defecto", "texto": "Lo más reciente encabeza la lista porque la pregunta habitual del auditor es «¿qué pasó último?» y porque investigar un incidente suele empezar por el presente y retroceder. Fijar ese orden evita reordenar en cada visita y da un punto de entrada estable.", "principio": "Valor por defecto alineado a la tarea dominante; consistencia del punto de entrada."}, {"componente": "Valor anterior → posterior en la misma línea de modificación", "texto": "Cuando la acción es una modificación, la fila muestra el antes y el después juntos (ej. 812 → 840 kWh); ver ambos estados sin abrir un detalle permite juzgar de un vistazo la magnitud y el sentido del cambio, que es justo lo que el auditor debe evaluar.", "principio": "Contexto completo en la unidad de lectura; el cambio se entiende sin navegación adicional."}, {"componente": "Heatmap día × hora como lectura de patrones", "texto": "El resumen usa una matriz de color porque el auditor busca lo anómalo —accesos de madrugada, ráfagas de exportación— y una cuadrícula de densidad delata esos patrones de forma pre-atenta, algo imposible de ver recorriendo miles de filas del timeline una por una.", "principio": "Codificación pre-atenta para detección de anomalías; la vista agregada complementa al registro lineal."}, {"componente": "Exportar CSV completo y verificar integridad al pie del timeline", "texto": "Las dos acciones —llevarse el registro y comprobar que no fue alterado— se colocan bajo el timeline, que es su objeto; separarlas del ranking evita que el auditor las confunda con acciones sobre el resumen y refuerza que operan sobre la pista íntegra.", "principio": "Proximidad entre acción y objeto; agrupación por afinidad funcional."}]}, "primaryAction": "Exportar CSV"}, {"id": "6.4", "slug": "trazabilidad-lineage", "profile": "auditor", "device": "desktop", "title": "Trazabilidad / lineage", "activeMenu": "Trazabilidad / lineage", "subtitle": "Linaje de cada lectura y comparación raw vs. mostrado · verificación de no manipulación (DAT-20)", "filters": [], "blocks": [{"type": "panel", "col": 0, "colspan": 12, "y": 184, "h": 236, "label": "Panel de linaje por lectura", "meta": "Cadena de origen del valor mostrado en la plataforma · solo lectura", "reqs": ["DAT-19", "DAT-20", "DAT-14"], "subs": ["Valor mostrado: 840 kWh · tipo: CNR (dato manual)", "Si real → timestamp medidor · gateway · hora de ingesta · transformaciones aplicadas", "Si estimado → método de estimación · período cubierto", "Si CNR → usuario · timestamp · valor original · justificación", "Si backfill → proceso · período repuesto · calidad resultante"]}, {"type": "table", "col": 0, "colspan": 6, "y": 436, "h": 410, "label": "Valor crudo del medidor (raw)", "meta": "Lado izquierdo de la comparación · inmutable, solo lectura", "reqs": ["DAT-20", "DAT-19"], "cols": ["Timestamp UTC", "Valor raw", "Unidad", "Flag calidad"], "nrows": 10, "statuscol": true}, {"type": "table", "col": 6, "colspan": 6, "y": 436, "h": 410, "label": "Valor procesado → mostrado en dashboard", "meta": "Lado derecho · cada transformación identificada", "reqs": ["DAT-20", "DAT-19"], "cols": ["Timestamp UTC", "Valor procesado", "Transformación aplicada", "Valor en dashboard"], "nrows": 10, "statuscol": true}], "detail": {"descripcion": "Pantalla de trazabilidad que reconstruye el linaje de cada lectura y permite verificar que los datos no fueron manipulados manualmente (DAT-20). El panel superior describe la cadena de origen del valor mostrado según su tipo (real / estimado / CNR / backfill); debajo, una comparación lado a lado enfrenta el valor crudo del medidor con el valor procesado y el que finalmente aparece en el dashboard, identificando cada transformación aplicada.", "componentes": [{"nombre": "Panel de linaje por lectura", "descripcion": "Valor mostrado en la plataforma y su tipo. Si es real: timestamp del medidor, gateway, hora de ingesta y transformaciones aplicadas. Si es estimado: método y período cubierto. Si es CNR: usuario, timestamp, valor original y justificación. Si es backfill: proceso, período y calidad.", "reqs": ["DAT-19", "DAT-20", "DAT-14"]}, {"nombre": "Comparación raw vs. mostrado", "descripcion": "Tabla lado a lado: valor crudo del medidor / valor procesado / valor en el dashboard, con cada transformación intermedia identificada explícitamente.", "reqs": ["DAT-20", "DAT-19"]}], "filtros": [], "ux": [{"componente": "Comparación en dos tablas contiguas raw | procesado", "texto": "El crudo y el mostrado se enfrentan en dos columnas pegadas, fila a fila y con el mismo timestamp, porque el auditor coteja valor contra valor: alinearlos horizontalmente convierte la pregunta «¿este número salió de aquel?» en un simple barrido lateral, sin saltar entre pantallas ni memorizar cifras.", "principio": "Comparación lado a lado; minimizar la distancia entre los datos que se contrastan."}, {"componente": "Cada transformación nombrada en su propia celda", "texto": "Entre el valor raw y el del dashboard se explicita qué operación se aplicó (factor de escala, conversión de unidad, offset), en lugar de mostrar solo el resultado. Hacer visible el paso intermedio es lo que permite verificar que la diferencia es una regla legítima y no una manipulación silenciosa.", "principio": "Transparencia del proceso; toda transformación es auditable, ninguna es una caja negra."}, {"componente": "Panel de linaje adaptado al tipo de dato", "texto": "La cadena que se muestra cambia según el valor sea real, estimado, CNR o backfill, porque cada origen exige comprobar cosas distintas —una estimación pide su método; un CNR pide quién y por qué lo ingresó—. Mostrar solo los campos pertinentes evita ruido y dirige la verificación a lo que realmente importa en cada caso.", "principio": "Revelación contextual; el contenido se ajusta al objeto que se audita."}, {"componente": "CNR con valor original y justificación siempre a la vista", "texto": "Cuando la lectura es un dato manual (CNR), el panel expone el valor original, el usuario y la justificación registrada, no solo el valor final. Conservar el rastro completo del dato intervenido es la esencia de la trazabilidad: el auditor ve qué había antes de la mano humana.", "principio": "Preservación del rastro de intervención; nada se sobrescribe sin dejar huella."}, {"componente": "Toda la vista en solo lectura", "texto": "Ni el panel de linaje ni las tablas de comparación ofrecen editar un valor o una transformación: el auditor reconstruye y verifica, pero no toca. La consistencia de esa restricción en todas las pantallas del perfil sostiene la confianza en que la evidencia observada es fiel al sistema.", "principio": "Consistencia del modelo de solo lectura entre pantallas; confianza por restricción uniforme."}]}}, {"id": "6.5", "slug": "datos-crudos", "profile": "auditor", "device": "desktop", "title": "Datos crudos (raw)", "activeMenu": "Datos crudos (raw)", "subtitle": "Vista previa y extracción total de datos crudos · PASA es dueño de la data (DAT-07)", "filters": [], "blocks": [{"type": "table", "col": 0, "colspan": 12, "y": 184, "h": 356, "label": "Vista previa de datos raw", "meta": "Primeras 100 filas · sin transformar · solo lectura", "reqs": ["DAT-07", "DAT-06", "DAT-04"], "cols": ["Timestamp UTC", "Valor raw", "Unidad", "Flag calidad", "Flag anomalía"], "nrows": 12, "statuscol": true}, {"type": "panel", "col": 0, "colspan": 7, "y": 556, "h": 184, "label": "Exportación", "meta": "Formatos para Data Science · retención de exports: 30 días", "reqs": ["DAT-12", "DAT-07", "CYB-10"], "subs": ["Formatos: Parquet · CSV · JSON", "Metadatos en el header: usuario · fecha de exportación · medidor(es) · período · hash SHA-256", "El hash sella el archivo: permite verificar que la extracción no fue alterada"]}, {"type": "actions", "col": 0, "colspan": 7, "y": 756, "h": 40, "btns": ["Exportar Parquet", "Exportar CSV", "Exportar JSON", "Verificar hash"]}, {"type": "panel", "col": 7, "colspan": 5, "y": 556, "h": 240, "label": "Restricción DAT-30", "meta": "Aviso permanente ligado a la exportación", "reqs": ["DAT-30"], "subs": ["Los datos exportados NO pueden usarse para entrenar modelos de ML fuera de PASA.", "Restricción contractual y técnica de entrenamiento con datos de PASA.", "Aplica a Parquet, CSV y JSON descargados desde esta pantalla."]}], "detail": {"descripcion": "Acceso a los datos crudos sin transformar, en cumplimiento de que PASA es dueño de la data y puede extraerla totalmente sin costo adicional (DAT-07). Muestra una vista previa de las primeras 100 filas y permite exportar en Parquet, CSV o JSON con metadatos y hash SHA-256 en el header. Un aviso permanente reitera la restricción DAT-30 sobre el uso de los datos para entrenar modelos de ML fuera de PASA.", "componentes": [{"nombre": "Vista previa de datos raw", "descripcion": "Tabla con las primeras 100 filas: timestamp UTC, valor raw, unidad, flag de calidad (real/estimado/CNR) y flag de anomalía si aplica.", "reqs": ["DAT-07", "DAT-06", "DAT-04"]}, {"nombre": "Exportación", "descripcion": "Formatos Parquet / CSV / JSON. Los archivos incluyen metadatos en el header: usuario, fecha de exportación, medidor(es), período y hash SHA-256. Retención de exports disponibles: 30 días.", "reqs": ["DAT-12", "DAT-07", "CYB-10"]}, {"nombre": "Restricción DAT-30", "descripcion": "Los datos exportados no pueden usarse para entrenar modelos de ML fuera de PASA: restricción contractual y técnica de entrenamiento con datos de PASA.", "reqs": ["DAT-30"]}], "filtros": [], "ux": [{"componente": "Vista previa antes de exportar", "texto": "Se muestran las primeras 100 filas del crudo en pantalla para que el auditor confirme estructura, unidad y flags antes de descargar un dataset potencialmente enorme; previsualizar evita gastar tiempo y espacio en una extracción que resultó ser el medidor o el período equivocado.", "principio": "Prevención de errores antes de una acción costosa; confirmación por muestra."}, {"componente": "Timestamp en UTC y flags declarados en la propia tabla", "texto": "El crudo se presenta con la hora en UTC y los flags de calidad y anomalía como columnas, sin normalizar a la zona local ni ocultar los marcadores; para auditar hay que ver el dato tal cual llegó, incluidas sus banderas, no una versión ya interpretada por la plataforma.", "principio": "Fidelidad al dato de origen; no maquillar lo que se somete a verificación."}, {"componente": "Tres formatos con hash embebido en el header", "texto": "Parquet, CSV y JSON se ofrecen juntos porque el auditor los lleva a herramientas distintas, y cada archivo incrusta en su encabezado los metadatos y el hash SHA-256; así la prueba de integridad viaja con el dato y puede recomprobarse fuera de la plataforma en cualquier momento.", "principio": "La evidencia es autocontenida y verificable de forma independiente."}, {"componente": "Aviso DAT-30 fijo junto al bloque de exportación", "texto": "La restricción de no entrenar ML fuera de PASA se ancla al lado del botón de descarga, no en unos términos legales lejanos, para que el límite de uso se lea en el momento y lugar exactos en que el auditor está a punto de llevarse los datos. La regla acompaña a la acción que la activa.", "principio": "Ayuda en contexto; la advertencia vive donde ocurre la acción que regula."}, {"componente": "Retención de exports de 30 días indicada explícitamente", "texto": "Se declara que los archivos generados están disponibles 30 días para que el auditor planifique su descarga y no asuma un repositorio permanente; hacer visible la caducidad fija una expectativa correcta sobre la persistencia de la extracción.", "principio": "Visibilidad de las restricciones del sistema; expectativas explícitas sobre el ciclo de vida del dato."}]}, "primaryAction": "Exportar datos"}, {"id": "6.6", "slug": "exportar-evidencia", "profile": "auditor", "device": "desktop", "title": "Exportar evidencia", "activeMenu": "Exportar evidencia", "subtitle": "Armado de paquetes de evidencia firmados · sello de tiempo, hash SHA-256 y verificación (CYB-10)", "filters": [], "blocks": [{"type": "form", "col": 0, "colspan": 6, "y": 184, "h": 360, "label": "Configurador de paquete de evidencia", "meta": "Selección de contenido, alcance y formato", "reqs": ["DAT-07", "DAT-12"], "fields": ["Contenido a incluir (datos de consumo / cuadratura / pista de auditoría / scorecard de calidad / linaje) — multi-selección", "Mall(es)", "Período", "Formato de salida (PDF + CSV empaquetados en ZIP firmado)"]}, {"type": "panel", "col": 6, "colspan": 6, "y": 184, "h": 200, "label": "Firma digital del paquete", "meta": "Sello de integridad aplicado al ZIP", "reqs": ["DAT-12", "CYB-10", "DAT-07"], "subs": ["Sello de tiempo del servidor (timestamp de emisión)", "Hash SHA-256 del contenido del paquete", "Firma de la plataforma", "Verificable con herramienta pública de verificación de hash"]}, {"type": "actions", "col": 6, "colspan": 6, "y": 400, "h": 40, "btns": ["Generar paquete firmado", "Verificar hash"]}, {"type": "panel", "col": 6, "colspan": 6, "y": 456, "h": 88, "label": "Vista previa del paquete", "meta": "Antes de generar", "reqs": ["DAT-12"], "subs": ["Portada + índice de contenidos seleccionados", "Estructura del ZIP: /pdf /csv /manifest-firma.txt"]}, {"type": "table", "col": 0, "colspan": 12, "y": 560, "h": 300, "label": "Historial de evidencias exportadas", "meta": "Link de descarga válido 90 días", "reqs": ["DAT-12", "DAT-14"], "cols": ["Fecha", "Usuario", "Contenido", "Período cubierto", "Hash SHA-256", "Descarga"], "nrows": 6}], "detail": {"descripcion": "Pantalla de cierre del flujo del auditor: arma paquetes de evidencia firmados que consolidan el material verificado en las demás pantallas. Permite elegir el contenido, los malls y el período, genera un ZIP firmado (PDF + CSV) con sello de tiempo del servidor, hash SHA-256 y firma de la plataforma, y conserva un historial de las evidencias exportadas con enlace de descarga válido por 90 días.", "componentes": [{"nombre": "Configurador de paquete de evidencia", "descripcion": "Contenido a incluir: datos de consumo, cuadratura, pista de auditoría, scorecard de calidad y linaje de lecturas seleccionadas. Mall(es) y período. Formato: PDF + CSV empaquetados en un ZIP firmado.", "reqs": ["DAT-07", "DAT-12"]}, {"nombre": "Firma digital del paquete", "descripcion": "Sello de tiempo del servidor, hash SHA-256 del contenido y firma de la plataforma. El auditor puede verificar la integridad con una herramienta pública de verificación de hash.", "reqs": ["DAT-12", "CYB-10", "DAT-07"]}, {"nombre": "Historial de evidencias exportadas", "descripcion": "Fecha, usuario, contenido, período cubierto y link de descarga (válido 90 días), con el hash del paquete a la vista.", "reqs": ["DAT-12", "DAT-14"]}], "filtros": [], "ux": [{"componente": "Configurador a la izquierda, firma y salida a la derecha", "texto": "La pantalla lee de izquierda a derecha el flujo «armo el paquete → veo su sello → lo genero»: el formulario en la columna izquierda es el primer paso y la firma, vista previa y botones a la derecha son el resultado. El auditor avanza sin retroceder ni buscar dónde se cierra la tarea.", "principio": "Flujo secuencial alineado al recorrido de lectura; un único camino hacia el cierre."}, {"componente": "Contenido como multi-selección que reúne el trabajo previo", "texto": "El paquete se compone marcando qué evidencias incluir (cuadratura, pista, calidad, linaje), de modo que consolida en un solo entregable lo verificado pieza por pieza en las pantallas anteriores. Empaquetar desde una lista evita rehacer o re-exportar cada fuente por separado.", "principio": "Agregación del trabajo previo en un solo artefacto; reducción de esfuerzo repetido."}, {"componente": "Firma digital detallada antes del botón Generar", "texto": "El panel de firma enumera los tres componentes del sello —tiempo de servidor, hash SHA-256 y firma de la plataforma— y anuncia que es verificable con herramienta pública, todo antes de generar; así el auditor sabe exactamente qué garantías tendrá el ZIP y no descubre el mecanismo de integridad recién al abrir el archivo.", "principio": "Visibilidad anticipada de las garantías; el usuario conoce el resultado antes de comprometerse."}, {"componente": "Vista previa de la estructura del ZIP", "texto": "Antes de emitir se muestra la portada, el índice y la estructura de carpetas del paquete para que el auditor confirme que incluye lo que debe presentar; previsualizar el entregable evita generar y firmar un ZIP incompleto que luego habría que rehacer y re-firmar.", "principio": "Confirmación previa a una acción irreversible; el sello se aplica una sola vez sobre lo correcto."}, {"componente": "Historial con el hash de cada paquete y caducidad de 90 días", "texto": "El registro de evidencias muestra el hash junto a cada descarga y advierte que el enlace vive 90 días; conservar el sello permite al auditor demostrar más tarde qué entregó exactamente, y explicitar la caducidad lo impulsa a resguardar el archivo antes de que expire.", "principio": "El sistema recuerda la evidencia entregada; expectativa clara sobre la vigencia del enlace."}, {"componente": "«Generar paquete firmado» como CTA primaria", "texto": "El botón que emite el paquete se distingue en acento sólido frente a «Verificar hash», secundario, porque es el acto que cierra toda la auditoría; darle el mayor peso visual elimina cualquier duda sobre cuál es el paso final de la pantalla.", "principio": "Jerarquía de acciones primaria/secundaria; ley de Fitts sobre el objetivo que cierra la tarea."}]}, "primaryAction": "Generar paquete"}, {"id": "7.1", "slug": "tenants-malls", "profile": "super-admin", "device": "desktop", "title": "Tenants y malls", "activeMenu": "Tenants y malls", "subtitle": "Multitenancy con aislamiento lógico por mall · alta de nuevos centros comerciales sin consultoría · crear/activar/desactivar requiere aprobación de PASA", "filters": [], "blocks": [{"type": "table", "col": 0, "colspan": 8, "y": 184, "h": 340, "label": "Lista de tenants", "meta": "Filtros: estado / con alertas activas · fila expandible con resumen del mall", "reqs": ["ARQ-05", "FIN-02", "FIN-03"], "cols": ["Tenant ID", "Mall", "Estado", "N° medidores", "N° usuarios", "Fecha alta", "Versión contrato"], "nrows": 8, "statuscol": true, "expand": true}, {"type": "table", "col": 0, "colspan": 8, "y": 540, "h": 300, "label": "Historial de cambios de configuración del tenant", "meta": "Inmutable · quién, qué campo, valor anterior/nuevo, timestamp (DAT-14)", "reqs": ["DAT-19", "DAT-14"], "cols": ["Fecha", "Usuario", "Campo", "Valor anterior", "Valor nuevo", "Aprobación"], "nrows": 6}, {"type": "panel", "col": 8, "colspan": 4, "y": 184, "h": 220, "label": "Detalle de tenant — configuración base", "meta": "tenant seleccionado en la lista", "reqs": ["ARQ-05", "DAT-19", "FIN-04"], "subs": ["Nombre · país · moneda · zona horaria", "Umbrales de alerta configurados", "Integración de facturación activa (FIN-04)", "Aislamiento lógico por mall (ARQ-05)"]}, {"type": "panel", "col": 8, "colspan": 4, "y": 420, "h": 150, "label": "Estadísticas de uso", "meta": "consumo del tenant, últimos 30 días", "reqs": ["FIN-01", "DAT-09"], "subs": ["Usuarios activos 30d: 42", "N° consultas API (mes): 1,2 M", "Volumen de datos almacenados: 318 GB"]}, {"type": "actions", "col": 8, "colspan": 4, "y": 588, "h": 40, "btns": ["Crear tenant", "Activar", "Desactivar"]}], "detail": {"descripcion": "Administración de los tenants (centros comerciales) sobre el modelo multitenant con aislamiento lógico por mall y consolidación por país y región (ARQ-05). Permite dar de alta nuevos malls sin consultoría específica (FIN-02/FIN-03) y editar la configuración base. Las acciones de creación, activación y desactivación no se ejecutan de forma directa: abren un flujo de aprobación documentado con PASA (CYB-15) y quedan auditadas (DAT-14).", "componentes": [{"nombre": "Lista de tenants", "descripcion": "Tenant ID, nombre del mall, estado, nº de medidores activos, nº de usuarios activos, fecha de alta y versión de contrato. Filtros por estado y con alertas activas.", "reqs": ["ARQ-05", "FIN-02", "FIN-03"]}, {"nombre": "Detalle de tenant", "descripcion": "Configuración base: nombre, país, moneda, zona horaria, umbrales de alerta e integración de facturación activa. Estadísticas de uso: usuarios activos en 30 días, nº de consultas API y volumen de datos almacenados. Historial de cambios de configuración.", "reqs": ["ARQ-05", "DAT-19", "FIN-04"]}, {"nombre": "Acciones de tenant", "descripcion": "Crear / Activar / Desactivar — requiere aprobación de PASA mediante flujo documentado. Editar la configuración base con auditoría de cada cambio.", "reqs": ["ARQ-05", "CYB-15", "DAT-14"]}], "filtros": [], "ux": [{"componente": "Lista como columna dominante y detalle a la derecha", "texto": "El súper-administrador entra a esta pantalla para localizar un tenant entre decenas, no para leer uno solo; por eso la tabla ocupa dos tercios del ancho y actúa como único punto de entrada, mientras el detalle se despliega al seleccionar una fila. Así el operador confirma sobre qué mall va a actuar antes de tener a la vista cualquier botón que lo modifique.", "principio": "Jerarquía visual por tarea dominante; seleccionar el objeto antes que ofrecer la acción."}, {"componente": "Botones Crear/Activar/Desactivar separados del detalle", "texto": "Las acciones que cambian el estado de un tenant se agrupan en una barra propia, visualmente aparte de los datos de solo lectura, para que el máximo privilegio de este perfil no se traduzca en un clic accidental sobre un control mezclado con la información. Separar 'mirar' de 'actuar' reduce el error en operaciones de alto impacto.", "principio": "Prevención de errores; separación entre visualización y acción destructiva."}, {"componente": "Nota de gate PASA siempre visible", "texto": "Aunque el perfil tiene permiso técnico para crear o desactivar, la nota fija explica que la acción abre un flujo de aprobación y no se ejecuta de inmediato. Hacer explícito el gate en la propia pantalla evita que el administrador espere un efecto instantáneo y sepa que falta la confirmación de un rol PASA.", "principio": "Visibilidad del estado del sistema; ajustar el modelo mental al flujo real."}, {"componente": "Historial de configuración como bloque permanente", "texto": "El historial de cambios no se esconde en un modal: se muestra siempre bajo la lista para que cualquier edición sea trazable de un vistazo. Dado que todo lo que hace este perfil es auditado por PASA, exponer el registro en pantalla refuerza la responsabilidad de cada cambio.", "principio": "Trazabilidad visible; el registro acompaña a la acción."}, {"componente": "Estadísticas de uso junto al detalle del tenant", "texto": "Usuarios activos, consultas API y volumen almacenado se colocan pegados al detalle porque el administrador los consulta al decidir un cambio de contrato o una desactivación; tenerlos contiguos evita saltar entre pantallas para reunir el contexto de la decisión.", "principio": "Proximidad de la información que soporta una misma decisión."}]}, "primaryAction": "Nuevo tenant"}, {"id": "7.2", "slug": "config-releases", "profile": "super-admin", "device": "desktop", "title": "Config y releases", "activeMenu": "Config y releases", "subtitle": "Pipeline de despliegue con IaC versionada · ningún cambio pasa a producción sin pruebas y aprobación previa (CYB-15) · ambientes QA y Producción independientes (ARQ-06)", "filters": [], "blocks": [{"type": "table", "col": 0, "colspan": 7, "y": 184, "h": 330, "label": "Pipeline de releases", "meta": "estado: En desarrollo → QA → Aprobación → Producción · fila expandible con diff y resultados de tests", "reqs": ["CYB-15", "ARQ-16", "ARQ-06"], "cols": ["Versión", "Descripción de cambios", "Estado", "Tests QA", "Aprobaciones (obt/req)"], "nrows": 7, "statuscol": true, "expand": true}, {"type": "panel", "col": 0, "colspan": 7, "y": 530, "h": 310, "label": "Configuración como código — diff viewer (IaC)", "meta": "cambios versionados en git · link al commit correspondiente (ARQ-16)", "reqs": ["ARQ-16", "CYB-15"], "subs": ["+  resource \"aws_rds_replica\" { multi_az = true }", "-  instance_class = \"db.r5.large\"", "+  instance_class = \"db.r5.xlarge\"", "commit a3f9c21 · autor: sre@globepower · rama: release/2.4.0"]}, {"type": "panel", "col": 7, "colspan": 5, "y": 184, "h": 200, "label": "Control de despliegue", "meta": "GATE: requiere aprobación de al menos un rol PASA configurado (CYB-15)", "reqs": ["CYB-15", "ARQ-06", "ARQ-16"], "subs": ["Etapas: build → deploy QA → aprobación → prod", "Logs de despliegue en tiempo real", "Rollback disponible a la versión anterior", "Ambientes QA/sandbox y Producción independientes"]}, {"type": "actions", "col": 7, "colspan": 5, "y": 400, "h": 40, "btns": ["Solicitar despliegue a producción", "Rollback"]}, {"type": "table", "col": 7, "colspan": 5, "y": 456, "h": 384, "label": "Historial de despliegues", "meta": "éxito / rollback · link a logs", "reqs": ["ARQ-16", "DAT-14", "CYB-10"], "cols": ["Versión", "Fecha", "Responsable", "Resultado"], "nrows": 9, "statuscol": true}], "detail": {"descripcion": "Pipeline de gestión de cambios y despliegue basado en infraestructura como código (IaC) versionada y documentada (ARQ-16). El proceso es formal: ninguna modificación pasa a producción sin pruebas de seguridad en QA y aprobación previa (CYB-15), sobre ambientes QA/sandbox y Producción independientes (ARQ-06). El botón de solicitud de despliegue abre un flujo de aprobación que exige la confirmación de al menos un rol PASA configurado.", "componentes": [{"nombre": "Pipeline de releases", "descripcion": "Lista de releases con versión, descripción de cambios y estado (en desarrollo / QA / aprobación / producción). Para cada release: diff de cambios, resultados de tests en QA y aprobaciones requeridas vs. obtenidas.", "reqs": ["CYB-15", "ARQ-16", "ARQ-06"]}, {"nombre": "Control de despliegue", "descripcion": "Botón 'Solicitar despliegue a producción' que abre el flujo de aprobación (requiere aprobación de al menos un rol PASA). Estado del despliegue con etapas, logs en tiempo real y rollback disponible.", "reqs": ["CYB-15", "ARQ-06", "ARQ-16"]}, {"nombre": "Configuración como código", "descripcion": "Diff viewer de los cambios en IaC entre versiones. Todos los cambios versionados en git, con link al commit correspondiente.", "reqs": ["ARQ-16", "CYB-15"]}, {"nombre": "Historial de despliegues", "descripcion": "Versión, fecha, responsable, resultado (éxito / rollback) y link a logs.", "reqs": ["ARQ-16", "DAT-14", "CYB-10"]}], "filtros": [], "ux": [{"componente": "Pipeline con estado codificado y etapas ordenadas", "texto": "Cada release muestra su fase (desarrollo/QA/aprobación/producción) con un punto de estado en la primera columna, de modo que el administrador reconstruye en un barrido en qué punto del proceso está cada cambio. Ver la etapa evita que alguien intente promover algo que aún no pasó QA.", "principio": "Visibilidad del estado del sistema; feedback de progreso por etapas."}, {"componente": "'Solicitar despliegue a producción' como CTA de acento con gate explícito", "texto": "El botón primario no dice 'Desplegar' sino 'Solicitar despliegue', y su meta advierte que exige aprobación de un rol PASA. El lenguaje del propio control comunica que la acción no es inmediata sino sometida a un gate, alineando la expectativa con el proceso formal de gestión de cambios.", "principio": "Correspondencia entre etiqueta y consecuencia real; prevención de error en acción crítica."}, {"componente": "Diff de IaC visible antes de aprobar", "texto": "El visor de diferencias con las líneas añadidas y eliminadas y el link al commit está en pantalla para que quien aprueba lea exactamente qué cambia en la infraestructura, sin salir a la herramienta de git. Mostrar el cambio concreto convierte la aprobación en una decisión informada, no en un clic ciego.", "principio": "Reconocer antes que recordar; revelar el contenido de la decisión."}, {"componente": "Rollback como acción siempre presente", "texto": "El control de rollback acompaña permanentemente al de despliegue, no aparece solo cuando algo falla, para que ante un incidente en producción la vía de reversión sea inmediata y no haya que buscarla bajo presión. Una salida de emergencia visible reduce el tiempo de recuperación.", "principio": "Salidas claramente marcadas; control y libertad del usuario."}, {"componente": "Historial de despliegues como registro auditado a la derecha", "texto": "El historial con resultado (éxito/rollback) y responsable queda fijo junto al control, porque en este perfil todo despliegue es auditado por PASA y el operador necesita ver el precedente de la versión antes de repetir una operación. El registro contiguo sostiene la rendición de cuentas.", "principio": "Trazabilidad en contexto; el pasado informa la próxima acción."}]}, "primaryAction": "Solicitar despliegue"}, {"id": "7.3", "slug": "usuarios-roles", "profile": "super-admin", "device": "desktop", "title": "Usuarios y roles", "activeMenu": "Usuarios y roles", "subtitle": "RBAC con mínimo privilegio y auditoría trimestral (CYB-03) · off-boarding automático (ARQ-10) · revisión de permisos sin uso en más de 90 días con revocación masiva", "filters": [], "blocks": [{"type": "table", "col": 0, "colspan": 8, "y": 184, "h": 330, "label": "Lista de usuarios", "meta": "filtros: tenant / perfil / estado / sin acceso en > 90 días · fila expandible", "reqs": ["CYB-03", "ARQ-10", "CYB-02"], "cols": ["Nombre", "Email", "Tenant / mall", "Perfil", "Estado", "Último acceso", "MFA"], "nrows": 8, "statuscol": true, "expand": true}, {"type": "table", "col": 0, "colspan": 8, "y": 530, "h": 310, "label": "Permisos sin uso en > 90 días", "meta": "ACCIÓN DESTRUCTIVA: revocación masiva · auditada usuario/timestamp (DAT-14)", "reqs": ["CYB-03", "ARQ-10", "DAT-14"], "cols": ["Usuario", "Permiso / recurso", "Últ. uso", "Perfil", "Sugerencia"], "nrows": 6, "statuscol": true}, {"type": "panel", "col": 8, "colspan": 4, "y": 184, "h": 210, "label": "Detalle de usuario — permisos efectivos", "meta": "recursos y acciones permitidas", "reqs": ["CYB-03", "DAT-14", "CYB-21"], "subs": ["Perfil: Operacional · tenant: Costanera", "Recursos: alarmas (R/W), tickets (R/W)", "MFA activo (CYB-02) · SSO Azure AD", "Auditoría trimestral de permisos (CYB-03)"]}, {"type": "timeline", "col": 8, "colspan": 4, "y": 410, "h": 250, "label": "Historial de accesos y cambios de rol", "meta": "últimas 30 sesiones · IP, timestamp, resultado", "reqs": ["DAT-14", "CYB-21"], "items": ["Login OK · 10-07 08:14 · IP 190.x", "Cambio de rol: Auditor → Operacional", "Login OK · 09-07 17:52", "Revocación de permiso backfill", "Login fallido · MFA rechazado"]}, {"type": "actions", "col": 8, "colspan": 4, "y": 676, "h": 40, "btns": ["Asignar / cambiar perfil", "Revocar acceso"]}], "detail": {"descripcion": "Gestión de identidades y roles bajo RBAC con mínimo privilegio y auditoría trimestral de permisos (CYB-03), integrada con el off-boarding automático desde Azure AD (ARQ-10). Además de la lista y el detalle por usuario, incorpora un panel de revisión de permisos sin uso en más de 90 días que habilita la revocación masiva, y expone los permisos efectivos y el historial de accesos y cambios de rol de cada cuenta.", "componentes": [{"nombre": "Lista de usuarios", "descripcion": "Nombre, email, tenant/mall asignado, perfil, estado (activo/inactivo/bloqueado), último acceso y MFA activo. Filtros por tenant, perfil, estado y sin acceso en más de 90 días.", "reqs": ["CYB-03", "ARQ-10", "CYB-02"]}, {"nombre": "Detalle de usuario", "descripcion": "Permisos efectivos (recursos y acciones permitidas). Historial de accesos: últimas 30 sesiones. Historial de cambios de rol.", "reqs": ["CYB-03", "DAT-14", "CYB-21"]}, {"nombre": "Gestión de usuarios", "descripcion": "Asignar/cambiar perfil con justificación. Revocar acceso (off-boarding). Revisión periódica de permisos: panel de 'permisos sin uso en más de 90 días' con revocación masiva.", "reqs": ["CYB-03", "ARQ-10", "DAT-14"]}], "filtros": [], "ux": [{"componente": "Columna de MFA y estado en la lista principal", "texto": "El estado de la cuenta y si tiene MFA activo se muestran como columnas fijas, no ocultas en el detalle, porque la primera pregunta de seguridad al revisar el padrón es qué cuentas están activas sin doble factor. Exponerlo en la fila permite auditar el cumplimiento de CYB-02 sin abrir cada usuario.", "principio": "Información crítica al primer nivel; escaneabilidad de la condición de riesgo."}, {"componente": "Panel dedicado de permisos sin uso > 90 días", "texto": "El mínimo privilegio se opera desde un bloque propio que aísla los permisos ociosos y ofrece revocarlos en bloque, convirtiendo la auditoría trimestral en una tarea guiada en vez de una búsqueda manual usuario por usuario. Reunir lo revocable en un solo lugar reduce el esfuerzo de mantener el principio de mínimo privilegio.", "principio": "Agrupar por intención de tarea; reducir la carga de la revisión periódica."}, {"componente": "Etiqueta explícita de acción destructiva en la revocación masiva", "texto": "El bloque de revocación advierte en su meta que es una acción destructiva y auditada; antes de aplicar sobre múltiples cuentas debe mediar confirmación. Nombrar el riesgo junto al control frena la ejecución impulsiva de una operación que puede dejar sin acceso a varios usuarios a la vez.", "principio": "Prevención de errores; confirmación proporcional al alcance del daño."}, {"componente": "Cambio de perfil que exige justificación", "texto": "Asignar o cambiar un rol no es un desplegable suelto: el flujo pide una justificación que quedará en la auditoría. Obligar a explicar el porqué disuade cambios arbitrarios de privilegio y deja una razón trazable para la revisión de PASA.", "principio": "Fricción deliberada en acciones sensibles; responsabilidad rastreable."}, {"componente": "Historial de accesos y cambios de rol como línea de tiempo", "texto": "Las últimas sesiones y los cambios de rol se presentan en orden cronológico junto al detalle, de modo que al investigar una cuenta el administrador ve la secuencia de eventos (logins, fallos de MFA, cambios de permiso) sin reconstruirla. La narrativa temporal facilita detectar comportamientos anómalos.", "principio": "Reconocimiento sobre memoria; la secuencia temporal cuenta la historia de la cuenta."}]}, "primaryAction": "Nuevo usuario"}, {"id": "7.4", "slug": "observabilidad", "profile": "super-admin", "device": "desktop", "title": "Observabilidad", "activeMenu": "Observabilidad", "subtitle": "Health-check compatible con monitoreo externo (Splunk/CloudWatch/Datadog) · logs a sistema centralizado de PASA · dashboard de uso de APIs y tasas de error", "filters": [], "blocks": [{"type": "kpi", "col": 0, "colspan": 3, "y": 184, "h": 108, "label": "Uptime (30 días)", "value": "99,82%", "delta": "▲ sobre SLA 99,5% (FIN-06)", "spark": true, "reqs": ["ARQ-08", "FIN-06"]}, {"type": "kpi", "col": 3, "colspan": 3, "y": 184, "h": 108, "label": "Latencia media de API", "value": "142 ms", "delta": "p50 · últimas 24h", "reqs": ["ARQ-08", "DAT-09"]}, {"type": "kpi", "col": 6, "colspan": 3, "y": 184, "h": 108, "label": "Error rate", "value": "0,4%", "delta": "(4xx + 5xx) / total requests", "reqs": ["ARQ-21", "DAT-09"]}, {"type": "kpi", "col": 9, "colspan": 3, "y": 184, "h": 108, "label": "Tiempo de respuesta p95", "value": "468 ms", "delta": "umbral INT-08 < 500 ms", "reqs": ["ARQ-08", "INT-08"]}, {"type": "table", "col": 0, "colspan": 6, "y": 308, "h": 232, "label": "Health dashboard — semáforo por componente", "meta": "API / BD / cola de mensajes / ingestión / backfill", "reqs": ["ARQ-08", "ARQ-21", "FIN-06"], "cols": ["Componente", "Estado", "Latencia", "Última verificación"], "nrows": 5, "statuscol": true}, {"type": "panel", "col": 6, "colspan": 6, "y": 308, "h": 232, "label": "Métricas de ingestión de datos", "meta": "salud del flujo de datos hacia la plataforma", "reqs": ["DAT-09", "DAT-27", "ARQ-08"], "subs": ["Medidores reportando en el último ciclo: 96,4%", "Mensajes procesados / hora: 1,84 M", "Mensajes en cola: 2.310", "Errores de parsing (24h): 41 · tendencia ▼", "Anomalías detectadas automáticamente (DAT-27)"]}, {"type": "line", "col": 0, "colspan": 4, "y": 556, "h": 274, "label": "Latencia de API por endpoint", "meta": "últimas 24h / 7 días · líneas por endpoint", "reqs": ["DAT-09", "ARQ-08"], "threshold": 0.8}, {"type": "bars", "col": 4, "colspan": 4, "y": 556, "h": 274, "label": "Tasa de errores por tipo", "meta": "4xx / 5xx · barras", "reqs": ["ARQ-21", "DAT-09"]}, {"type": "area", "col": 8, "colspan": 4, "y": 556, "h": 274, "label": "Throughput de mensajes", "meta": "mensajes procesados · área", "reqs": ["DAT-09", "ARQ-08"]}], "detail": {"descripcion": "Panel de observabilidad de la plataforma con health-check compatible con herramientas de monitoreo externas (Splunk, CloudWatch, Datadog) según ARQ-08, envío de logs de errores al sistema centralizado de PASA (ARQ-21) y dashboard de uso de APIs y tasas de error (DAT-09). Combina un semáforo de salud por componente, métricas de ingestión de datos y gráficos de tendencia de latencia, errores y throughput.", "componentes": [{"nombre": "Health dashboard", "descripcion": "Uptime (30 días), latencia media de API [ms], error rate [%] y tiempo de respuesta p95. Semáforo por componente: API / BD / cola de mensajes / ingestión / backfill.", "reqs": ["ARQ-08", "ARQ-21", "FIN-06"]}, {"nombre": "Métricas de ingestión de datos", "descripcion": "% de medidores reportando en el último ciclo, mensajes procesados/hora, mensajes en cola y errores de parsing.", "reqs": ["DAT-09", "DAT-27", "ARQ-08"]}, {"nombre": "Gráficos de tendencia", "descripcion": "Latencia de API por endpoint (líneas), tasa de errores por tipo 4xx/5xx (barras) y throughput de mensajes (área). Ventanas de últimas 24h / 7 días.", "reqs": ["DAT-09", "ARQ-08", "ARQ-21"]}], "filtros": [], "ux": [{"componente": "Fila de KPIs de salud como cabecera de lectura", "texto": "Uptime, latencia, error rate y p95 se alinean en una sola fila superior porque son la respuesta inmediata a '¿está sana la plataforma ahora?'. El administrador los lee como un tablero de instrumentos antes de descender al detalle, y cada uno referencia su umbral contractual para saber si el número es aceptable.", "principio": "Jerarquía en F; la conclusión de salud antes que la evidencia gráfica."}, {"componente": "Semáforo por componente en tabla de estado", "texto": "API, base de datos, cola, ingestión y backfill se listan con su punto de estado y última verificación, de modo que ante una degradación el operador localiza el componente culpable de un vistazo en lugar de correlacionar gráficos. Descomponer la salud por pieza acelera el diagnóstico de causa.", "principio": "Codificación pre-atenta del color; localización rápida del punto de falla."}, {"componente": "Métricas de ingestión separadas de la salud de aplicación", "texto": "El flujo de datos (medidores reportando, mensajes en cola, errores de parsing) tiene su propio panel junto al health, porque en un EMS un problema de datos no siempre coincide con uno de infraestructura. Distinguir 'la app responde' de 'los datos llegan' evita que el administrador dé por sana la plataforma cuando la ingestión está detenida.", "principio": "Separación de dominios de problema; evitar conclusiones falsas por agregación."}, {"componente": "Tres gráficos de tendencia contiguos y comparables", "texto": "Latencia, errores y throughput se colocan lado a lado con el mismo eje temporal para que el administrador correlacione visualmente un pico de errores con una caída de throughput sin cambiar de vista. La alineación temporal convierte tres series en una sola lectura de causa-efecto.", "principio": "Vistas coordinadas en un eje común; comparación por adyacencia."}, {"componente": "Compatibilidad con monitoreo externo declarada en subtítulo", "texto": "El encabezado recuerda que estas métricas se exponen a Splunk/Datadog y se envían a los logs centralizados de PASA, para que el administrador entienda que la pantalla es un espejo del monitoreo formal y no una fuente aislada. Situar la herramienta en su ecosistema evita duplicar la vigilancia.", "principio": "Consistencia con el sistema externo; transparencia del origen del dato."}]}, "live": "En vivo · act. hace 30 s"}, {"id": "7.5", "slug": "integraciones", "profile": "super-admin", "device": "desktop", "title": "Integraciones", "activeMenu": "Integraciones", "subtitle": "Consola de salud y latencia de cada conexión (INT-13) · APIs con backward compatibility por 6 meses (INT-06) · ver contrato de interfaz sin exponer el modelo interno", "filters": [], "blocks": [{"type": "table", "col": 0, "colspan": 7, "y": 184, "h": 330, "label": "Lista de integraciones activas", "meta": "tipo: API REST / Modbus / DLMS / webhook / SFTP · fila expandible", "reqs": ["INT-13", "DAT-09", "INT-06"], "cols": ["Nombre", "Tipo", "Tenant", "Estado", "Último heartbeat", "Éxito 7d"], "nrows": 8, "statuscol": true, "expand": true}, {"type": "feed", "col": 0, "colspan": 7, "y": 530, "h": 300, "label": "Log de los últimos 100 eventos de la integración", "meta": "integración seleccionada · solo lectura", "reqs": ["INT-13", "DAT-09"], "items": [["OK", "Heartbeat recibido · 10-07 09:12", "ok"], ["WARNING", "Latencia elevada 820 ms", "warn"], ["ERROR", "Timeout — reintento 3/5", "crit"], ["OK", "Re-sincronización manual completada", "ok"], ["INFO", "Rotación de credencial OAuth2", "null"]]}, {"type": "panel", "col": 7, "colspan": 5, "y": 184, "h": 200, "label": "Detalle de integración — configuración técnica", "meta": "endpoint · protocolo · credenciales enmascaradas", "reqs": ["INT-13", "DAT-09", "INT-06"], "subs": ["Endpoint: https://api.***/v2/ingress", "Protocolo: API REST · OAuth2 (INT-02)", "Credenciales: ****** (enmascaradas)", "Timeout configurable por canal (INT-11)", "Contrato: API v2 · compatibilidad hacia atrás 6m (INT-06)"]}, {"type": "line", "col": 7, "colspan": 5, "y": 400, "h": 320, "label": "Métricas de la integración (24h)", "meta": "tasa de éxito / errores / latencia / volumen", "reqs": ["INT-13", "DAT-09"], "threshold": 0.75}, {"type": "actions", "col": 7, "colspan": 5, "y": 736, "h": 40, "btns": ["Activar / Desactivar", "Forzar re-sincronización", "Ver contrato"]}], "detail": {"descripcion": "Consola de monitoreo y administración de las integraciones de la plataforma, con estado de salud y latencia de cada conexión (INT-13) y observabilidad de API (DAT-09). Permite ver el detalle técnico de cada integración con credenciales enmascaradas, gestionar su activación y forzar re-sincronización, y consultar el contrato de interfaz (versión de API y esquema) con backward compatibility por 6 meses (INT-06) sin exponer el modelo interno.", "componentes": [{"nombre": "Lista de integraciones activas", "descripcion": "Nombre, tipo (API REST / Modbus / DLMS / webhook / SFTP), tenant, estado (activo/degradado/error), último heartbeat y tasa de éxito de 7 días.", "reqs": ["INT-13", "DAT-09", "INT-06"]}, {"nombre": "Detalle de integración", "descripcion": "Configuración técnica (endpoint, protocolo, credenciales enmascaradas). Métricas: tasa de éxito, errores, latencia y volumen de 24h. Log de los últimos 100 eventos.", "reqs": ["INT-13", "DAT-09", "INT-06"]}, {"nombre": "Gestión de integraciones", "descripcion": "Activar/Desactivar con registro de motivo. Forzar re-sincronización. Ver el contrato de interfaz (versión de API, esquema) sin exponer el modelo interno.", "reqs": ["INT-06", "INT-07", "DAT-25"]}], "filtros": [], "ux": [{"componente": "Estado y tasa de éxito 7d en la lista", "texto": "Cada integración muestra su estado y su tasa de éxito de la última semana como columnas, de modo que el administrador prioriza las conexiones degradadas o con error sin abrirlas una a una. Ordenar la atención hacia lo que falla es el propósito de una consola de salud de interfaces.", "principio": "Priorización por severidad; lo problemático se hace evidente primero."}, {"componente": "Credenciales enmascaradas en el detalle", "texto": "Aunque este perfil tiene máximo privilegio, el detalle técnico muestra las credenciales ofuscadas por defecto; verlas en claro sería una acción aparte y auditada. Ocultar el secreto salvo solicitud explícita reduce la exposición accidental en pantalla compartida o captura.", "principio": "Minimización de exposición de secretos; privilegio no implica revelación por defecto."}, {"componente": "'Forzar re-sincronización' junto al log de eventos", "texto": "La acción de re-sincronizar se ubica cerca del log de los últimos 100 eventos porque el administrador la ejecuta justo después de leer un error y quiere ver el efecto inmediato en el mismo lugar. Emparejar la acción con su evidencia cierra el ciclo diagnóstico-acción-verificación.", "principio": "Proximidad acción-feedback; cerrar el bucle de control."}, {"componente": "'Ver contrato' sin exponer el modelo interno", "texto": "El botón de contrato de interfaz muestra la versión de API y el esquema público, pero no la implementación interna; la etiqueta lo deja claro para que el administrador comparta el contrato con PASA sin filtrar detalles propietarios. Delimitar qué se expone protege la frontera técnica del proveedor.", "principio": "Correspondencia entre affordance y alcance permitido; protección de la frontera de datos."}, {"componente": "Métricas como gráfico con umbral de servicio", "texto": "La tasa de éxito y latencia de 24h se grafican con una línea de umbral para que el administrador vea de un vistazo si la integración opera dentro de lo comprometido, en lugar de interpretar cifras sueltas. El umbral dibujado transforma el dato en juicio inmediato de cumplimiento.", "principio": "Referencia visible para la interpretación; el umbral da significado al valor."}]}, "primaryAction": "Nueva integración"}, {"id": "7.6", "slug": "seguridad-pam", "profile": "super-admin", "device": "desktop", "title": "Seguridad y PAM", "activeMenu": "Seguridad y PAM", "subtitle": "Panel único de postura de seguridad · agrupado en tres bandas: Estado de seguridad · PAM (cuentas privilegiadas y bóveda JIT) · Incidentes y continuidad · acciones críticas resaltadas y auditadas", "filters": [], "blocks": [{"type": "panel", "col": 0, "colspan": 4, "y": 184, "h": 128, "label": "Resumen de vulnerabilidades", "meta": "parche crítico ≤ 30 días (CYB-18)", "reqs": ["CYB-13", "CYB-18"], "subs": ["Críticas 2 · Altas 5 · Medias 11 · Bajas 23", "Parches pendientes: 3 (vence en 12 días)", "Último scan: 09-07 · componentes con parche 94%"]}, {"type": "table", "col": 4, "colspan": 4, "y": 184, "h": 128, "label": "Certificados TLS", "meta": "alerta a 30 y 7 días (CYB-04)", "reqs": ["CYB-04", "INT-04"], "cols": ["Servicio", "Días", "Estado"], "nrows": 3, "statuscol": true}, {"type": "panel", "col": 8, "colspan": 4, "y": 184, "h": 128, "label": "Cifrado en reposo (AES-256)", "meta": "alerta si un componente pierde cifrado", "reqs": ["CYB-05"], "subs": ["Base de datos: AES-256 activo ✓", "Backups: AES-256 activo ✓", "Almacenamiento de archivos: activo ✓"]}, {"type": "panel", "col": 0, "colspan": 4, "y": 326, "h": 128, "label": "WAF / DDoS / IDS-IPS", "meta": "IDS/IPS monitoreado 24x7 (CYB-22)", "reqs": ["CYB-09", "CYB-22"], "subs": ["WAF activo · última alerta hace 3h", "Protección DDoS activa", "IDS/IPS activo y monitoreado 24x7"]}, {"type": "panel", "col": 4, "colspan": 4, "y": 326, "h": 128, "label": "Hardening — CIS Benchmarks", "meta": "% cumplimiento por componente", "reqs": ["CYB-17"], "subs": ["Servidores: 96% · BD: 92%", "Última auditoría de hardening: 30-06", "Hallazgos abiertos: 4 (con ETA de remediación)"]}, {"type": "panel", "col": 8, "colspan": 4, "y": 326, "h": 128, "label": "EDR y antivirus", "meta": "alerta si > 24h sin actualizar firmas", "reqs": ["CYB-14"], "subs": ["Cobertura EDR: 100% de componentes", "Última actualización de firmas: hace 2h", "Última detección: ninguna (7 días)"]}, {"type": "table", "col": 0, "colspan": 4, "y": 468, "h": 128, "label": "Inventario HW/SW (SBOM)", "meta": "alerta EOL en próximos 90 días · exportable a PASA", "reqs": ["CYB-19", "ARQ-20"], "cols": ["Componente", "EOL", "Soporte"], "nrows": 3, "statuscol": true}, {"type": "table", "col": 4, "colspan": 4, "y": 468, "h": 128, "label": "PAM — cuentas privilegiadas", "meta": "revisión mensual obligatoria con justificación (CYB-20)", "reqs": ["CYB-20", "CYB-03", "DAT-14"], "cols": ["Usuario / rol", "Próxima rev.", "Estado"], "nrows": 3, "statuscol": true}, {"type": "panel", "col": 8, "colspan": 4, "y": 468, "h": 128, "label": "Bóveda de credenciales JIT", "meta": "acceso just-in-time · sesión grabada", "reqs": ["CYB-20", "DAT-14"], "subs": ["Solicitud → aprobación por tiempo limitado", "Sesión completa grabada (DAT-14)", "Historial: usuario · recurso · duración · acciones"]}, {"type": "table", "col": 0, "colspan": 4, "y": 610, "h": 128, "label": "Incidentes de seguridad", "meta": "CTA: 'Notificar a PASA' — informe de brecha en < 24h (CYB-16)", "reqs": ["CYB-16", "PRI-02"], "cols": ["Fecha", "Tipo", "Estado"], "nrows": 3, "statuscol": true}, {"type": "panel", "col": 4, "colspan": 4, "y": 610, "h": 128, "label": "Estado del BCP / DRP", "meta": "alerta si prueba > 6 meses", "reqs": ["CYB-11", "DAT-13"], "subs": ["Última prueba: 15-05 · resultado: exitoso", "Próxima prueba programada: 15-11", "Link al documento de DRP vigente"]}, {"type": "panel", "col": 8, "colspan": 4, "y": 610, "h": 128, "label": "Integridad de backups", "meta": "prueba semestral · alerta si > 6 meses", "reqs": ["CYB-23", "ARQ-11"], "subs": ["Última prueba de integridad: 20-04 ✓", "Tamaño validado · hash de verificación OK", "RTO < 4h · RPO < 1h (ARQ-11)"]}, {"type": "panel", "col": 0, "colspan": 4, "y": 752, "h": 128, "label": "Escaneo DAST", "meta": "último ciclo de escaneo dinámico", "reqs": ["CYB-07"], "subs": ["Interfaces: Portal / API / Webhooks", "Hallazgos: 0 críticos · 2 medios (en remediación)", "Historial de los últimos 12 ciclos"]}, {"type": "panel", "col": 4, "colspan": 4, "y": 752, "h": 128, "label": "Informe Pentest anual", "meta": "alerta si último Pentest > 12 meses", "reqs": ["CYB-08"], "subs": ["Último informe: 02-2026 · tercero independiente", "Hallazgos críticos: 0 · altos: 1 (remediado)", "Empresa auditora registrada"]}, {"type": "panel", "col": 8, "colspan": 4, "y": 752, "h": 128, "label": "Borrado criptográfico", "meta": "CTA DESTRUCTIVA: 'Ejecutar borrado' — al término del contrato · genera acta", "reqs": ["CYB-12", "DAT-07"], "subs": ["Lista de activos a borrar · estado por activo", "Hash de verificación post-borrado", "Acta generada para PASA (irreversible)"]}], "detail": {"descripcion": "Panel único de postura de seguridad y gestión de accesos privilegiados del proveedor, agrupado en tres bandas de afinidad para reducir la carga cognitiva de una pantalla muy densa: (1) Estado de seguridad — vulnerabilidades, certificados TLS, cifrado en reposo, WAF/DDoS/IDS-IPS, hardening CIS, inventario SBOM y EDR; (2) PAM — cuentas privilegiadas y bóveda de credenciales JIT; (3) Incidentes y continuidad — incidentes de seguridad con notificación de brechas en menos de 24h, BCP/DRP, integridad de backups, DAST, Pentest anual y borrado criptográfico. Las acciones críticas y destructivas se resaltan y quedan auditadas.", "componentes": [{"nombre": "Resumen de vulnerabilidades", "descripcion": "Vulnerabilidades abiertas por severidad (crítica/alta/media/baja), parches pendientes con fecha límite (críticas ≤ 30 días), fecha del último scan y % de componentes con parche vigente.", "reqs": ["CYB-13", "CYB-18"]}, {"nombre": "Certificados TLS", "descripcion": "Tabla de certificados por servicio: dominio, fecha de expiración, días restantes y estado (válido/por vencer/vencido). Alerta automática a 30 y 7 días del vencimiento.", "reqs": ["CYB-04", "INT-04"]}, {"nombre": "Estado de cifrado en reposo", "descripcion": "Indicador por componente (base de datos, backups, almacenamiento de archivos): cifrado AES-256 activo (sí/no), última verificación y responsable. Alerta si algún componente pierde el cifrado.", "reqs": ["CYB-05"]}, {"nombre": "Estado de WAF / DDoS / IDS-IPS", "descripcion": "Semáforo por servicio de protección perimetral: WAF activo, protección DDoS activa, IDS/IPS activo y monitoreado 24x7. Última alerta detectada por cada sistema.", "reqs": ["CYB-09", "CYB-22"]}, {"nombre": "Hardening — cumplimiento CIS Benchmarks", "descripcion": "% de cumplimiento del benchmark CIS por componente (servidor, BD). Última auditoría de hardening. Hallazgos abiertos con criticidad y ETA de remediación.", "reqs": ["CYB-17"]}, {"nombre": "Inventario de componentes HW/SW (SBOM)", "descripcion": "Tabla de todos los componentes tecnológicos: nombre, versión, fabricante, fecha de EOL y estado de soporte. Exportable a PASA. Alerta si algún componente entra en EOL en los próximos 90 días.", "reqs": ["CYB-19", "ARQ-20"]}, {"nombre": "EDR y antivirus", "descripcion": "Estado de cobertura de EDR por componente: activo/inactivo, fecha de última actualización de firmas y última detección. Alerta si algún componente lleva más de 24h sin actualización.", "reqs": ["CYB-14"]}, {"nombre": "Lista de cuentas privilegiadas (PAM)", "descripcion": "Usuario, rol, fecha de última revisión, próxima revisión programada y estado (activo/suspendido/en revisión). Revisión mensual obligatoria con registro de justificación de uso.", "reqs": ["CYB-20", "CYB-03", "DAT-14"]}, {"nombre": "Bóveda de credenciales JIT", "descripcion": "Acceso just-in-time: el técnico solicita acceso, se aprueba por tiempo limitado y se graba la sesión completa. Historial de uso: usuario, recurso accedido, duración y acciones realizadas.", "reqs": ["CYB-20", "DAT-14"]}, {"nombre": "Lista de incidentes de seguridad", "descripcion": "Incidentes abiertos: fecha de detección, tipo, severidad, estado y responsable. Botón 'Notificar a PASA' que genera y envía el informe de brecha en formato estándar en menos de 24h desde la detección.", "reqs": ["CYB-16", "PRI-02"]}, {"nombre": "Estado del BCP / DRP", "descripcion": "Última prueba realizada, resultado (exitoso/con observaciones), próxima prueba programada y link al documento de DRP vigente. Alerta si la prueba lleva más de 6 meses sin realizarse.", "reqs": ["CYB-11", "DAT-13"]}, {"nombre": "Integridad de backups", "descripcion": "Registro de pruebas de integridad de backups (semestral mínimo): fecha, resultado, tamaño validado y hash de verificación. Alerta si el último backup validado tiene más de 6 meses.", "reqs": ["CYB-23", "ARQ-11"]}, {"nombre": "Escaneo DAST", "descripcion": "Resultado del último ciclo de escaneo dinámico: fecha, interfaces escaneadas (Portal/API/Webhooks), hallazgos por severidad y estado de remediación. Historial de los últimos 12 ciclos.", "reqs": ["CYB-07"]}, {"nombre": "Informe Pentest anual", "descripcion": "Registro del último informe de Pentest/Ethical Hacking por tercero: fecha, empresa auditora, hallazgos críticos y estado de remediación. Alerta si el último Pentest tiene más de 12 meses.", "reqs": ["CYB-08"]}, {"nombre": "Borrado criptográfico", "descripcion": "Herramienta de borrado criptográfico al término del contrato: lista de activos a borrar, estado, hash de verificación post-borrado y acta generada.", "reqs": ["CYB-12", "DAT-07"]}], "filtros": [], "ux": [{"componente": "Tres bandas de afinidad en una grilla densa uniforme", "texto": "Los quince sub-paneles se organizan en bandas horizontales — estado de seguridad, PAM y continuidad — con bloques de igual altura y ancho, de modo que el administrador escanea cada dominio como una unidad en vez de enfrentar una nube de indicadores. Agrupar por afinidad y estandarizar el tamaño convierte una pantalla saturada en algo recorrible.", "principio": "Agrupación por afinidad y ley de proximidad (Gestalt); reducción de carga cognitiva en alta densidad."}, {"componente": "Semáforo homogéneo como lenguaje común de toda la pantalla", "texto": "Cada panel expone su condición con el mismo código de estado, para que el ojo detecte el único bloque en rojo entre catorce en verde sin leer texto. En un tablero de seguridad con tantos frentes, un lenguaje visual único es lo que permite encontrar el problema en segundos.", "principio": "Consistencia de codificación; detección pre-atenta de la excepción."}, {"componente": "'Notificar a PASA' resaltado en el bloque de incidentes", "texto": "La acción que dispara el informe de brecha en menos de 24h se destaca en el panel de incidentes con su plazo explícito, porque es la obligación contractual más sensible al tiempo de todo el perfil. Anclar la acción a su ventana de 24h evita que el operador subestime la urgencia regulatoria.", "principio": "Visibilidad de la acción crítica; el plazo forma parte del control."}, {"componente": "'Ejecutar borrado' marcado como destructivo e irreversible", "texto": "El borrado criptográfico advierte en su meta que es una acción destructiva que genera un acta y no tiene retorno; su ejecución exige aprobación y confirmación. Rotular la irreversibilidad junto al botón es la última barrera contra un borrado accidental de datos al cierre de contrato.", "principio": "Prevención de errores catastróficos; confirmación explícita ante acción irreversible."}, {"componente": "Alertas de caducidad temporal embebidas en cada panel", "texto": "Certificados TLS, Pentest, BCP/DRP e integridad de backups muestran su cuenta regresiva o su umbral de antigüedad dentro del propio bloque, para que el administrador vea qué control está por vencer sin abrir cada módulo. Situar el vencimiento junto al estado transforma la vigilancia en una lectura pasiva.", "principio": "Visibilidad del estado del sistema; anticipación en vez de reacción."}, {"componente": "Bóveda JIT y PAM contiguos como flujo de acceso privilegiado", "texto": "La lista de cuentas privilegiadas y la bóveda de acceso just-in-time se colocan juntas porque describen el mismo ciclo: quién tiene privilegio permanente y cómo se concede el temporal con sesión grabada. Reunir ambos evita que el administrador razone el control de accesos privilegiados en dos lugares distintos.", "principio": "Continuidad del modelo mental; agrupar los pasos de un mismo proceso."}]}}, {"id": "7.7", "slug": "replica-datos", "profile": "super-admin", "device": "desktop", "title": "Réplica y datos", "activeMenu": "Réplica y datos", "subtitle": "BD de réplica read-only NRT en AWS · notificación de cambios de esquema a PASA con 30 días de anticipación (DAT-13) · contratos de datos versionados (DAT-25)", "filters": [], "blocks": [{"type": "panel", "col": 0, "colspan": 4, "y": 184, "h": 180, "label": "Estado de la réplica (NRT)", "meta": "alerta si el lag supera el umbral (> 5 min)", "reqs": ["DAT-01", "DAT-26"], "subs": ["Sincronización: activa ✓", "Lag actual: 42 s (umbral 300 s)", "Última réplica exitosa: 10-07 09:15:22", "Volumen replicado 24h: 214 GB"]}, {"type": "histogram", "col": 4, "colspan": 8, "y": 184, "h": 180, "label": "Histograma de lag de réplica", "meta": "lag en segundos · últimas 24h / 7 días", "reqs": ["DAT-01", "DAT-26"], "threshold": 0.7}, {"type": "table", "col": 0, "colspan": 6, "y": 380, "h": 230, "label": "Acceso a réplica por tenant / proceso ETL de PASA", "meta": "gestión de acceso con revocación individual (auditada)", "reqs": ["DAT-01", "CYB-03", "DAT-14"], "cols": ["Usuario", "Tenant / proceso", "Permisos", "Última conexión", "Vol. consultado"], "nrows": 5, "statuscol": true}, {"type": "table", "col": 6, "colspan": 6, "y": 380, "h": 230, "label": "Monitor de cambios de esquema", "meta": "badge rojo si el plazo de aviso de 30 días no se cumple (DAT-13)", "reqs": ["DAT-13", "DAT-25"], "cols": ["Tabla / endpoint", "Tipo de cambio", "Detección", "Despliegue", "Notif. PASA"], "nrows": 5, "statuscol": true, "expand": true}, {"type": "table", "col": 0, "colspan": 8, "y": 626, "h": 210, "label": "Contratos de datos versionados", "meta": "backward compatibility · deprecación de versiones antiguas (INT-06)", "reqs": ["DAT-25", "INT-06"], "cols": ["Integración", "Versión actual", "Versiones soportadas", "Esquema", "Deprecación"], "nrows": 5}, {"type": "panel", "col": 8, "colspan": 4, "y": 626, "h": 150, "label": "Alerta de anticipación de 30 días", "meta": "aviso formal a PASA por cambio de esquema (DAT-13)", "reqs": ["DAT-13"], "subs": ["2 cambios detectados sin notificar", "1 incumple el plazo de 30 días (badge rojo)", "Calcula si el despliegue respeta el aviso"]}, {"type": "actions", "col": 8, "colspan": 4, "y": 790, "h": 40, "btns": ["Notificar a PASA ahora"]}], "detail": {"descripcion": "Gestión de la base de datos de réplica read-only en AWS con sincronización NRT (DAT-01) y de los contratos de datos versionados que PASA consume en sus procesos ETL (DAT-25). Incluye el estado y el lag de la réplica, el control de acceso por tenant/proceso, el monitor de cambios de esquema con el cálculo del aviso de 30 días de anticipación a PASA (DAT-13) y el catálogo de contratos con su política de compatibilidad hacia atrás (INT-06).", "componentes": [{"nombre": "Panel de estado de réplica", "descripcion": "Estado de sincronización NRT (activa/degradada/detenida), lag actual [segundos], timestamp de la última réplica exitosa y volumen replicado en 24h. Alerta si el lag supera el umbral configurado.", "reqs": ["DAT-01", "DAT-26"]}, {"nombre": "Histograma de lag de réplica", "descripcion": "Gráfico del lag en segundos durante las últimas 24h/7 días. Permite identificar degradaciones periódicas o picos de carga que afectan la sincronización.", "reqs": ["DAT-01", "DAT-26"]}, {"nombre": "Acceso a réplica por tenant", "descripcion": "Tabla de credenciales de acceso a la réplica read-only por tenant/proceso ETL de PASA: usuario, permisos, última conexión y volumen consultado. Gestión de acceso con revocación individual.", "reqs": ["DAT-01", "CYB-03", "DAT-14"]}, {"nombre": "Monitor de cambios de esquema", "descripcion": "Detecta automáticamente cambios en la estructura de tablas de la réplica o la API. Lista los cambios pendientes de notificar a PASA con tabla/endpoint afectado, tipo de cambio, fecha de detección, fecha planificada de despliegue y estado de notificación (pendiente/enviada/confirmada).", "reqs": ["DAT-13", "DAT-25"]}, {"nombre": "Alerta de anticipación de 30 días", "descripcion": "Para cada cambio de esquema detectado calcula si el despliegue planificado respeta el aviso de 30 días a PASA. Badge rojo si el plazo no se cumple. Botón 'Notificar a PASA ahora' que genera el aviso formal.", "reqs": ["DAT-13"]}, {"nombre": "Contratos de datos versionados", "descripcion": "Catálogo de contratos activos: nombre de la integración (API/réplica/webhook/archivo), versión actual, versiones anteriores soportadas, esquema (campos, tipos, validaciones), política de compatibilidad hacia atrás y fecha de deprecación de versiones antiguas.", "reqs": ["DAT-25", "INT-06"]}], "filtros": [], "ux": [{"componente": "Estado de réplica y lag emparejados con su histograma", "texto": "El indicador de lag actual se coloca junto al histograma de su evolución para que el administrador distinga un pico puntual de una degradación sostenida en la misma mirada. Un número solo no dice si el problema es transitorio; la serie contigua le da esa lectura.", "principio": "Dato puntual junto a su tendencia; contexto para interpretar el valor."}, {"componente": "Cálculo automático del plazo de 30 días con badge", "texto": "El sistema no deja al administrador contar días: calcula si el despliegue de cada cambio de esquema respeta el aviso de 30 días a PASA y marca en rojo el que lo incumple. Automatizar el cómputo del plazo previene el error de notificar tarde una obligación contractual.", "principio": "Prevención de errores por cálculo manual; el sistema vigila el compromiso."}, {"componente": "Botón 'Notificar a PASA ahora' contiguo a la alerta", "texto": "La acción de emitir el aviso formal se ubica junto al panel que detecta el incumplimiento del plazo, para que la respuesta al riesgo sea inmediata y en el mismo lugar donde se descubre. Acercar la solución al problema reduce la latencia entre detectar y actuar.", "principio": "Proximidad problema-acción; minimizar el costo de la respuesta correcta."}, {"componente": "Acceso a la réplica con revocación individual auditada", "texto": "La tabla de accesos por tenant/proceso ETL permite revocar credenciales una a una en lugar de en bloque, porque cortar el acceso ETL de PASA de forma masiva interrumpiría procesos legítimos. La granularidad de la revocación protege la operación del cliente mientras se mantiene el control.", "principio": "Control de grano fino en operaciones sensibles; evitar el daño colateral."}, {"componente": "Contratos versionados como catálogo con deprecación visible", "texto": "El catálogo muestra versión actual, versiones aún soportadas y fecha de deprecación en columnas, de modo que el administrador comunica a PASA hasta cuándo funciona cada versión sin abrir documentación externa. Exponer el calendario de compatibilidad hace explícito el compromiso de backward compatibility.", "principio": "Transparencia del ciclo de vida; el compromiso de compatibilidad a la vista."}]}}, {"id": "7.8", "slug": "slos-datos", "profile": "super-admin", "device": "desktop", "title": "SLOs de datos", "activeMenu": "SLOs de datos", "subtitle": "Niveles de servicio para datos críticos — frescura, completitud, disponibilidad, unicidad y recuperación — diferenciados del SLA de infraestructura · latencia de API p95 < 500 ms (INT-08)", "filters": [{"name": "Dimensión", "default": "Todas"}, {"name": "Tenant / mall", "default": "Todos"}, {"name": "Período", "default": "Últimas 24h"}, {"name": "Estado", "default": "Todos"}], "blocks": [{"type": "table", "col": 0, "colspan": 7, "y": 184, "h": 250, "label": "SLOs por dimensión de dato", "meta": "objetivo vs. actual · estado (cumple/incumple) · tendencia 7 días", "reqs": ["DAT-26"], "cols": ["Dimensión", "Objetivo", "Actual", "Estado", "Tend. 7d"], "nrows": 5, "statuscol": true}, {"type": "line", "col": 7, "colspan": 5, "y": 184, "h": 250, "label": "SLO de latencia de API — p95", "meta": "umbral contractual 500 ms · badge rojo si lo supera (INT-08)", "reqs": ["INT-08", "DAT-26"], "threshold": 0.8}, {"type": "table", "col": 0, "colspan": 7, "y": 450, "h": 300, "label": "Historial de incumplimientos de SLO", "meta": "causa raíz registrada · exportable para revisión con PASA", "reqs": ["DAT-26", "FIN-06", "DAT-14"], "cols": ["Dimensión", "Período", "Objetivo", "Valor real", "Causa raíz", "Acción"], "nrows": 6, "statuscol": true, "expand": true}, {"type": "form", "col": 7, "colspan": 5, "y": 450, "h": 300, "label": "Configurador de SLOs", "meta": "los valores no pueden bajar de los mínimos contractuales · cada cambio auditado", "reqs": ["DAT-26"], "fields": ["Dimensión de dato a configurar", "Tipo de dato (medidor crítico / contexto)", "Valor objetivo", "Ventana de evaluación", "Umbral de alerta"]}], "detail": {"descripcion": "Panel diferenciado de niveles de servicio (SLOs) para datos críticos, separado del SLA de infraestructura y aplicación. La plataforma compromete SLOs específicos para frescura, completitud, disponibilidad, unicidad operativa y tiempo máximo de recuperación de datasets (DAT-26), más un indicador dedicado de latencia de API en el percentil 95 con umbral contractual de 500 ms (INT-08). Incluye historial de incumplimientos exportable y un configurador que no permite bajar de los mínimos contractuales.", "componentes": [{"nombre": "Tabla de SLOs por dimensión de dato", "descripcion": "Una fila por dimensión: Frescura [min desde última lectura], Completitud [% recibidas vs. esperadas], Disponibilidad de datos [%], Unicidad operativa [% sin duplicados] y Tiempo de recuperación de dataset [min]. Para cada una: valor objetivo, valor actual, estado (cumple/incumple) y tendencia 7 días.", "reqs": ["DAT-26"]}, {"nombre": "SLO de latencia de API (p95 < 500 ms)", "descripcion": "Indicador del percentil 95 del tiempo de respuesta de la API de datos. Umbral contractual 500 ms. Valor actual en tiempo real y gráfico de evolución del p95 en los últimos 7 días. Badge rojo si supera el umbral.", "reqs": ["INT-08", "DAT-26"]}, {"nombre": "Historial de incumplimientos de SLO", "descripcion": "Tabla de períodos en que algún SLO fue incumplido: dimensión afectada, período, valor objetivo, valor real, causa raíz registrada y acción tomada. Exportable para revisión con PASA.", "reqs": ["DAT-26", "FIN-06", "DAT-14"]}, {"nombre": "Configurador de SLOs", "descripcion": "Permite ajustar los valores objetivo por SLO y por tipo de dato (datos de medidores críticos vs. datos de contexto). Cada cambio queda registrado con usuario y timestamp. Los valores no pueden bajar de los mínimos contractuales.", "reqs": ["DAT-26"]}], "filtros": [{"nombre": "Dimensión", "opciones": "Frescura / Completitud / Disponibilidad / Unicidad / Tiempo de recuperación / Latencia API / Todas", "default": "Todas"}, {"nombre": "Tenant / mall", "opciones": "Multi-selección con buscador", "default": "Todos"}, {"nombre": "Período", "opciones": "Tiempo real / Últimas 24h / 7 días / 30 días", "default": "Últimas 24h"}, {"nombre": "Estado", "opciones": "Todos / Solo incumplidos / Solo en riesgo", "default": "Todos"}], "ux": [{"componente": "Tabla de SLOs con objetivo y actual en columnas contiguas", "texto": "Cada dimensión muestra su valor objetivo junto al valor actual y el estado, de modo que el administrador juzga el cumplimiento comparando dos cifras adyacentes en vez de recordar el umbral. Poner el compromiso al lado del dato real elimina el paso mental de buscar contra qué se mide.", "principio": "Comparación en contexto; reducir la carga de memoria del umbral."}, {"componente": "SLO de latencia p95 con línea de umbral dibujada", "texto": "El gráfico del p95 traza la línea de 500 ms para que cualquier punto por encima sea visible sin leer valores, y el badge rojo confirma el incumplimiento. Materializar el umbral contractual sobre la serie convierte el SLO en una lectura binaria de cumple/no cumple.", "principio": "Umbral visible sobre la serie; juicio inmediato de cumplimiento."}, {"componente": "Configurador que bloquea bajar del mínimo contractual", "texto": "El formulario de ajuste de objetivos impide fijar un valor por debajo del piso pactado con PASA; el propio control es la barrera. Restringir el rango editable previene que, con máximo privilegio, se relaje un compromiso contractual por error o descuido.", "principio": "Prevención de errores por restricción del rango; el límite vive en el control."}, {"componente": "Historial de incumplimientos con causa raíz y exportable", "texto": "Cada incumplimiento registra su causa raíz y acción tomada y es exportable, porque la conversación con PASA no es sobre el número aislado sino sobre por qué ocurrió y qué se hizo. Estructurar la evidencia para la revisión externa hace la rendición de cuentas verificable.", "principio": "Trazabilidad orientada a la auditoría externa; el dato acompañado de su explicación."}, {"componente": "Filtros declarados por dimensión, tenant, período y estado", "texto": "Esta pantalla sí expone filtros porque el administrador alterna entre revisar una dimensión concreta, un tenant o solo lo incumplido; ubicarlos en la barra superior estándar mantiene el patrón del resto del perfil y evita reconstruir la vista manualmente. La consistencia del lugar del filtro reduce el costo de aprenderlo.", "principio": "Consistencia entre pantallas; filtrado como reducción del espacio de búsqueda."}, {"componente": "Datos críticos separados del SLA de infraestructura", "texto": "El subtítulo insiste en que estos SLOs son distintos del uptime de infraestructura, para que el administrador no confunda 'la plataforma está arriba' con 'los datos son frescos y completos'. Diferenciar los dominios de servicio evita dar por cumplido un compromiso de datos mirando la salud del sistema.", "principio": "Distinción explícita de dominios; evitar la confusión entre disponibilidad y calidad de dato."}]}}, {"id": "7.9", "slug": "throttle-cargas", "profile": "super-admin", "device": "desktop", "title": "Throttle y cargas", "activeMenu": "Throttle y cargas", "subtitle": "Quotas de API documentadas para no bloquear los ETL de PASA (DAT-15) · whitelist de IPs exentas · cargas incrementales por cursor (DAT-21)", "filters": [], "blocks": [{"type": "table", "col": 0, "colspan": 7, "y": 184, "h": 240, "label": "Quotas de API por tenant", "meta": "alerta si un tenant supera el 80% de su cuota", "reqs": ["DAT-15"], "cols": ["Tenant", "Req/hora", "Req/día", "Consumo actual", "% uso", "Estado"], "nrows": 6, "statuscol": true}, {"type": "line", "col": 7, "colspan": 5, "y": 184, "h": 240, "label": "Consumo de API por tenant", "meta": "requests/hora 24h · línea horizontal en el límite configurado", "reqs": ["DAT-15", "DAT-09"], "threshold": 0.75}, {"type": "table", "col": 0, "colspan": 4, "y": 440, "h": 220, "label": "Log de eventos de throttling", "meta": "detecta falsos positivos que afecten ETL legítimos de PASA", "reqs": ["DAT-15", "DAT-14"], "cols": ["Tenant", "Endpoint", "Bloqueadas", "IP origen"], "nrows": 5}, {"type": "form", "col": 4, "colspan": 4, "y": 440, "h": 220, "label": "Configurador de quotas", "meta": "whitelist de IPs exentas · cambios auditados (usuario/timestamp)", "reqs": ["DAT-15", "CYB-03"], "fields": ["Tenant", "Límite requests/hora", "Límite requests/día", "Whitelist de IPs exentas (ETL PASA)"]}, {"type": "table", "col": 8, "colspan": 4, "y": 440, "h": 220, "label": "Estado de extracciones incrementales", "meta": "indicador si el cursor lleva > 4h sin avanzar (DAT-24)", "reqs": ["DAT-21", "DAT-24"], "cols": ["Integración", "Modo", "Cursor", "Últ. extracción"], "nrows": 5, "statuscol": true}, {"type": "form", "col": 0, "colspan": 6, "y": 676, "h": 180, "label": "Configurador de modo de extracción", "meta": "incremental / full-load · ventana de overlap para registros tardíos", "reqs": ["DAT-21"], "fields": ["Integración", "Modo (incremental / full-load)", "Columna de cursor (timestamp o ID)", "Ventana de overlap (ej. últimos 5 min)"]}, {"type": "table", "col": 6, "colspan": 6, "y": 676, "h": 180, "label": "Historial de extracciones", "meta": "últimas 100 por integración · audita eficiencia incremental vs. full-load", "reqs": ["DAT-21", "DAT-19"], "cols": ["Inicio", "Fin", "Modo", "Registros", "MB", "Resultado"], "nrows": 4, "statuscol": true}], "detail": {"descripcion": "Gestión de los límites de consumo de la API (throttle y quotas) y de la configuración de las extracciones incrementales por tenant. Los quotas están definidos y documentados para que los procesos ETL de PASA no sean bloqueados por rate limiting ni incurran en sobrecostos (DAT-15), con whitelist de IPs exentas y log de eventos para detectar falsos positivos. La sección de cargas soporta el modo incremental por cursor (DAT-21) con ventana de overlap para registros tardíos.", "componentes": [{"nombre": "Tabla de quotas por tenant", "descripcion": "Tenant, límite de requests/hora y /día, consumo actual (requests en la última hora y en el día), % de uso sobre la cuota y estado (normal/en riesgo/bloqueado). Alerta si algún tenant supera el 80% de su cuota.", "reqs": ["DAT-15"]}, {"nombre": "Gráfico de consumo de API por tenant", "descripcion": "Línea de requests/hora en las últimas 24h por tenant seleccionado, con línea horizontal en el límite configurado. Permite identificar picos que podrían activar el rate limiting.", "reqs": ["DAT-15", "DAT-09"]}, {"nombre": "Configurador de quotas", "descripcion": "Editar el límite de requests/hora y /día por tenant. Campo de whitelist de IPs exentas de rate limiting (para procesos ETL de PASA). Registro de cambios con usuario y timestamp.", "reqs": ["DAT-15", "CYB-03"]}, {"nombre": "Log de eventos de throttling", "descripcion": "Registro de cada activación del rate limiting: tenant, endpoint, timestamp, nº de requests bloqueadas e IP de origen. Exportable. Permite detectar falsos positivos que afecten procesos ETL legítimos de PASA.", "reqs": ["DAT-15", "DAT-14"]}, {"nombre": "Estado de extracciones incrementales por integración", "descripcion": "Integración, tipo (API/réplica/webhook), modo (incremental/full-load), cursor actual (última marca de tiempo o ID extraído), última extracción exitosa y nº de registros. Indicador si el cursor lleva más de 4h sin avanzar.", "reqs": ["DAT-21", "DAT-24"]}, {"nombre": "Configurador de modo de extracción", "descripcion": "Por integración: selector de modo (incremental / full-load). Para modo incremental: campo de cursor (columna de timestamp o ID incremental) y configuración de ventana de overlap (ej. últimos 5 min para cubrir registros tardíos).", "reqs": ["DAT-21"]}, {"nombre": "Historial de extracciones", "descripcion": "Log de las últimas 100 extracciones por integración: timestamp de inicio y fin, modo, nº de registros, tamaño [MB] y resultado (éxito/error/parcial). Permite auditar la eficiencia del modo incremental vs. full-load.", "reqs": ["DAT-21", "DAT-19"]}], "filtros": [], "ux": [{"componente": "% de uso y estado por tenant como semáforo de riesgo", "texto": "La tabla de quotas resalta el porcentaje de uso y marca 'en riesgo' al superar el 80%, para que el administrador intervenga antes de que un tenant crítico de PASA choque contra el rate limiting. Anticipar el bloqueo con un umbral de advertencia protege la continuidad de los ETL del cliente.", "principio": "Alerta temprana; actuar antes del fallo, no después."}, {"componente": "Gráfico de consumo con la línea del límite superpuesta", "texto": "El consumo por hora se dibuja contra la línea del límite configurado, de modo que un pico que se acerca al techo se ve venir. Mostrar el margen restante convierte una serie de tráfico en una herramienta de decisión sobre si ampliar la cuota.", "principio": "Umbral visible como referencia de decisión; margen a la vista."}, {"componente": "Whitelist de IPs de PASA en el configurador de quotas", "texto": "El configurador incluye un campo explícito de IPs exentas para los ETL de PASA, porque el objetivo del throttle no es frenar al cliente sino a los abusos externos. Hacer de la exención un control de primera clase evita que un límite genérico bloquee por error los procesos legítimos.", "principio": "El diseño refleja la intención real de la política; excepción legítima como control explícito."}, {"componente": "Log de throttling orientado a detectar falsos positivos", "texto": "El registro de bloqueos incluye endpoint e IP de origen para que el administrador distinga un ataque de un ETL legítimo mal calibrado. Estructurar el log en torno a esa pregunta hace que la evidencia sirva para corregir la quota, no solo para constatar el bloqueo.", "principio": "Datos orientados a la acción de corrección; el log responde una pregunta concreta."}, {"componente": "Cargas incrementales con indicador de cursor detenido", "texto": "El estado de extracciones marca cuándo un cursor lleva más de 4h sin avanzar, señal de que la carga incremental se estancó y PASA podría estar recibiendo datos incompletos. Vigilar el avance del cursor detecta un silencio de datos que un simple 'sin errores' ocultaría.", "principio": "Detección de fallo silencioso; ausencia de progreso como señal de alarma."}]}}, {"id": "7.10", "slug": "retencion-privacidad", "profile": "super-admin", "device": "desktop", "title": "Retención y privacidad", "activeMenu": "Retención y privacidad", "subtitle": "Políticas de retención, anonimización y eliminación diferenciadas por tipo de dato, país y finalidad (PRI-08) · minimización de campos por proceso (PRI-05) · la eliminación masiva requiere aprobación de PASA", "filters": [], "blocks": [{"type": "table", "col": 0, "colspan": 7, "y": 184, "h": 210, "label": "Catálogo de políticas de retención", "meta": "acción al vencimiento: anonimizar / eliminar / archivar · fila expandible", "reqs": ["PRI-08", "PRI-05"], "cols": ["Política", "Tipo de dato", "Retención", "Acción", "Estado"], "nrows": 5, "statuscol": true, "expand": true}, {"type": "table", "col": 0, "colspan": 7, "y": 410, "h": 170, "label": "Cola de ejecución de políticas", "meta": "GATE: la eliminación masiva requiere aprobación del rol PASA antes de ejecutar", "reqs": ["PRI-08", "CYB-12", "DAT-14"], "cols": ["Tipo de dato", "Registros", "Acción pendiente", "Fecha límite", "Responsable"], "nrows": 4, "statuscol": true}, {"type": "actions", "col": 0, "colspan": 7, "y": 590, "h": 40, "btns": ["Ejecutar borrado", "Enviar a aprobación PASA"]}, {"type": "heatmap", "col": 0, "colspan": 7, "y": 644, "h": 185, "label": "Configurador de campos por proceso y país", "meta": "obligatorio / opcional / no requerido / no permitido · cambios auditados (DAT-14)", "reqs": ["PRI-05", "DAT-14"], "cols": 8, "rowsn": 5}, {"type": "form", "col": 7, "colspan": 5, "y": 184, "h": 390, "label": "Formulario de nueva política", "meta": "minimización de datos por proceso, país y finalidad", "reqs": ["PRI-08", "PRI-05"], "fields": ["Tipo de dato", "País de aplicación (CL / PE / CO / Todos)", "Período de retención activa [años]", "Período de retención en archivo (si aplica)", "Acción al vencimiento (anonimizar / eliminar / archivar)", "Base legal (obligación / interés legítimo / consentimiento)", "Finalidad de uso (operativo / analítico / legal)", "Justificación de la política (texto libre)"]}, {"type": "actions", "col": 7, "colspan": 5, "y": 588, "h": 40, "btns": ["Guardar política", "Cancelar"]}, {"type": "table", "col": 7, "colspan": 5, "y": 644, "h": 185, "label": "Historial de ejecuciones de políticas", "meta": "inmutable · hash de verificación · usuario que aprobó", "reqs": ["PRI-08", "CYB-10", "DAT-14"], "cols": ["Política", "Fecha", "Registros", "Acción", "Aprobó"], "nrows": 4}], "detail": {"descripcion": "Configuración y ejecución de políticas de retención, anonimización y eliminación diferenciadas por tipo de dato, obligación legal, país, criticidad y finalidad de uso (PRI-08), junto con la minimización de datos que define qué campos son obligatorios, opcionales, no requeridos o no permitidos según proceso y país (PRI-05). La cola de ejecución exige aprobación del rol PASA antes de una eliminación masiva, y toda ejecución queda registrada de forma inmutable con hash de verificación.", "componentes": [{"nombre": "Catálogo de políticas de retención", "descripcion": "Tabla de políticas activas: nombre, tipo de dato (consumo eléctrico / dato de locatario / log de auditoría / dato personal / dato de configuración), país de aplicación, período de retención activa [años], acción al vencimiento (anonimizar/eliminar/archivar), base legal y estado (activa/pendiente/vencida).", "reqs": ["PRI-08", "PRI-05"]}, {"nombre": "Formulario de nueva política", "descripcion": "Tipo de dato, país de aplicación (Chile), período de retención activa, período de retención en archivo, acción al vencimiento, base legal (obligación legal / interés legítimo / consentimiento), finalidad de uso (operativo / analítico / legal) y justificación de la política.", "reqs": ["PRI-08", "PRI-05"]}, {"nombre": "Cola de ejecución de políticas", "descripcion": "Lista de políticas cuya fecha de vencimiento se acerca o ya se cumplió: tipo de dato, nº de registros afectados, acción pendiente (anonimizar/eliminar/archivar), fecha límite y responsable. Requiere aprobación del rol PASA antes de ejecutar una eliminación masiva.", "reqs": ["PRI-08", "CYB-12", "DAT-14"]}, {"nombre": "Configurador de campos por proceso y país", "descripcion": "Matriz de campos por proceso (ingesta de medidor / integración con locatario / exportación a Data Lake / etc.) y por país. Para cada celda: campo obligatorio / opcional / no requerido / no permitido. Los cambios requieren justificación y quedan en la pista de auditoría.", "reqs": ["PRI-05", "DAT-14"]}, {"nombre": "Historial de ejecuciones de políticas", "descripcion": "Log de cada ejecución: política, fecha, nº de registros procesados, acción ejecutada (anonimización/eliminación/archivo), hash de verificación y usuario que aprobó. Inmutable.", "reqs": ["PRI-08", "CYB-10", "DAT-14"]}], "filtros": [], "ux": [{"componente": "Catálogo a la izquierda y alta de política a la derecha", "texto": "El flujo natural es revisar qué políticas existen antes de crear una nueva, así que el catálogo ocupa el punto de entrada y el formulario de alta se sitúa a su derecha como paso siguiente. Ordenar 'consultar' antes de 'crear' evita duplicar políticas y refuerza el recorrido de lectura de izquierda a derecha.", "principio": "Flujo alineado al recorrido de lectura; consultar antes de crear."}, {"componente": "Cola de ejecución con gate de aprobación PASA visible", "texto": "Las políticas por vencer se listan con el número de registros afectados, y su meta advierte que una eliminación masiva exige aprobación del rol PASA antes de ejecutarse. Mostrar el alcance del borrado junto al gate frena la ejecución de una acción irreversible sin la autorización debida.", "principio": "Prevención de errores irreversibles; el alcance del daño y el gate a la vista."}, {"componente": "'Ejecutar borrado' y 'Enviar a aprobación' diferenciados", "texto": "Los dos botones de la cola separan la acción destructiva de la de solicitar autorización, de modo que el administrador no confunda ejecutar con tramitar. Distinguir la acción final de su antesala reduce el riesgo de disparar una eliminación creyendo que solo se pedía permiso.", "principio": "Jerarquía y separación de acciones; distinguir el trámite de la ejecución."}, {"componente": "Configurador de campos como matriz proceso × país", "texto": "La minimización de datos se opera en una matriz donde cada celda cruza un proceso con un país y marca si el campo es obligatorio, opcional, no requerido o no permitido; ver la rejilla completa permite detectar un dato exigido donde debería estar prohibido. La representación matricial hace visibles las inconsistencias de política entre países.", "principio": "Visualización matricial para detectar excepciones; la estructura revela el error."}, {"componente": "Historial de ejecuciones inmutable con quién aprobó", "texto": "Cada ejecución guarda el hash de verificación y el usuario que la aprobó, sin posibilidad de edición, porque la eliminación o anonimización de datos personales debe poder demostrarse ante PASA y ante la autoridad. Registrar la aprobación junto al resultado convierte la acción en evidencia de cumplimiento.", "principio": "Inmutabilidad y trazabilidad de aprobación; la ejecución como prueba legal."}, {"componente": "País y base legal como campos obligatorios de la política", "texto": "El formulario de alta exige país, base legal y finalidad antes de guardar, porque una misma clase de dato retiene distinto según jurisdicción y motivo. Forzar estos campos impide crear una política ambigua que luego se aplique mal según la jurisdicción o la finalidad.", "principio": "Restricciones que garantizan una política completa; prevención de configuración incompleta."}]}, "primaryAction": "Nueva política"}], "menus": {"gerencial": ["Panel consolidado", "Consumo jerárquico", "Costos y tendencias", "Reportes ejecutivos", "Alarmas agregadas", "Exportar reportes"], "operacional": ["Monitoreo en vivo", "Alarmas y eventos", "Tickets y SLA", "Calidad y backfill", "CNR pendientes", "Mapa de cobertura"], "tecnico": ["Mis órdenes", "Activos (medidores)", "Diagnóstico comms", "Registro de intervención", "Ingreso CNR manual", "Maestro de medidores", "Reglas de transformación"], "auditor": ["Calidad de datos", "Cuadratura de agregación", "Pista de auditoría", "Trazabilidad / lineage", "Datos crudos (raw)", "Exportar evidencia"], "super-admin": ["Tenants y malls", "Config y releases", "Usuarios y roles", "Observabilidad", "Integraciones", "Seguridad y PAM", "Réplica y datos", "SLOs de datos", "Throttle y cargas", "Retención y privacidad"]}, "labels": {"gerencial": "Gerencial", "operacional": "Operacional", "tecnico": "Técnico", "auditor": "Auditor", "super-admin": "Súper-admin"}, "auth": {"gerencial": "Solo lectura · sin MFA", "operacional": "MFA obligatorio · escritura alarmas/tickets", "tecnico": "MFA obligatorio · escritura terreno", "auditor": "MFA obligatorio · solo lectura", "super-admin": "Federado + MFA + JIT · máx. privilegio"}, "order": ["gerencial", "operacional", "tecnico", "auditor", "super-admin"]};
